import { useEffect } from 'react';

/**
 * Application keyboard shortcuts.
 *
 * Two rules decide the whole bindings table:
 *
 * 1. **Never fight the browser.** `Ctrl+N`, `Ctrl+T`, `Ctrl+W` and `Ctrl+Shift+R` cannot be
 *    intercepted in a normal tab, so binding them would produce a shortcut that works on one
 *    browser and opens a window on another. Anything this app claims, it can actually have.
 * 2. **Never eat a keystroke meant for the text.** A shortcut with no modifier is ignored while
 *    the caret is in an input, a textarea or the editor — a person writing a note who types `n`
 *    must get an `n`.
 */

export interface Shortcut {
  /** A single printable key, or a named key such as `Escape`. Compared case-insensitively. */
  readonly key: string;
  /** Ctrl on Windows/Linux, Cmd on macOS. */
  readonly mod?: boolean;
  readonly shift?: boolean;
  readonly alt?: boolean;
  /** Fires even while typing. Only `mod`-prefixed shortcuts should set this. */
  readonly whileTyping?: boolean;
  readonly run: () => void;
  /** For the shortcuts list in the command palette. */
  readonly label: string;
}

/** `⌘K` on a Mac, `Ctrl+K` everywhere else — for rendering, not for matching. */
export function describeShortcut(shortcut: Shortcut): string {
  const mac = /mac|iphone|ipad/i.test(globalThis.navigator?.userAgent ?? '');
  const parts: string[] = [];
  if (shortcut.mod === true) parts.push(mac ? '⌘' : 'Ctrl');
  if (shortcut.alt === true) parts.push(mac ? '⌥' : 'Alt');
  if (shortcut.shift === true) parts.push(mac ? '⇧' : 'Shift');
  parts.push(shortcut.key.length === 1 ? shortcut.key.toUpperCase() : shortcut.key);
  return parts.join(mac ? '' : '+');
}

function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  if (target.isContentEditable) {
    return true;
  }
  const tag = target.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
}

export function useShortcuts(shortcuts: readonly Shortcut[]): void {
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent): void {
      const mod = event.ctrlKey || event.metaKey;
      const typing = isTyping(event.target);

      for (const shortcut of shortcuts) {
        if (event.key.toLowerCase() !== shortcut.key.toLowerCase()) continue;
        if ((shortcut.mod ?? false) !== mod) continue;
        if ((shortcut.shift ?? false) !== event.shiftKey) continue;
        if ((shortcut.alt ?? false) !== event.altKey) continue;
        if (typing && shortcut.whileTyping !== true) continue;

        event.preventDefault();
        shortcut.run();
        return;
      }
    }

    globalThis.addEventListener('keydown', onKeyDown);
    return () => globalThis.removeEventListener('keydown', onKeyDown);
  }, [shortcuts]);
}
