import type { DragEvent, KeyboardEvent, MouseEvent, PointerEvent, ReactNode } from 'react';
import { useRef } from 'react';
import { Icon } from './icons';
import type { RowSelection } from './selection-context';

/**
 * The rail: one hairline down the left of every list, with beads on it.
 *
 * This is the product's signature element and the only decorative-looking thing in it that is not
 * decoration. Because every row's status sits on one vertical line at a fixed x-position, forty
 * dream entries can be scanned for which ones are locked without reading a single word — which is
 * the acceptance test from the brief, answered by the signature element rather than by a badge
 * bolted on somewhere.
 *
 * Four marks, and each is paired with a word elsewhere in the row so none of them is colour
 * alone:
 *
 * | Mark | Means | Also says |
 * |---|---|---|
 * | a branch crossing the rail | a group | serif title, subgroup/note counts |
 * | a filled bead | unread | a counted chip |
 * | a brass lock | private | the word "Private", and a filled lock button |
 * | a ring | currently open | the row is tinted |
 */

export type RowMark = 'none' | 'group' | 'unread' | 'private' | 'open';

const MARK_CLASS: Record<RowMark, string> = {
  none: 'mark',
  group: 'mark m-group',
  unread: 'mark m-unread',
  private: 'mark m-private',
  open: 'mark m-open',
};

export function Mark({ mark }: { readonly mark: RowMark }): React.JSX.Element {
  if (mark === 'private') {
    return (
      <span className={MARK_CLASS.private} title="Private">
        <i>
          <Icon name="lock" />
        </i>
      </span>
    );
  }
  return (
    <span className={MARK_CLASS[mark]} title={mark === 'unread' ? 'New' : undefined}>
      <i />
    </span>
  );
}

/**
 * The tickbox, drawn **in the rail** rather than beside it.
 *
 * Selection gets no column of its own. The rail is the one vertical line every row's status
 * already sits on, so the tickbox takes the bead's place there: nothing shifts sideways when a
 * selection starts, and a list mid-selection is still the same list at the same width. It is a
 * real `<input type="checkbox">` because a screen reader needs to hear "checkbox, not checked",
 * and a `div` with `role="checkbox"` inside a `role="button"` row announces as neither.
 */
function Pick({
  mark,
  select,
  label,
}: {
  readonly mark: RowMark;
  readonly select: RowSelection;
  readonly label: string;
}): React.JSX.Element {
  return (
    <span className="mark pick">
      <input
        aria-label={`Select ${label}`}
        checked={select.selected}
        className="pick-box"
        onChange={() => select.onPress('toggle')}
        onClick={(event) => {
          // The row underneath is a click target too; ticking a box must not also open the note.
          event.stopPropagation();
        }}
        type="checkbox"
      />
      <span aria-hidden="true" className="pick-bead">
        <Mark mark={mark} />
      </span>
    </span>
  );
}

export interface ListProps {
  readonly children: ReactNode;
  /** Drop the hairline. Used where a list is a single "add" affordance and has nothing to line up. */
  readonly noRail?: boolean;
  readonly label?: string;
}

/**
 * A real `<ul>`, with each row a real `<li>`.
 *
 * The rail is drawn on the list's own `::before`, so the semantics cost nothing visually and buy
 * the thing a labelled div could not: a screen reader announcing "list, 5 items" before the rows,
 * which is the audible equivalent of what the rail does for the eye.
 */
export function List({ children, noRail = false, label }: ListProps): React.JSX.Element {
  return (
    <ul aria-label={label} className={noRail ? 'list no-rail' : 'list'}>
      {children}
    </ul>
  );
}

export interface RowProps {
  readonly mark: RowMark;
  readonly title: ReactNode;
  readonly meta?: ReactNode;
  readonly excerpt?: ReactNode;
  readonly trailing?: ReactNode;
  readonly onOpen: () => void;
  readonly kind?: 'group' | 'note' | 'plain';
  readonly open?: boolean;
  /** The group's colour, when it owns one, so its rail and beads read in it. */
  readonly accent?: string | null;
  readonly icon?: ReactNode;
  /** The accessible name, when the visible title is not a plain string. */
  readonly label?: string;
  /**
   * Makes the row selectable. Absent means it is not — the trash and the templates list have
   * no bulk actions behind them, and a tickbox that leads nowhere is worse than no tickbox.
   */
  readonly select?: RowSelection | undefined;
  /** Makes the row somewhere a dragged selection can be dropped. Group rows, in practice. */
  readonly onDropSelection?: (() => void) | undefined;
  /**
   * Opens the right-click menu at a point.
   *
   * Right-click used to tick the row for multi-select. That was a reasonable guess and is not what
   * a right-click means to anybody — Rose asked for a menu, so the menu is what it does now, with
   * "Select" as one of its items so nothing is lost.
   */
  readonly onMenu?: ((at: { x: number; y: number }) => void) | undefined;
}

/** How long a finger rests on a row before it counts as "select this", in milliseconds. */
const LONG_PRESS_MS = 450;

/**
 * One row: rail bead, title and meta, trailing control.
 *
 * A `div` with `role="button"` rather than a `<button>`, because the trailing control is often
 * itself a button — a lock toggle — and a button inside a button is invalid and behaves
 * differently in every browser. The keyboard contract is honoured by hand instead: Enter and
 * Space both open, exactly as a button would.
 */
export function Row({
  mark,
  title,
  meta,
  excerpt,
  trailing,
  onOpen,
  kind = 'note',
  open = false,
  accent,
  icon,
  label,
  select,
  onDropSelection,
  onMenu,
}: RowProps): React.JSX.Element {
  /*
   * Set by a long press, and read by the click that follows it.
   *
   * A press-and-hold on a touchscreen also produces a `click` when the finger lifts. Without
   * this, holding a row selects it and the click immediately deselects it — the row flashes and
   * nothing happens, which is precisely the bug report "long press does nothing".
   */
  const consumed = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const classes = ['row'];
  if (kind === 'group') classes.push('is-group');
  if (kind === 'note') classes.push('is-note');
  if (open) classes.push('is-open');
  if (select?.selected === true) classes.push('is-picked');
  if (select?.anySelected === true) classes.push('is-picking');

  function cancelPress(): void {
    if (timer.current !== null) {
      clearTimeout(timer.current);
      timer.current = null;
    }
  }

  function onPointerDown(event: PointerEvent<HTMLDivElement>): void {
    // Touch only. A mouse has Ctrl and Shift; holding a mouse button still on a row is not a
    // gesture anybody makes on purpose, and treating it as one makes slow clicks behave oddly.
    if (select === undefined || event.pointerType === 'mouse') return;
    consumed.current = false;
    cancelPress();
    timer.current = setTimeout(() => {
      consumed.current = true;
      select.onPress('toggle');
    }, LONG_PRESS_MS);
  }

  function onClick(event: MouseEvent<HTMLDivElement>): void {
    if (consumed.current) {
      consumed.current = false;
      return;
    }
    if (select !== undefined) {
      const intent = select.intentFor(event);
      if (intent !== 'open') {
        // A shift-click also paints a browser text selection across everything it spans, which
        // looks like a rendering fault sitting on top of the rows it just ticked.
        globalThis.getSelection?.()?.removeAllRanges();
        select.onPress(intent);
        return;
      }
    }
    onOpen();
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>): void {
    // Ctrl/Cmd-Enter ticks the row without opening it: the keyboard's Ctrl-click, and the only
    // way to build a selection with no pointing device at all.
    if (event.key === 'Enter' && (event.ctrlKey || event.metaKey) && select !== undefined) {
      event.preventDefault();
      select.onPress('toggle');
      return;
    }
    // What a keyboard sends for "context menu". Without these the menu is a mouse-only feature,
    // which would put rename, move and delete out of reach of anybody not using a pointer.
    if (
      onMenu !== undefined &&
      (event.key === 'ContextMenu' || (event.key === 'F10' && event.shiftKey))
    ) {
      event.preventDefault();
      const box = event.currentTarget.getBoundingClientRect();
      onMenu({ x: box.left + 24, y: box.bottom - 4 });
      return;
    }
    if (event.key !== 'Enter' && event.key !== ' ') return;
    // Space scrolls the page by default, which is exactly wrong on a row you meant to open.
    event.preventDefault();
    if (event.key === ' ' && select !== undefined && select.anySelected) {
      select.onPress('toggle');
      return;
    }
    onOpen();
  }

  function onContextMenu(event: MouseEvent<HTMLDivElement>): void {
    if (onMenu === undefined) return;
    event.preventDefault();
    onMenu({ x: event.clientX, y: event.clientY });
  }

  function onDragStart(event: DragEvent<HTMLDivElement>): void {
    event.dataTransfer.effectAllowed = 'move';
    // Some payload is required or Firefox refuses to start the drag at all. What it says does not
    // matter: the selection is read from state, never from the payload, so a drag out of another
    // tab cannot move anything in here.
    event.dataTransfer.setData('text/plain', 'rosie-notes-selection');
  }

  function onDragOver(event: DragEvent<HTMLDivElement>): void {
    if (onDropSelection === undefined || select?.selected === true) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }

  function onDrop(event: DragEvent<HTMLDivElement>): void {
    if (onDropSelection === undefined || select?.selected === true) return;
    event.preventDefault();
    onDropSelection();
  }

  return (
    /*
     * The `<li>` is the list item; the control is the element inside it.
     *
     * That control is a `div` with `role="button"` rather than a `<button>`, because a row's
     * trailing control is often itself a button — the per-note lock — and a `<button>` inside a
     * `<button>` is invalid HTML that behaves differently in every engine. The keyboard contract
     * is honoured by hand instead: Enter and Space both open, exactly as a button would.
     */
    <li className="row-item">
      {/* biome-ignore lint/a11y/useSemanticElements: a <button> here would nest buttons */}
      <div
        aria-label={label}
        className={classes.join(' ')}
        data-gc={accent ?? undefined}
        draggable={select?.selected === true}
        onClick={onClick}
        onContextMenu={onContextMenu}
        onDragOver={onDragOver}
        onDragStart={onDragStart}
        onDrop={onDrop}
        onKeyDown={onKeyDown}
        onPointerCancel={cancelPress}
        onPointerDown={onPointerDown}
        onPointerMove={cancelPress}
        onPointerUp={cancelPress}
        role="button"
        tabIndex={0}
      >
        {select === undefined ? (
          <Mark mark={mark} />
        ) : (
          <Pick
            label={typeof title === 'string' ? title : (label ?? 'this row')}
            mark={mark}
            select={select}
          />
        )}
        <span className="row-body">
          <span className={kind === 'plain' ? 'row-title plain' : 'row-title'}>
            {icon !== undefined && <span className="rowicon">{icon}</span>}
            <span className="row-title-text">{title}</span>
          </span>
          {excerpt !== undefined && excerpt !== '' && (
            <span className="row-excerpt">{excerpt}</span>
          )}
          {meta !== undefined && <span className="row-meta num">{meta}</span>}
        </span>
        <span className="row-trail">{trailing ?? <Icon name="chev" />}</span>
      </div>
    </li>
  );
}

/**
 * The last row of every list.
 *
 * Creating a subgroup is exactly as heavy as creating a note — one tap, in place, no modal. That
 * is the whole of flow 4.1 from the brief, and it is why this is a row rather than a button
 * somewhere else on the screen.
 */
export function AddRow({
  label,
  onClick,
}: {
  readonly label: string;
  readonly onClick: () => void;
}): React.JSX.Element {
  return (
    <Row
      kind="plain"
      label={label}
      mark="none"
      onOpen={onClick}
      title={label}
      trailing={<Icon name="plus" />}
    />
  );
}

/**
 * A list-shaped placeholder.
 *
 * A spinner over a list is a lie about what is coming; a few rail rows are the truth, and they
 * stop the page reflowing when the real thing lands.
 */
export function SkeletonRows({ count = 3 }: { readonly count?: number }): React.JSX.Element {
  return (
    <div aria-busy="true" className="list" role="status">
      <span className="sr">Loading…</span>
      {Array.from({ length: count }, (_unused, index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity of their own
        <div className="skeleton-row" key={index}>
          <span />
          <span>
            <span className="skeleton-bar" style={{ width: `${70 - index * 12}%` }} />
            <span className="skeleton-bar" style={{ width: `${40 - index * 6}%` }} />
          </span>
        </div>
      ))}
    </div>
  );
}
