import type { CollectionId, Note, NoteId, TagName } from '@rosie-notes/schema';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  addAll,
  type ClickIntent,
  clickIntent,
  EMPTY_SELECTION,
  extendTo,
  isSelected,
  partition,
  removeAll,
  type SelectableKind,
  type SelectionItem,
  type SelectionSnapshot,
  selectionKey,
  toggle,
} from './selection';

/**
 * The selection, mounted.
 *
 * Selection lives on the rail rows the app already has — there is no "manage" screen and no
 * second list mode to switch into (`DECISIONS.md` D-44). Anything that renders a `Row` can be
 * selected, and the bar at the bottom acts on whatever is ticked.
 *
 * Two things this holds that the pure model in `selection.ts` cannot:
 *
 * 1. **The note objects.** Tagging needs a note's existing tags, and the selection only carries
 *    ids. Rows hand over the note they are drawing when they tick it, so the bar never has to
 *    fetch forty notes back to add one word to them.
 * 2. **Clearing on navigation.** A selection that survived a route change would have the bar
 *    claiming three notes that are no longer on screen, and a Delete button that means something
 *    the person can no longer see. Leaving a screen ends the selection.
 */

export interface SelectionApi {
  readonly snapshot: SelectionSnapshot;
  readonly count: number;
  /** True as soon as anything is ticked — what turns a plain click into a select. */
  readonly active: boolean;
  isOn(item: SelectionItem): boolean;
  /** The one door. `ordered` is the list's own draw order, for shift-ranges. */
  press(
    item: SelectionItem,
    intent: Exclude<ClickIntent, 'open'>,
    ordered: readonly SelectionItem[],
    note?: Note,
  ): void;
  addMany(items: readonly SelectionItem[], notes?: readonly Note[]): void;
  removeMany(items: readonly SelectionItem[]): void;
  clear(): void;
  /** The selected notes, as objects, in no particular order. */
  notes(): readonly Note[];
  noteIds(): readonly NoteId[];
  groupIds(): readonly CollectionId[];
}

const SelectionContext = createContext<SelectionApi | null>(null);

export function useSelection(): SelectionApi {
  const value = useContext(SelectionContext);
  if (value === null) {
    throw new Error('useSelection must be used inside <SelectionProvider>');
  }
  return value;
}

/** The selection if there is one. For rows that also render outside the shell. */
export function useSelectionOptional(): SelectionApi | null {
  return useContext(SelectionContext);
}

export function SelectionProvider({
  children,
  routeKey,
}: {
  readonly children: ReactNode;
  /** Changing this clears the selection. The shell passes the current hash. */
  readonly routeKey: string;
}): React.JSX.Element {
  const [snapshot, setSnapshot] = useState<SelectionSnapshot>(EMPTY_SELECTION);
  const known = useRef(new Map<string, Note>());

  // biome-ignore lint/correctness/useExhaustiveDependencies: routeKey is the whole trigger
  useEffect(() => {
    setSnapshot(EMPTY_SELECTION);
    known.current.clear();
  }, [routeKey]);

  const value = useMemo<SelectionApi>(() => {
    const remember = (item: SelectionItem, note?: Note): void => {
      if (note !== undefined) known.current.set(selectionKey(item), note);
    };

    return {
      snapshot,
      count: snapshot.keys.size,
      active: snapshot.keys.size > 0,
      isOn: (item) => isSelected(snapshot, item),
      press(item, intent, ordered, note) {
        remember(item, note);
        setSnapshot((current) =>
          intent === 'range' ? extendTo(current, item, ordered) : toggle(current, item),
        );
      },
      addMany(items, notes = []) {
        for (const [index, item] of items.entries()) remember(item, notes[index]);
        setSnapshot((current) => addAll(current, items));
      },
      removeMany(items) {
        setSnapshot((current) => removeAll(current, items));
      },
      clear() {
        setSnapshot(EMPTY_SELECTION);
      },
      notes() {
        const out: Note[] = [];
        for (const key of snapshot.keys) {
          const note = known.current.get(key);
          if (note !== undefined) out.push(note);
        }
        return out;
      },
      noteIds: () => partition(snapshot).notes as NoteId[],
      groupIds: () => partition(snapshot).groups as CollectionId[],
    };
  }, [snapshot]);

  return <SelectionContext.Provider value={value}>{children}</SelectionContext.Provider>;
}

/**
 * What a `Row` needs to take part in selection, or `undefined` where selection is unavailable.
 *
 * Returned as one object so a row can spread it straight onto `<Row select={…}>` — a row should
 * not have to know that shift-clicks measure against a list order, only that it belongs to one.
 */
export interface RowSelection {
  readonly selected: boolean;
  readonly anySelected: boolean;
  onPress(intent: Exclude<ClickIntent, 'open'>): void;
  intentFor(event: {
    readonly shiftKey: boolean;
    readonly ctrlKey: boolean;
    readonly metaKey: boolean;
  }): ClickIntent;
}

export function useRowSelection(
  kind: SelectableKind,
  id: string,
  ordered: readonly SelectionItem[],
  note?: Note,
): RowSelection | undefined {
  const selection = useSelectionOptional();
  const press = selection?.press;
  const active = selection?.active ?? false;

  // Two strings rather than an object, so the memo compares by value. A row builds its own
  // `{ kind, id }` fresh on every render, and taking that as a dependency would rebuild the
  // callback on every keystroke anywhere else on the screen.
  const item = useMemo<SelectionItem>(() => ({ kind, id }), [kind, id]);

  const onPress = useCallback(
    (intent: Exclude<ClickIntent, 'open'>) => press?.(item, intent, ordered, note),
    [press, item, ordered, note],
  );

  if (selection === null) return undefined;
  return {
    selected: selection.isOn(item),
    anySelected: active,
    onPress,
    intentFor: (event) => clickIntent(event, active),
  };
}

/** Turn a list of ids into selection items, for the `ordered` argument. */
export function orderedItems(
  kind: SelectionItem['kind'],
  ids: readonly string[],
): readonly SelectionItem[] {
  return ids.map((id) => ({ kind, id }));
}

/** Every tag on every selected note, with how many carry it. Feeds the tag sheet. */
export function tagTally(notes: readonly Note[]): readonly { tag: TagName; count: number }[] {
  const counts = new Map<string, number>();
  for (const note of notes) {
    for (const tag of note.tags) counts.set(tag as string, (counts.get(tag as string) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([tag, count]) => ({ tag: tag as TagName, count }))
    .sort((left, right) => right.count - left.count || left.tag.localeCompare(right.tag));
}
