import type { NoteListRequestInput } from '@rosie-notes/schema';
import { useMemo } from 'react';
import { useNoteQuery } from '../hooks/use-note-query';
import { PageHeader } from './chrome';
import { NoteRow } from './group-view';
import { plural } from './labels';
import { Callout } from './primitives';
import { List, SkeletonRows } from './rail';
import { EmptyState, ErrorState, OfflineBanner } from './states';

/**
 * "Everything by this name" (T-38) — never a profile of a person.
 *
 * D-40 is the whole design brief for this screen: `creator` is a field on the notes Rose has
 * collected, not an account, so there is nothing here to imply a signup, a real person browsing
 * this app, or a way to reach them. The {@link Callout} says that outright rather than trusting
 * the absence of a "message" button to say it by itself — a page that merely *lacks* the features
 * of a profile still reads as one at a glance, and glances are what this screen gets.
 *
 * The list is a live query, not a cached count: `meta.story.creator` can be edited on any note at
 * any time from `story-fields.tsx`, and a work count computed once at some other screen would
 * drift the moment somebody retypes a name.
 */

export interface CreatorViewProps {
  readonly creatorName: string;
}

export function CreatorView({ creatorName }: CreatorViewProps): React.JSX.Element {
  const query = useMemo<NoteListRequestInput>(
    () => ({ creator: creatorName, limit: 200 }),
    [creatorName],
  );
  const works = useNoteQuery(query);
  const count = works.total ?? works.notes.length;

  return (
    <>
      <PageHeader
        sub={<span>{plural(count, 'work')}</span>}
        title={creatorName === '' ? 'Untitled creator' : creatorName}
      />

      <Callout icon="eye" tone="quiet">
        <b>{creatorName}</b> is a field on the notes below, not an account. There is no profile to
        visit here beyond this page, and no way to message anyone — whoever this is has not signed
        up to anything.
      </Callout>

      {works.stale && <OfflineBanner what="this creator's works" />}

      {works.loading && works.notes.length === 0 ? (
        <SkeletonRows count={3} />
      ) : works.error !== null ? (
        <ErrorState
          body="The server did not answer and this device has nothing cached for this creator."
          onRetry={works.reload}
          title="This could not be loaded"
        />
      ) : works.notes.length === 0 ? (
        <EmptyState
          body="No note in your library names this creator. It may have been renamed or removed."
          title="Nothing by this name yet"
        />
      ) : (
        <List label={`Works by ${creatorName}`}>
          {works.notes.map((note) => (
            <NoteRow key={note.id} note={note} onChanged={works.reload} />
          ))}
        </List>
      )}
    </>
  );
}
