import type { CollectionId, NoteId } from '@rosie-notes/schema';
import { useCallback, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useNoteActions } from '../hooks/use-note-actions';
import { useHistory } from './history';
import { Icon } from './icons';
import { Sheet } from './primitives';
import type { RowMenuItem } from './row-menu';
import { useSelectionOptional } from './selection-context';
import { useToast } from './toasts';

/**
 * The quick actions a row offers, and their undo.
 *
 * Rose asked for two things that are one piece of work: a right-click menu with *"rename, move to,
 * delete, ect"*, and Ctrl+Z for *"group moves, renames, ect"*. Every action here does both — it
 * acts, and it registers how to reverse itself **while it still knows the old value**. A rename
 * that did not capture the previous name at the moment it ran cannot be undone by any amount of
 * cleverness afterwards.
 *
 * Menu *items* live here rather than in `row-menu.tsx` so that the menu stays a menu: it knows how
 * to position itself and take a keystroke, and nothing at all about groups or notes.
 */

export interface RowTarget {
  readonly kind: 'group' | 'note';
  readonly id: string;
  readonly name: string;
}

export interface RowActions {
  /**
   * The menu for a row.
   *
   * `onRename` is the row's own "turn the title into a field" — passed in rather than signalled,
   * because the row is the thing that knows how to edit itself and a global event to tell it so
   * would be a channel with exactly one listener.
   */
  itemsFor(
    target: RowTarget,
    options?: { readonly onRename?: () => void; readonly extra?: readonly RowMenuItem[] },
  ): readonly RowMenuItem[];
  rename(target: RowTarget, next: string): Promise<boolean>;
  move(target: RowTarget, destination: CollectionId | null): Promise<void>;
  remove(target: RowTarget): Promise<void>;
  askMove(target: RowTarget): void;
  /** What the move sheet is open for, or `null`. Render {@link RowMoveSheet} against it. */
  readonly moving: RowTarget | null;
  closeMove(): void;
}

export function useRowActions(): RowActions {
  const tree = useGroups();
  const notes = useNoteActions();
  const history = useHistory();
  const toast = useToast();
  const selection = useSelectionOptional();
  const [moving, setMoving] = useState<RowTarget | null>(null);

  const rename = useCallback(
    async (target: RowTarget, next: string): Promise<boolean> => {
      const trimmed = next.trim();
      if (trimmed === '' || trimmed === target.name) return false;
      const before = target.name;

      const apply = async (name: string): Promise<void> => {
        if (target.kind === 'group') await tree.update(target.id as CollectionId, { name });
        else await notes.rename(target.id as NoteId, name);
      };

      await apply(trimmed);
      history.push({
        label: `Renamed ${before} to ${trimmed}`,
        undo: () => apply(before),
        redo: () => apply(trimmed),
      });
      return true;
    },
    [history, notes, tree],
  );

  const move = useCallback(
    async (target: RowTarget, destination: CollectionId | null): Promise<void> => {
      const wasIn =
        target.kind === 'group'
          ? ((tree.byId.get(target.id)?.parentId as CollectionId | null) ?? null)
          : null;

      const apply = async (to: CollectionId | null): Promise<void> => {
        if (target.kind === 'group') {
          await tree.update(target.id as CollectionId, { parentId: to });
          await tree.reload();
        } else if (to !== null) {
          await notes.update(target.id as NoteId, { collectionIds: [to] });
        }
      };

      await apply(destination);
      const where =
        destination === null ? 'the top level' : (tree.byId.get(destination)?.name ?? 'there');
      history.push({
        label: `Moved ${target.name} to ${where}`,
        undo: () => apply(wasIn),
        redo: () => apply(destination),
      });
      toast.show(`${target.name} moved to ${where}.`, { icon: 'move' });
      setMoving(null);
    },
    [history, notes, toast, tree],
  );

  const remove = useCallback(
    async (target: RowTarget): Promise<void> => {
      if (target.kind === 'note') {
        await notes.trash(target.id as NoteId);
        history.push({
          label: `Deleted ${target.name}`,
          // The trash is what makes this reversible at all: a note goes there rather than away,
          // so the undo is the restore the trash screen already offers.
          undo: () => notes.restore(target.id as NoteId),
          redo: () => notes.trash(target.id as NoteId),
        });
        toast.show(`${target.name} moved to the trash.`, { icon: 'trash' });
        return;
      }

      /*
       * A group delete is **not** offered as reversible, on purpose.
       *
       * The server promotes the children rather than keeping the group, and there is no "untrash a
       * group" — so an undo entry here would be a promise the API cannot keep. The toast says what
       * actually happened to the notes instead of implying a safety net that is not there.
       */
      const counted = tree.tally(target.id);
      await tree.remove(target.id as CollectionId);
      toast.show(
        counted.notes === 0
          ? `${target.name} deleted.`
          : `${target.name} deleted. Its ${counted.notes} notes moved up a level.`,
        { icon: 'trash' },
      );
    },
    [history, notes, toast, tree],
  );

  const itemsFor = useCallback(
    (
      target: RowTarget,
      options: { readonly onRename?: () => void; readonly extra?: readonly RowMenuItem[] } = {},
    ): readonly RowMenuItem[] => {
      const items: RowMenuItem[] = [];
      if (options.onRename !== undefined) {
        items.push({ label: 'Rename', icon: 'edit', run: options.onRename });
      }
      items.push({ label: 'Move to…', icon: 'move', run: () => setMoving(target) });
      if (selection !== null) {
        items.push({
          label: 'Select',
          icon: 'check',
          run: () =>
            selection.press({ kind: target.kind, id: target.id }, 'toggle', [
              { kind: target.kind, id: target.id },
            ]),
        });
      }
      items.push(...(options.extra ?? []));
      items.push({ label: 'Delete', icon: 'trash', danger: true, run: () => void remove(target) });
      return items;
    },
    [remove, selection],
  );

  return {
    itemsFor,
    rename,
    move,
    remove,
    askMove: setMoving,
    moving,
    closeMove: () => setMoving(null),
  };
}

/**
 * The move picker, for one row.
 *
 * `selection-bar.tsx` has the bulk version; this is the single-row one, and it shares the one hard
 * rule: a group cannot be moved inside itself or anything under it, because that detaches the
 * branch from the tree entirely.
 */
export function RowMoveSheet({
  target,
  onClose,
  onMove,
}: {
  readonly target: RowTarget;
  readonly onClose: () => void;
  readonly onMove: (destination: CollectionId | null) => void;
}): React.JSX.Element {
  const tree = useGroups();

  const options = [...tree.byId.values()]
    .map((group) => ({
      group,
      path: tree
        .chain(group.id as string)
        .map((entry) => entry.name)
        .join(' / '),
      blocked:
        target.kind === 'group' &&
        (group.id === target.id ||
          tree.chain(group.id as string).some((entry) => entry.id === target.id)),
    }))
    .sort((left, right) => left.path.localeCompare(right.path));

  return (
    <Sheet onClose={onClose} sub={`Where should ${target.name} go?`} title="Move to">
      <div className="setlist">
        {target.kind === 'group' && (
          <button className="setrow" onClick={() => onMove(null)} type="button">
            <span className="setrow-main">
              <span className="setrow-label">The top level</span>
              <span className="setrow-help">Out of any group.</span>
            </span>
            <span className="setrow-value">
              <Icon className="chev" name="chev" />
            </span>
          </button>
        )}
        {options.map(({ group, path, blocked }) => (
          <button
            className="setrow"
            disabled={blocked}
            key={group.id}
            onClick={() => onMove(group.id)}
            type="button"
          >
            <span className="setrow-main">
              <span className="setrow-label">{group.name}</span>
              <span className="setrow-help">{path}</span>
            </span>
            <span className="setrow-value">
              {blocked ? <span className="inh">Inside itself</span> : null}
              <Icon className="chev" name="chev" />
            </span>
          </button>
        ))}
      </div>
    </Sheet>
  );
}
