import type { UserConfig } from '@rosie-notes/schema';
import { parseUserConfig, resolveProjectPath } from '@rosie-notes/schema';
import { useState } from 'react';
import { useUserConfig } from '../hooks/use-user-config';
import { Btn, Callout, SetGroup, SetRow, Sheet } from './primitives';
import { useShell } from './shell-context';
import { useToast } from './toasts';

/**
 * Your setup, and importing one.
 *
 * Rose asked for this shape outright (`GROUP-MODEL.md` §2): *"hand over an **importable config
 * file** pre-filled with Rose's own project types and path templates, so their install is set up
 * correctly without going through the UI. Everyone else starts from an empty list."* So the screen
 * is a reader for a file somebody already has, not a form to fill in.
 *
 * **It shows what it is about to do before it does it.** A config sets where files get written, so
 * an import that just said "done" would be asking somebody to trust a path they had not seen. The
 * preview lists the project types, resolves one real path from the first of them, and says plainly
 * that nothing is written to disk by any of this.
 */

export function ConfigSection(): React.JSX.Element {
  // The hook is called **here and only here**: `useUserConfig` holds its own state, so a second
  // call inside the sheet would save into a copy the screen behind it never hears about.
  const { config, configured, save } = useUserConfig();
  const [importing, setImporting] = useState(false);

  const types = config.paths.types;

  return (
    <>
      <SetGroup title="Your setup">
        <SetRow
          help={
            configured
              ? 'Where each kind of project lives on your disk, and the file a new one is handed.'
              : 'Nothing set up yet. A path convention is your own filing system, so there is nothing sensible to guess.'
          }
          label="Project types"
          value={
            <span>
              {types.length === 0
                ? 'None'
                : types
                    .map((type) => type.label)
                    .slice(0, 3)
                    .join(' · ')}
            </span>
          }
        />
        {config.paths.root !== '' && (
          <SetRow
            label="Root folder"
            value={<span className="chip chip-mono">{config.paths.root}</span>}
          />
        )}
        <SetRow
          help="Reads a config file — the one you were handed, or one you wrote. It replaces what is here."
          label="Import a config"
          onClick={() => setImporting(true)}
          value={<span />}
        />
      </SetGroup>

      {importing && <ImportSheet onClose={() => setImporting(false)} save={save} />}
    </>
  );
}

/** What an about-to-be-imported config would set up, in the words somebody can check. */
function Preview({ config }: { readonly config: UserConfig }): React.JSX.Element {
  const first = config.paths.types[0];
  const example =
    first === undefined
      ? null
      : resolveProjectPath(config, first.id, { project: 'a-project', subgroup: 'docs' });

  return (
    <div style={{ display: 'grid', gap: 10 }}>
      <p className="setrow-help">
        <b>
          {config.paths.types.length} project types
          {config.paths.root === '' ? '' : `, under ${config.paths.root}`}
        </b>
        {config.defaultSubgroups.codeProject.length > 0 &&
          `. New code projects get ${config.defaultSubgroups.codeProject.join(', ')}`}
        {config.mainFile.enabled && `, plus a ${config.mainFile.filename}`}.
      </p>
      {example !== null && (
        <p className="setrow-help">
          A {first?.label.toLowerCase()} project called <i>a-project</i> would resolve its docs
          folder to <span className="chip chip-mono">{example}</span>.
        </p>
      )}
      {config.projects.length > 0 && (
        <p className="setrow-help">
          It also lists <b>{config.projects.length} projects</b>. Importing does <b>not</b> create
          them — you pick which ones afterwards, on the setup screen.
        </p>
      )}
      <Callout icon="eye" tone="quiet">
        <b>Nothing is written to your disk by importing this.</b> It only tells the app which paths
        to suggest. Files are only ever created when you ask for it, from the editor.
      </Callout>
    </div>
  );
}

function ImportSheet({
  onClose,
  save,
}: {
  readonly onClose: () => void;
  readonly save: (config: UserConfig) => Promise<void>;
}): React.JSX.Element {
  const { appearance } = useShell();
  const toast = useToast();
  const [text, setText] = useState('');
  const [parsed, setParsed] = useState<UserConfig | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  /**
   * Read the pasted text.
   *
   * Two failures worth telling apart, because the fix is different: text that is not JSON at all
   * (usually a half-copied file) and JSON whose shape is wrong (usually a typo in a key). The
   * schema is strict about the second on purpose — a silently ignored key is a setting that never
   * happens and nobody can see why.
   */
  function check(next: string): void {
    setText(next);
    setParsed(null);
    setFailure(null);
    if (next.trim() === '') return;
    let raw: unknown;
    try {
      raw = JSON.parse(next);
    } catch {
      setFailure('That is not valid JSON. Copy the whole file, including the outer braces.');
      return;
    }
    try {
      setParsed(parseUserConfig(raw));
    } catch (error) {
      setFailure(
        error instanceof Error
          ? `That JSON is not a config: ${error.message.slice(0, 300)}`
          : 'That JSON is not a config.',
      );
    }
  }

  async function readFile(file: File | undefined): Promise<void> {
    if (file === undefined) return;
    check(await file.text());
  }

  async function apply(): Promise<void> {
    if (parsed === null) return;
    setSaving(true);
    try {
      await save(parsed);
      // Appearance is applied to *this device* rather than stored as a preference somebody has to
      // find later. `null` means the config had no opinion, and a device already tuned is left be.
      if (parsed.appearance.theme !== null) appearance.setThemePreference(parsed.appearance.theme);
      if (parsed.appearance.density !== null) appearance.setDensity(parsed.appearance.density);
      toast.show('Config imported.');
      onClose();
    } catch (error) {
      setFailure(
        error instanceof Error ? error.message : 'The server did not accept it. Nothing changed.',
      );
    } finally {
      setSaving(false);
    }
  }

  return (
    <Sheet
      onClose={onClose}
      sub="Paste the file, or choose it. It replaces your current setup — it does not merge into it."
      title="Import a config"
    >
      <div style={{ display: 'grid', gap: 10 }}>
        <input
          accept="application/json,.json"
          aria-label="Config file"
          className="field"
          onChange={(event) => void readFile(event.target.files?.[0])}
          type="file"
        />
        <textarea
          aria-label="Config JSON"
          className="field field-mono"
          onChange={(event) => check(event.target.value)}
          placeholder='{ "version": 1, "paths": { … } }'
          rows={8}
          value={text}
        />

        {failure !== null && (
          <p className="banner banner-clay" role="alert">
            {failure}
          </p>
        )}
        {parsed !== null && <Preview config={parsed} />}
      </div>

      <div className="form__actions" style={{ marginTop: 16 }}>
        <Btn onClick={onClose} tone="ghost">
          Cancel
        </Btn>
        <Btn disabled={parsed === null || saving} onClick={() => void apply()} tone="primary">
          {saving ? 'Importing…' : 'Import it'}
        </Btn>
      </div>
    </Sheet>
  );
}
