import type { StoryCreator, StoryFacetsResponse, StoryTheme } from '@rosie-notes/client';
import { useCallback, useEffect, useState } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * The story library's derived views — creators, themes, facet chips — in one hook.
 *
 * All three ride together rather than as three separate hooks, because every screen that wants
 * one of them ends up wanting the others: the browse screen (`stories-view.tsx`) filters by all
 * three, and the per-note editable block (`story-fields.tsx`) only needs `creators` and
 * `facets.source` for its `<datalist>`s but asking for the whole bag is one request either way —
 * `Promise.all`, not three separate loading states to reconcile on screen.
 *
 * Unlike `useNoteQuery`, there is no offline fallback here. A cached note list can be filtered
 * locally by `filters/evaluate`; a creator's work count or a theme's tag cloud cannot be
 * reconstructed from whatever notes happen to be cached on this device without silently lying
 * about totals, so this simply fails and lets the screen say so.
 */

export interface StoryLibraryState {
  readonly creators: readonly StoryCreator[];
  readonly themes: readonly StoryTheme[];
  readonly facets: StoryFacetsResponse;
  readonly loading: boolean;
  readonly failed: boolean;
  reload(): void;
}

const EMPTY_FACETS: StoryFacetsResponse = { source: [], storyType: [], status: [] };

export function useStoryLibrary(): StoryLibraryState {
  const workspace = useWorkspace();
  const [creators, setCreators] = useState<readonly StoryCreator[]>([]);
  const [themes, setThemes] = useState<readonly StoryTheme[]>([]);
  const [facets, setFacets] = useState<StoryFacetsResponse>(EMPTY_FACETS);
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);
  const [nonce, setNonce] = useState(0);

  // `nonce` is not read in the body — it is the reload signal. Bumping it is how `reload()`
  // re-runs a query whose inputs have not changed, which is the entire point of a retry button.
  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const [creatorsResult, themesResult, facetsResult] = await Promise.all([
          workspace.client.stories.creators(),
          workspace.client.stories.themes(),
          workspace.client.stories.facets(),
        ]);
        if (cancelled) return;
        setCreators(creatorsResult);
        setThemes(themesResult);
        setFacets(facetsResult);
        setFailed(false);
      } catch {
        if (cancelled) return;
        setFailed(true);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspace, nonce]);

  return {
    creators,
    themes,
    facets,
    loading,
    failed,
    reload: useCallback(() => setNonce((value) => value + 1), []),
  };
}
