import type { KeyValueStore, NoteCache, PlatformAdapter } from '@rosie-notes/core';
import type { Note, NoteId } from '@rosie-notes/schema';
import {
  DOCS_STORE,
  idbClear,
  idbDelete,
  idbGet,
  idbGetAll,
  idbPut,
  NOTES_STORE,
  openDatabase,
} from './idb';

/**
 * The browser's {@link PlatformAdapter}.
 *
 * `localStorage` for the handful of small durable strings (sync cursors, the outbox, the session)
 * and IndexedDB for the library itself. The split is the one `core` asks for and it matters:
 * `localStorage` is synchronous and therefore blocks the main thread, so a note body has no
 * business being in it, while IndexedDB is a poor fit for a value read on every flush.
 *
 * ## Everything here is a cache
 *
 * The server is the source of truth. That is what lets this file be as simple as it is: a
 * corrupt or missing entry is a slower start, never lost work, so nothing here retries, migrates
 * or repairs. A read that fails returns "nothing cached" and the app fetches.
 */

const STORAGE_PREFIX = 'rosie-notes:';

/** `localStorage` behind the async {@link KeyValueStore} interface. */
export class LocalStorageStore implements KeyValueStore {
  readonly #storage: Storage;
  readonly #prefix: string;

  constructor(storage: Storage, prefix = STORAGE_PREFIX) {
    this.#storage = storage;
    this.#prefix = prefix;
  }

  async get(key: string): Promise<string | null> {
    return this.#storage.getItem(this.#prefix + key);
  }

  async set(key: string, value: string): Promise<void> {
    // A full quota is a real possibility on a shared origin, and it throws. The outbox is the
    // one caller that must know, so it is not swallowed — losing a queued edit silently would be
    // exactly the failure the outbox exists to prevent.
    this.#storage.setItem(this.#prefix + key, value);
  }

  async remove(key: string): Promise<void> {
    this.#storage.removeItem(this.#prefix + key);
  }

  async keys(prefix = ''): Promise<string[]> {
    const wanted = this.#prefix + prefix;
    const found: string[] = [];
    for (let index = 0; index < this.#storage.length; index += 1) {
      const key = this.#storage.key(index);
      if (key?.startsWith(wanted) === true) {
        found.push(key.slice(this.#prefix.length));
      }
    }
    return found;
  }
}

/** The library in IndexedDB: note metadata in one store, Yjs document blobs in another. */
export class IndexedDbNoteCache implements NoteCache {
  readonly #open: () => Promise<IDBDatabase>;
  #database: Promise<IDBDatabase> | null = null;

  constructor(open: () => Promise<IDBDatabase>) {
    this.#open = open;
  }

  /** Opened lazily and once: a cold start should not wait on IndexedDB before it can paint. */
  #db(): Promise<IDBDatabase> {
    this.#database ??= this.#open();
    return this.#database;
  }

  async readNote(id: NoteId): Promise<Note | null> {
    return idbGet<Note>(await this.#db(), NOTES_STORE, id);
  }

  async writeNote(note: Note): Promise<void> {
    await idbPut(await this.#db(), NOTES_STORE, note.id, note);
  }

  async removeNote(id: NoteId): Promise<void> {
    await idbDelete(await this.#db(), NOTES_STORE, id);
  }

  async listNotes(): Promise<Note[]> {
    return idbGetAll<Note>(await this.#db(), NOTES_STORE);
  }

  async readDoc(id: NoteId): Promise<Uint8Array | null> {
    const stored = await idbGet<ArrayBuffer | Uint8Array>(await this.#db(), DOCS_STORE, id);
    if (stored === null) {
      return null;
    }
    // Structured clone gives back an ArrayBuffer in some engines and a Uint8Array in others.
    return stored instanceof Uint8Array ? stored : new Uint8Array(stored);
  }

  async writeDoc(id: NoteId, state: Uint8Array): Promise<void> {
    await idbPut(await this.#db(), DOCS_STORE, id, state);
  }

  async removeDoc(id: NoteId): Promise<void> {
    await idbDelete(await this.#db(), DOCS_STORE, id);
  }

  async clear(): Promise<void> {
    await idbClear(await this.#db(), [NOTES_STORE, DOCS_STORE]);
  }
}

export interface BrowserAdapterOptions {
  /** Overridden in tests; defaults to the real ones. */
  readonly storage?: Storage | undefined;
  readonly indexedDB?: IDBFactory | undefined;
  readonly fetch?: typeof globalThis.fetch | undefined;
  readonly databaseName?: string | undefined;
}

/**
 * Somewhere to put things when the browser will not let us — private browsing with storage
 * disabled, or a blocked third-party context. The app still runs; it simply forgets on reload,
 * which is a far better outcome than a white screen.
 */
class MemoryStorage implements Storage {
  readonly #entries = new Map<string, string>();

  get length(): number {
    return this.#entries.size;
  }

  clear(): void {
    this.#entries.clear();
  }

  getItem(key: string): string | null {
    return this.#entries.get(key) ?? null;
  }

  key(index: number): string | null {
    return [...this.#entries.keys()][index] ?? null;
  }

  removeItem(key: string): void {
    this.#entries.delete(key);
  }

  setItem(key: string, value: string): void {
    this.#entries.set(key, value);
  }
}

/** `localStorage` throws on access in some privacy modes, so even reading it needs a guard. */
export function safeLocalStorage(): Storage {
  try {
    const probe = '__rosie-notes-probe__';
    globalThis.localStorage.setItem(probe, '1');
    globalThis.localStorage.removeItem(probe);
    return globalThis.localStorage;
  } catch {
    return new MemoryStorage();
  }
}

export function createBrowserAdapter(options: BrowserAdapterOptions = {}): PlatformAdapter {
  const factory = options.indexedDB ?? globalThis.indexedDB;
  const fetchImpl = options.fetch ?? globalThis.fetch.bind(globalThis);

  return {
    storage: new LocalStorageStore(options.storage ?? safeLocalStorage()),
    cache: new IndexedDbNoteCache(() =>
      options.databaseName === undefined
        ? openDatabase(factory)
        : openDatabase(factory, options.databaseName),
    ),
    net: {
      fetch: fetchImpl,
      WebSocket: globalThis.WebSocket as unknown as PlatformAdapter['net']['WebSocket'],
    },
    clock: () => Date.now(),
    random: () => globalThis.crypto.randomUUID(),
  };
}
