import { transcriptionAudioNotice, transcriptionEngineInfo } from '@rosie-notes/schema';
import { useDictation } from '../hooks/use-dictation';
import { Icon } from './icons';

/**
 * The dictate button, and the sentence that has to sit next to it.
 *
 * `DECISIONS.md` D-23: *"every option is labelled with **where the audio actually goes**, in plain
 * language, and the record button shows which engine is live."* That is the whole reason this is
 * a labelled panel rather than a microphone icon. In Chrome the Web Speech API **streams the
 * audio to Google** — which is a perfectly reasonable trade for dictating a shopping list and an
 * unpleasant surprise for somebody dictating into a note they locked. The app says so before the
 * microphone opens, not in a settings page nobody found.
 *
 * The wording is not written here. It comes from `TRANSCRIPTION_ENGINES` in the schema, which the
 * Android app and the VSCode extension read too — one description of where audio goes, shown
 * identically everywhere, so the three surfaces cannot drift into telling different stories about
 * the same recogniser.
 */

export interface DictateProps {
  /** Where a finished phrase goes. Typically the editor's `insertText` command. */
  readonly onPhrase: (text: string) => void;
  readonly disabled?: boolean;
}

export function Dictate({ onPhrase, disabled = false }: DictateProps): React.JSX.Element | null {
  const dictation = useDictation({ onPhrase });
  const engine = transcriptionEngineInfo('browser_speech');
  const notice = transcriptionAudioNotice('browser_speech');

  // Nothing at all rather than a dead button. A browser with no recogniser is most of Firefox,
  // and offering a control that cannot work is worse than not mentioning the feature.
  if (dictation.state === 'unsupported') return null;

  const listening = dictation.state === 'listening';

  return (
    <div className={listening ? 'dictate is-live' : 'dictate'}>
      <button
        aria-pressed={listening}
        className="dictate-btn"
        disabled={disabled}
        onClick={() => (listening ? dictation.stop() : dictation.start())}
        type="button"
      >
        <Icon name={listening ? 'x' : 'spark'} />
        <span>{listening ? 'Stop dictating' : 'Dictate'}</span>
      </button>

      <span className="dictate-where">
        {listening ? (
          <>
            <b>{engine.label}</b> — {notice}
          </>
        ) : (
          notice
        )}
      </span>

      {/*
        The live guess, shown and never inserted. The recogniser revises interim results as more
        audio arrives — "recognise" becoming "recognize" becoming "recognise" — and putting those
        into the document produces text that rewrites itself under the caret. Only final phrases
        are handed over.
      */}
      {listening && dictation.interim !== '' && (
        <span aria-live="polite" className="dictate-interim">
          {dictation.interim}
        </span>
      )}

      {dictation.problem !== null && (
        <span className="dictate-problem" role="alert">
          {dictation.problem}
        </span>
      )}
    </div>
  );
}
