import type { Annotation, AnnotationId, NoteId } from '@rosie-notes/schema';
import { anchorAnnotation, targetFromSelection } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNoteBody } from '../hooks/use-note-body';
import { useWorkspace } from '../session/session-context';
import { Icon } from './icons';
import { ago, plural } from './labels';
import { Btn, Callout } from './primitives';
import { useToast } from './toasts';

/**
 * Comments on a span of a note (T-16).
 *
 * Rose asked for *"anchored annotations (comment on a span, survives edits)"*. The surviving is
 * the whole feature, and it happens in `anchorAnnotation` in the schema package — the same
 * function the server would run, so a comment lands in the same place here, in an export and in
 * anything else that has the note's text.
 *
 * ## The orphan case, which is the one worth looking at
 *
 * When the quoted text is reworded out of existence there is nowhere to put the comment. It is
 * **kept, listed, and labelled** with what it used to be about, rather than deleted or silently
 * dropped down the page: somebody wrote it about something, and *"this used to say X, and here is
 * what I thought"* is worth more than a tidy list. Deleting it is a decision for the person who
 * wrote it, not for a resolver that could not find a string.
 *
 * ## Why the selection is taken from the flattened body
 *
 * The editor knows the ProseMirror positions, which mean nothing outside a mounted editor. The
 * body — the markdown projection the server also indexes — is text every client has. Anchoring
 * against that makes an annotation something a script or the Android app can read, and it costs
 * only that a comment is made from **selecting in the panel's own quote box** rather than in the
 * editor. Highlighting the span inside the editor would need a ProseMirror decoration and a new
 * bridge message, which is real work and is not this.
 */

export interface AnnotationsProps {
  readonly noteId: NoteId;
}

type Anchored = {
  readonly annotation: Annotation;
  readonly how: ReturnType<typeof anchorAnnotation>['how'];
};

export function Annotations({ noteId }: AnnotationsProps): React.JSX.Element {
  const workspace = useWorkspace();
  const toast = useToast();
  const body = useNoteBody(noteId);
  const [items, setItems] = useState<readonly Annotation[]>([]);
  const [showResolved, setShowResolved] = useState(false);
  const [quote, setQuote] = useState('');
  const [comment, setComment] = useState('');
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const page = await workspace.client.annotations.list(noteId, {
        includeResolved: showResolved,
      });
      setItems(page.items);
      setFailure(null);
    } catch {
      // Offline, or an older server. A note with no comment list is still a readable note, so
      // this stays quiet rather than putting an error banner over somebody's writing.
      setItems([]);
    }
  }, [noteId, showResolved, workspace]);

  useEffect(() => {
    void load();
  }, [load]);

  const anchored = useMemo<readonly Anchored[]>(
    () =>
      items.map((annotation) => ({
        annotation,
        how: anchorAnnotation(body.text, annotation.target).how,
      })),
    [items, body.text],
  );

  const orphans = anchored.filter((entry) => entry.how === 'orphaned').length;

  async function add(): Promise<void> {
    if (comment.trim() === '') return;
    setBusy(true);
    setFailure(null);
    try {
      const at = quote === '' ? -1 : body.text.indexOf(quote);
      const target =
        at === -1
          ? // No quote, or a quote that is not in the note: a comment on the whole thing. Saying
            // so is better than pinning it to a span that does not exist.
            { quote: '', prefix: '', suffix: '', offsetHint: 0 }
          : targetFromSelection(body.text, at, at + quote.length);
      const created = await workspace.client.annotations.create(noteId, {
        target,
        body: comment.trim(),
      });
      setItems((current) => [...current, created]);
      setQuote('');
      setComment('');
      toast.show(target.quote === '' ? 'Comment added.' : 'Comment anchored.', { icon: 'edit' });
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That comment was not saved.');
    } finally {
      setBusy(false);
    }
  }

  async function setResolved(id: AnnotationId, resolved: boolean): Promise<void> {
    await workspace.client.annotations.update(id, { resolved });
    await load();
  }

  async function remove(id: AnnotationId): Promise<void> {
    await workspace.client.annotations.remove(id);
    setItems((current) => current.filter((entry) => entry.id !== id));
  }

  return (
    <section className="notes-anno">
      <div className="sec-head">
        <h2 className="sec-title">Comments</h2>
        <span className="sec-note num">
          {plural(items.length, 'comment')}
          {orphans > 0 ? ` · ${orphans} no longer anchored` : ''}
        </span>
      </div>

      <div className="anno-new">
        <label className="field-row">
          <span className="eyebrow">The words you are commenting on</span>
          <input
            className="field"
            onChange={(event) => setQuote(event.target.value)}
            placeholder="Paste or type a phrase from the note — or leave it empty"
            value={quote}
          />
          <span className="hint">
            {quote === ''
              ? 'Empty means the comment is about the whole note.'
              : body.text.includes(quote)
                ? 'Found in the note. The comment will follow these words as you edit around them.'
                : 'Not in the note as written — this will be saved as a comment on the whole note.'}
          </span>
        </label>
        <label className="field-row">
          <span className="eyebrow">What you want to say</span>
          <textarea
            className="field"
            onChange={(event) => setComment(event.target.value)}
            rows={2}
            value={comment}
          />
        </label>
        <Btn
          disabled={busy || comment.trim() === ''}
          onClick={() => void add()}
          small
          tone="primary"
        >
          Add the comment
        </Btn>
      </div>

      {failure !== null && (
        <Callout icon="warn" tone="clay">
          {failure}
        </Callout>
      )}

      {anchored.length === 0 ? (
        <p className="setrow-help">
          No comments on this note yet. A comment sticks to the words you quote, and follows them as
          you edit around them.
        </p>
      ) : (
        <ul className="anno-list">
          {anchored.map(({ annotation, how }) => (
            <li className={how === 'orphaned' ? 'anno is-orphan' : 'anno'} key={annotation.id}>
              <div className="anno-quote">
                {annotation.target.quote === '' ? (
                  <em>About the whole note</em>
                ) : (
                  <>“{annotation.target.quote}”</>
                )}
              </div>
              <div className="anno-body">{annotation.body}</div>
              <div className="anno-meta num">
                <span>{ago(annotation.updatedAt)}</span>
                {how === 'orphaned' && (
                  // Kept and labelled, never dropped. Somebody wrote it about something.
                  <span className="anno-flag">
                    <Icon name="warn" /> the words it quoted are no longer in the note
                  </span>
                )}
                {how === 'quote' && <span className="anno-flag">moved</span>}
                {annotation.resolved && <span className="anno-flag">done</span>}
                <button
                  className="anno-act"
                  onClick={() => void setResolved(annotation.id, !annotation.resolved)}
                  type="button"
                >
                  {annotation.resolved ? 'Reopen' : 'Mark done'}
                </button>
                <button
                  className="anno-act"
                  onClick={() => void remove(annotation.id)}
                  type="button"
                >
                  Delete
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      <label className="anno-toggle">
        <input
          checked={showResolved}
          onChange={(event) => setShowResolved(event.target.checked)}
          type="checkbox"
        />
        <span>Show the ones marked done</span>
      </label>
    </section>
  );
}
