import type { Note, NoteId } from '@rosie-notes/schema';
import { ACCENT_NAMES } from '@rosie-notes/tokens';
import { useEffect, useRef, useState } from 'react';
import { useAddNote } from '../hooks/use-add-note';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNoteBody } from '../hooks/use-note-body';
import { useNavigate } from '../routing/use-route';
import { Icon } from './icons';
import { plural } from './labels';
import {
  addPoint,
  movePoint,
  type Point,
  parsePoints,
  pastePoints,
  removePoint,
  serializePoints,
  setPointText,
} from './points';
import { Btn } from './primitives';

/**
 * Several notes side by side, each edited on its own.
 *
 * This is two of Rose's asks at once, and they turned out to be the same screen.
 *
 * **T-39, the shared page.** From `prompts/old/tmp6.txt`: *"a group which allows the user to have
 * a main file that is readable by both users … but each user in this group has their own notes
 * page which then will get auto added to the main one … Rose and Ryla are both writing their
 * thoughts as to why Rose has ADHD"*, with a sketch of a table headed by the two names. The
 * "main note" is not a separate document that has to be kept in step — it is **this view**: the
 * columns, read together, under the group's own name. Nothing is copied anywhere, so nothing can
 * fall out of date, and the whole thing exports as one page because a group export already does.
 *
 * **T-18, two notes side by side, editable independently.** Same mechanism, no shared-group
 * framing needed: turn the layout on for any group and its notes sit next to each other.
 *
 * Each column is an ordinary note (`DECISIONS.md` D-22: each person owns a part only they write
 * to). That is what buys sync, export, search, tags and the per-note lock for free, and it is why
 * a column can also be opened in the full editor when somebody wants to write a paragraph rather
 * than a dot point.
 *
 * ## What this does not claim
 *
 * Nothing here enforces who may write in which column — sharing to specific people is not built
 * yet, so every column belongs to whoever owns the account. The screen therefore says a column is
 * *named after* a person rather than *owned by* them. The day sharing lands, the ownership
 * becomes real and the wording changes with it; until then, claiming a lock that does not exist
 * would be the same mistake as claiming encryption.
 */

export interface ColumnsViewProps {
  readonly groupId: string;
  readonly notes: readonly Note[];
  readonly onChanged: () => void;
}

export function ColumnsView({ groupId, notes, onChanged }: ColumnsViewProps): React.JSX.Element {
  const add = useAddNote();
  const [busy, setBusy] = useState(false);

  async function addColumn(): Promise<void> {
    setBusy(true);
    try {
      // Untitled, and the title is focused the moment it appears. Asking for a name in a modal
      // before there is anything to name is a step nobody wanted.
      await add(groupId);
      onChanged();
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="sec">
      <div className="sec-head">
        <h2 className="sec-title">Side by side</h2>
        <span className="sec-note num">{plural(notes.length, 'column')}</span>
      </div>

      {notes.length === 0 ? (
        <p className="setrow-help">
          Nothing here yet. Add a column for each person, then write your points in your own one.
        </p>
      ) : (
        <ul className="cols">
          {notes.map((note, index) => (
            <Column accent={accentFor(index)} key={note.id} note={note} onChanged={onChanged} />
          ))}
        </ul>
      )}

      <div className="undertext">
        <Btn disabled={busy} icon="plus" onClick={() => void addColumn()} small tone="quiet">
          Add a column
        </Btn>
      </div>
    </section>
  );
}

/**
 * A colour per column, by position.
 *
 * Rose, on the first version: *"it had nice coloured lil coloured edges to each users thingy based
 * on their colour chosen"*. There are no members yet — a column is **named after** a person rather
 * than owned by one until T-45 — so there is no chosen colour to read. Position is the honest
 * stand-in: it is stable for as long as the columns are, and it gives every column its own
 * identity down the whole of its length.
 *
 * `data-gc` is the mechanism the app already uses for a group's own colour: it re-declares all
 * five accent tokens inside that subtree, so the header tint, the hairline and every bead follow
 * from one attribute rather than from colour plumbed through five components.
 */
function accentFor(index: number): string {
  return ACCENT_NAMES[index % ACCENT_NAMES.length] ?? 'rose';
}

function Column({
  note,
  onChanged,
  accent,
}: {
  readonly note: Note;
  readonly onChanged: () => void;
  readonly accent: string;
}): React.JSX.Element {
  const body = useNoteBody(note.id as NoteId);
  const actions = useNoteActions();
  const navigate = useNavigate();
  const [points, setPoints] = useState<readonly Point[]>([]);
  const [title, setTitle] = useState(note.title);
  /*
   * Which row to put the caret in after the next render.
   *
   * Adding a point that you then have to click into is two actions where Rose asked for one:
   * *"each user would click a button to add a new dot point"* — and then type in it.
   */
  const focusOn = useRef<number | null>(null);
  const loadedFrom = useRef<string | null>(null);

  // The body arrives asynchronously, and re-parsing it on every render would throw away whatever
  // is half-typed. Keyed on the text actually loaded, so a later load still lands.
  if (!body.loading && loadedFrom.current !== body.text) {
    loadedFrom.current = body.text;
    setPoints(parsePoints(body.text));
  }

  useEffect(() => {
    setTitle(note.title);
  }, [note.title]);

  function commit(next: readonly Point[]): void {
    setPoints(next);
    void body.write(serializePoints(next));
  }

  return (
    <li className="col" data-gc={accent}>
      <header className="col-head">
        <input
          aria-label="Column name"
          className="col-name"
          onBlur={() => {
            if (title !== note.title) void actions.rename(note.id, title).then(onChanged);
          }}
          onChange={(event) => setTitle(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') event.currentTarget.blur();
          }}
          placeholder="Whose column?"
          value={title}
        />
        <button
          className="col-open"
          onClick={() => navigate({ name: 'note', noteId: note.id as string })}
          title="Open this column as a full note"
          type="button"
        >
          <Icon name="edit" />
          <span className="sr">Open {title === '' ? 'this column' : title} as a full note</span>
        </button>
      </header>

      <ol className="pts">
        {points.map((point, index) => (
          <li
            className={point.depth === 1 ? 'pt is-sub' : 'pt'}
            // biome-ignore lint/suspicious/noArrayIndexKey: a point's identity IS its position
            key={index}
          >
            {/*
              The bead and the number are two elements, not one.
              Merging them put the bead on top of the number and hid it — the original design
              (`docs/stuffs/ui.html`) had `.pb` and `.pnum` separate for exactly this reason.
            */}
            <span aria-hidden="true" className="pt-bead" />
            <span aria-hidden="true" className="pt-num">
              {point.depth === 1 ? '' : `${countAbove(points, index)}.`}
            </span>
            <textarea
              aria-label={`Point ${index + 1} in ${title === '' ? 'this column' : title}`}
              className="pt-text"
              onBlur={() => commit(points)}
              onChange={(event) => setPoints(setPointText(points, index, event.target.value))}
              onPaste={(event) => {
                // A pasted list becomes a list. Pasting thirteen lines into one point makes one
                // point thirteen lines long, which is not what anybody means by pasting a list —
                // and pasting a list you already wrote elsewhere is the normal way a column of
                // reasons gets filled in the first place.
                const text = event.clipboardData.getData('text/plain');
                // One line is an ordinary paste; let the browser do it.
                if (!/[\r\n]/u.test(text)) return;
                event.preventDefault();
                const next = pastePoints(points, index, text);
                focusOn.current = index + (next.length - points.length);
                commit(next);
              }}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  // Enter makes the next point, the way a list in any editor behaves. Shift-Enter
                  // is left alone, so a point can still be more than one line.
                  event.preventDefault();
                  focusOn.current = index + 1;
                  commit(addPoint(points, index, point.depth));
                }
                if (event.key === 'Backspace' && point.text === '' && points.length > 1) {
                  event.preventDefault();
                  focusOn.current = Math.max(0, index - 1);
                  commit(removePoint(points, index));
                }
              }}
              ref={(element) => {
                if (element !== null && focusOn.current === index) {
                  focusOn.current = null;
                  element.focus();
                }
                if (element !== null) {
                  // Grow with the text. A fixed height either clips a long thought or leaves a
                  // column of mostly empty boxes.
                  element.style.height = 'auto';
                  element.style.height = `${element.scrollHeight}px`;
                }
              }}
              rows={1}
              value={point.text}
            />
            <span className="pt-acts">
              <PointButton
                icon="plus"
                label="Add a sub-point under this one"
                onClick={() => {
                  focusOn.current = index + 1;
                  commit(addPoint(points, index, 1));
                }}
              />
              <PointButton
                icon="chevd"
                label="Move this down"
                onClick={() => commit(movePoint(points, index, 1))}
              />
              <PointButton
                icon="x"
                label="Remove this point"
                onClick={() => commit(removePoint(points, index))}
              />
            </span>
          </li>
        ))}
      </ol>

      <Btn
        icon="plus"
        onClick={() => {
          focusOn.current = points.length;
          commit(addPoint(points, points.length - 1, 0));
        }}
        small
        tone="quiet"
      >
        Add a point
      </Btn>
    </li>
  );
}

/** The numbering Rose's sketch asks for: 1., 2., counting only dot points. */
function countAbove(points: readonly Point[], index: number): number {
  let count = 0;
  for (let at = 0; at <= index; at += 1) {
    if (points[at]?.depth === 0) count += 1;
  }
  return count;
}

function PointButton({
  icon,
  label,
  onClick,
}: {
  readonly icon: 'plus' | 'chevd' | 'x';
  readonly label: string;
  readonly onClick: () => void;
}): React.JSX.Element {
  return (
    <button className="pt-btn" onClick={onClick} title={label} type="button">
      <Icon name={icon} />
      <span className="sr">{label}</span>
    </button>
  );
}

/** Whether a group is laid out as columns. One place, so the view and the settings agree. */
export function isColumnsLayout(settings: {
  readonly memberSections: boolean;
  readonly memberSectionDisplay: string;
}): boolean {
  return settings.memberSections && settings.memberSectionDisplay === 'columns';
}
