import type {
  CollectionId,
  Note,
  NoteCreateRequestInput,
  NoteId,
  NoteKind,
  NoteUpdateRequest,
  TagName,
} from '@rosie-notes/schema';
import { newId } from '@rosie-notes/schema';
import { useMemo } from 'react';
import { useWorkspace } from '../session/session-context';
import { useGroupsOptional } from './use-groups';

/**
 * Every write the UI can make, in one place, and all of them offline-safe.
 *
 * Nothing in the views calls `store.updateNote` directly. They call these, which route through
 * the workspace's {@link WriteQueue}: applied now when the server is there, queued on disk when
 * it is not, and replayed in order on reconnect. Having exactly one door means "does this work
 * offline?" has one answer for the whole app rather than one per button.
 */

/** How a bulk verb ended. `failed` is a count, never an exception — see {@link NoteActions}. */
export interface BulkResult {
  readonly done: number;
  readonly failed: number;
}

/** What a caller may say about a new note. The id is ours to mint, and the title may be empty. */
export type NewNoteInput = Partial<Omit<NoteCreateRequestInput, 'id'>>;

export interface NoteActions {
  /** Mints the id locally, so the note is real — and editable — before the server hears of it. */
  create(input?: NewNoteInput): Promise<NoteId>;
  update(id: NoteId, patch: NoteUpdateRequest): Promise<void>;
  rename(id: NoteId, title: string): Promise<void>;
  setKind(id: NoteId, kind: NoteKind): Promise<void>;
  setTags(id: NoteId, tags: readonly TagName[]): Promise<void>;
  setParent(id: NoteId, parentId: NoteId | null): Promise<void>;
  togglePinned(note: Note): Promise<void>;
  toggleArchived(note: Note): Promise<void>;
  trash(id: NoteId): Promise<void>;
  /**
   * The bulk verbs.
   *
   * Each single-note write refreshes the group tree afterwards, because `Group.noteCount` is
   * counted by the server and every figure on screen is derived from it. Looping the single verb
   * over a selection would fire one `GET /v1/groups` per note — fifty writes, fifty tree loads,
   * each describing a tree that is about to change again. These do the writes and recount once.
   *
   * They report counts rather than throwing on the first failure. A bulk action that stops halfway
   * and says only "something went wrong" leaves a person with no idea which half happened, which
   * is the worst possible state to be in after asking to delete forty things.
   */
  trashMany(ids: readonly NoteId[]): Promise<BulkResult>;
  moveMany(ids: readonly NoteId[], groupId: CollectionId): Promise<BulkResult>;
  /** Adds tags to every note, keeping the ones each already has. Never removes. */
  tagMany(notes: readonly Note[], tags: readonly TagName[]): Promise<BulkResult>;
  /** Removes tags from every note that has them. The undo for {@link NoteActions.tagMany}. */
  untagMany(notes: readonly Note[], tags: readonly TagName[]): Promise<BulkResult>;
  restore(id: NoteId): Promise<void>;
  purge(id: NoteId): Promise<void>;
}

/**
 * Run one write per item, counting outcomes instead of stopping at the first failure.
 *
 * Sequential on purpose. The write queue preserves order, and forty parallel writes against a
 * laptop over a tunnel is how a bulk action turns into a timeout — the slow-and-complete version
 * is the one worth having when the alternative is a half-applied delete.
 */
async function runEach<T>(
  items: readonly T[],
  write: (item: T) => Promise<unknown>,
): Promise<BulkResult> {
  let done = 0;
  let failed = 0;
  for (const item of items) {
    try {
      await write(item);
      done += 1;
    } catch {
      failed += 1;
    }
  }
  return { done, failed };
}

export function useNoteActions(): NoteActions {
  const workspace = useWorkspace();
  const tree = useGroupsOptional();
  const reloadGroups = tree?.reload;

  return useMemo<NoteActions>(() => {
    const { writes, adapter } = workspace;

    /**
     * Refresh the group tree after a write that changed how many notes are in one.
     *
     * `Group.noteCount` is counted by the server and only arrives with `GET /v1/groups`, and the
     * tree is loaded once per session. Without this, adding a note updates the *listing* — which
     * refetches — while every count derived from the tree keeps its load-time value: the row on
     * Home, the parent group's summary, the "N notes in here and everything under it" footer, and
     * the whole-account total. They come back only on a hard reload, which is precisely the shape
     * of "the numbers are wrong but I cannot say since when".
     *
     * Deliberately fire-and-forget: a count catching up a moment late is fine, and a failed
     * refresh must not make the write it followed look like it failed.
     */
    const recount = (): void => {
      void reloadGroups?.();
    };

    return {
      async create(input = {}) {
        const noteId = newId<'note'>(adapter.clock());
        await writes.submit({
          kind: 'create',
          noteId,
          input: { kind: 'page', ...input, title: input.title ?? '', id: noteId },
        });
        recount();
        return noteId;
      },
      async update(id, patch) {
        await writes.submit({ kind: 'update', noteId: id, patch });
        // Moving a note between groups changes two groups' counts; nothing else in a patch does.
        if (patch.collectionIds !== undefined) recount();
      },
      async rename(id, title) {
        await writes.submit({ kind: 'update', noteId: id, patch: { title } });
      },
      async setKind(id, kind) {
        await writes.submit({ kind: 'update', noteId: id, patch: { kind } });
      },
      async setTags(id, tags) {
        await writes.submit({ kind: 'update', noteId: id, patch: { tags: [...tags] } });
      },
      async setParent(id, parentId) {
        await writes.submit({ kind: 'update', noteId: id, patch: { parentId } });
      },
      async togglePinned(note) {
        await writes.submit({ kind: 'update', noteId: note.id, patch: { pinned: !note.pinned } });
      },
      async toggleArchived(note) {
        await writes.submit({
          kind: 'update',
          noteId: note.id,
          patch: { archived: !note.archived },
        });
      },
      async trash(id) {
        await writes.submit({ kind: 'trash', noteId: id });
        recount();
      },
      async trashMany(ids) {
        const result = await runEach(ids, (id) => writes.submit({ kind: 'trash', noteId: id }));
        recount();
        return result;
      },
      async moveMany(ids, groupId) {
        const result = await runEach(ids, (id) =>
          writes.submit({ kind: 'update', noteId: id, patch: { collectionIds: [groupId] } }),
        );
        recount();
        return result;
      },
      async tagMany(notes, tags) {
        return runEach(notes, (note) => {
          const next = new Set<string>(note.tags as readonly string[]);
          for (const tag of tags) next.add(tag as string);
          // Nothing to say to the server when the note already carries every tag asked for.
          if (next.size === note.tags.length) return Promise.resolve();
          return writes.submit({
            kind: 'update',
            noteId: note.id,
            patch: { tags: [...next] as TagName[] },
          });
        });
      },
      async untagMany(notes, tags) {
        const drop = new Set<string>(tags as readonly string[]);
        return runEach(notes, (note) => {
          const next = (note.tags as readonly string[]).filter((tag) => !drop.has(tag));
          if (next.length === note.tags.length) return Promise.resolve();
          return writes.submit({
            kind: 'update',
            noteId: note.id,
            patch: { tags: next as TagName[] },
          });
        });
      },
      async restore(id) {
        await writes.submit({ kind: 'restore', noteId: id });
        recount();
      },
      async purge(id) {
        await writes.submit({ kind: 'purge', noteId: id });
        recount();
      },
    };
  }, [workspace, reloadGroups]);
}
