import type { ConfiguredProject, GroupSettingsOverrides } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useUserConfig } from '../hooks/use-user-config';
import { Btn, Callout, SetGroup, SetRow, Sheet } from './primitives';
import { useToast } from './toasts';

/**
 * Creating the projects a config lists — arranged the way the disk is.
 *
 * Two rounds of getting this wrong, both worth keeping written down.
 *
 * **First**, the config carried no projects at all, so importing it created nothing and said so
 * nowhere. Rose: *"i didnt get any prefilled groups or groups added or anything"*.
 *
 * **Then** it created every project as a **top-level group** — ninety-two rows at the root. Rose:
 * *"it was meant to all be under a single main code stuffs group … grouped how i group them here
 * based on the top level folders"*. The config already knew each project's category, in `type`; it
 * was only ever used to resolve a path. Now it shapes the tree too: one root group, a subgroup per
 * type, projects inside those.
 *
 * **Listed is offered, never created**, and nothing is ticked by default — a file must not be able
 * to reshape somebody's account by being opened.
 *
 * The clean-up below exists because of the second mistake. An import that can make ninety-two
 * groups should be able to take them back, and doing that by hand ninety-two times is not a
 * recovery plan.
 */

/** A group whose name matches a configured project and which nothing has been put into yet. */
interface Removable {
  readonly id: string;
  readonly name: string;
}

export function ConfigProjectsSection(): React.JSX.Element | null {
  const { config } = useUserConfig();
  const tree = useGroups();
  const [adding, setAdding] = useState(false);
  const [cleaning, setCleaning] = useState(false);

  const existing = useMemo(
    () => new Set([...tree.byId.values()].map((group) => group.name.trim().toLowerCase())),
    [tree.byId],
  );

  /**
   * Top-level groups that came from this config and are still empty.
   *
   * Deliberately narrow on all three counts: **top-level** (the flat import's mistake, and never a
   * correctly-nested one), **named in the config**, and **empty**. A group Rose has since written
   * in is not clean-up, it is their work.
   */
  const strays = useMemo<Removable[]>(() => {
    const named = new Set(config.projects.map((p) => p.name.trim().toLowerCase()));
    return tree
      .children(null)
      .filter((group) => named.has(group.name.trim().toLowerCase()))
      .filter((group) => {
        const { notes, groups } = tree.tally(group.id as string);
        return notes === 0 && groups === 0;
      })
      .map((group) => ({ id: group.id as string, name: group.name }));
  }, [config.projects, tree]);

  if (config.projects.length === 0) return null;

  const missing = config.projects.filter((p) => !existing.has(p.name.trim().toLowerCase()));

  return (
    <>
      <SetGroup title="Projects in your config">
        <SetRow
          help={
            missing.length === 0
              ? 'Every project your config lists already exists here.'
              : 'Importing a config never creates groups on its own. Pick the ones you want.'
          }
          label="From your config"
          value={
            <span>
              {config.projects.length - missing.length} of {config.projects.length} created
            </span>
          }
        />
        <SetRow
          label=""
          value={
            <Btn disabled={missing.length === 0} onClick={() => setAdding(true)}>
              {missing.length === 0 ? 'Nothing to add' : `Add ${missing.length} projects…`}
            </Btn>
          }
        />
        {strays.length > 0 && (
          <SetRow
            help="Empty project groups sitting at the top level. An earlier import put them there instead of nesting them. Anything you have written in is left alone."
            label="Tidy up"
            value={
              <Btn onClick={() => setCleaning(true)} tone="quiet">
                Remove {strays.length} empty…
              </Btn>
            }
          />
        )}
      </SetGroup>
      {adding && <CreateSheet onClose={() => setAdding(false)} projects={missing} />}
      {cleaning && <CleanupSheet onClose={() => setCleaning(false)} strays={strays} />}
    </>
  );
}

function CreateSheet({
  projects,
  onClose,
}: {
  readonly projects: readonly ConfiguredProject[];
  readonly onClose: () => void;
}): React.JSX.Element {
  const tree = useGroups();
  const { config } = useUserConfig();
  const toast = useToast();
  const [chosen, setChosen] = useState<ReadonlySet<string>>(new Set());
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);

  const { rootGroup, groupByType } = config.projectLayout;
  const labelFor = (type: string): string =>
    config.paths.types.find((t) => t.id === type)?.label ?? type;

  function toggle(name: string): void {
    setChosen((current) => {
      const next = new Set(current);
      if (next.has(name)) next.delete(name);
      else next.add(name);
      return next;
    });
  }

  /** Find a child by name, or make it. Re-running an import must not duplicate the scaffolding. */
  async function ensureGroup(name: string, parentId: string | null): Promise<string> {
    const found = tree
      .children(parentId)
      .find((group) => group.name.trim().toLowerCase() === name.trim().toLowerCase());
    if (found !== undefined) return found.id as string;
    const made = await tree.create({
      name,
      ...(parentId === null ? {} : { parentId: parentId as never }),
    });
    return made.id as string;
  }

  async function create(): Promise<void> {
    setBusy(true);
    setFailure(null);
    let made = 0;
    let failed = 0;
    try {
      const rootId = rootGroup === '' ? null : await ensureGroup(rootGroup, null);
      // Cached so twenty Rust projects make one "Rust" subgroup rather than twenty.
      const typeGroups = new Map<string, string | null>();

      for (const project of projects) {
        if (!chosen.has(project.name)) continue;

        let parentId = rootId;
        if (groupByType) {
          if (!typeGroups.has(project.type)) {
            typeGroups.set(project.type, await ensureGroup(labelFor(project.type), rootId));
          }
          parentId = typeGroups.get(project.type) ?? rootId;
        }

        const settings = {
          codeProject: {
            enabled: true,
            projectType: project.type,
            projectName: project.name,
            linkedFolder: null,
            status: project.status,
            handoffProject: project.handoffProject,
            tags: [...project.tags],
            mainFile: { enabled: false, template: '' },
            orchestratorPrompt: { enabled: false, template: '' },
            checkDiskChanges: false,
          },
        } as GroupSettingsOverrides;

        try {
          await tree.create({
            name: project.name,
            ...(parentId === null ? {} : { parentId: parentId as never }),
            settings,
          });
          made += 1;
        } catch {
          // One bad row must not lose the other ninety-one. A partial success is the normal
          // outcome of a bulk create, so it is counted and reported rather than thrown.
          failed += 1;
        }
      }
      await tree.reload();
      toast.show(
        failed === 0
          ? `Created ${made} projects.`
          : `Created ${made}, and ${failed} failed. Nothing else changed.`,
        failed === 0 ? undefined : { tone: 'clay', icon: 'warn' },
      );
      onClose();
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'Could not create them.');
    } finally {
      setBusy(false);
    }
  }

  const where =
    rootGroup === ''
      ? groupByType
        ? 'in a group per kind, at the top level'
        : 'at the top level'
      : groupByType
        ? `under ${rootGroup}, in a group per kind`
        : `under ${rootGroup}`;

  return (
    <Sheet
      footer={
        <Btn disabled={chosen.size === 0 || busy} onClick={() => void create()} tone="primary">
          {busy ? 'Creating…' : `Create ${chosen.size}`}
        </Btn>
      }
      onClose={onClose}
      sub={`${projects.length} in your config that do not exist here yet`}
      title="Add projects"
    >
      <div style={{ display: 'grid', gap: 10 }}>
        <Callout icon="eye" tone="quiet">
          These become <b>groups</b>, {where} — the same shape as your folders. Nothing is written
          to your disk; the linked folder is worked out when you ask for it.
        </Callout>

        <div style={{ display: 'flex', gap: 8 }}>
          <Btn onClick={() => setChosen(new Set(projects.map((p) => p.name)))}>Select all</Btn>
          <Btn disabled={chosen.size === 0} onClick={() => setChosen(new Set())}>
            Clear
          </Btn>
        </div>

        <div style={{ display: 'grid', gap: 2, maxHeight: '46vh', overflowY: 'auto' }}>
          {projects.map((project) => (
            <label className="setrow" key={project.name}>
              <input
                checked={chosen.has(project.name)}
                onChange={() => toggle(project.name)}
                type="checkbox"
              />
              <span className="setrow-label">{project.name}</span>
              <span className="setrow-help">
                {labelFor(project.type)}
                {project.handoffProject === null ? '' : ' · has handoff docs'}
              </span>
            </label>
          ))}
        </div>

        {failure !== null && (
          <Callout icon="warn" tone="clay">
            {failure}
          </Callout>
        )}
      </div>
    </Sheet>
  );
}

function CleanupSheet({
  strays,
  onClose,
}: {
  readonly strays: readonly Removable[];
  readonly onClose: () => void;
}): React.JSX.Element {
  const tree = useGroups();
  const toast = useToast();
  const [busy, setBusy] = useState(false);

  async function remove(): Promise<void> {
    setBusy(true);
    let gone = 0;
    let failed = 0;
    for (const stray of strays) {
      try {
        // No `deleteNotes` — these are empty by definition, and passing it would make this
        // destructive against a group that gained a note between listing and confirming.
        await tree.remove(stray.id as never);
        gone += 1;
      } catch {
        failed += 1;
      }
    }
    await tree.reload();
    toast.show(
      failed === 0 ? `Removed ${gone} empty groups.` : `Removed ${gone}, and ${failed} would not.`,
      failed === 0 ? undefined : { tone: 'clay', icon: 'warn' },
    );
    setBusy(false);
    onClose();
  }

  return (
    <Sheet
      footer={
        <Btn disabled={busy} onClick={() => void remove()} tone="danger">
          {busy ? 'Removing…' : `Remove ${strays.length}`}
        </Btn>
      }
      onClose={onClose}
      sub="Empty, at the top level, and named in your config"
      title="Remove empty project groups"
    >
      <div style={{ display: 'grid', gap: 10 }}>
        <Callout icon="warn" tone="quiet">
          Every one of these is <b>empty</b> — no notes, no subgroups. Anything you have written in
          is not listed here and will not be touched.
        </Callout>
        <div style={{ display: 'grid', gap: 2, maxHeight: '46vh', overflowY: 'auto' }}>
          {strays.map((stray) => (
            <div className="setrow" key={stray.id}>
              <span className="setrow-label">{stray.name}</span>
            </div>
          ))}
        </div>
      </div>
    </Sheet>
  );
}
