import type { NoteListRequestInput, StoryStatus, TagName } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useNoteQuery } from '../hooks/use-note-query';
import { useStoryLibrary } from '../hooks/use-stories';
import { PageHeader } from './chrome';
import { NoteRow } from './group-view';
import { plural } from './labels';
import { Segmented } from './primitives';
import { List, SkeletonRows } from './rail';
import { EmptyState, ErrorState, OfflineBanner } from './states';

/**
 * The story library, browsable (T-38): themes, creators and the free-text facets, each one a
 * filter over the same list beneath them.
 *
 * Rose: *"search across stories for what you want for example transformation, animal
 * transformation"* — that is the **themes** row. Tags are the mechanism the rest of the app
 * already has for exactly this, so "search for a theme" is a tag filter here rather than a new
 * kind of field nobody else's notes get.
 *
 * Every row is a {@link Segmented} control rather than a wall of chips: one choice at a time per
 * dimension, `All` always included, and every option's own count baked into its label — the same
 * shape `StatusFilterBar` in `project-status.tsx` already uses for exactly this reason, so a
 * screen that filters five different ways still reads as one idea repeated, not five widgets.
 * `useNoteQuery` runs the actual list; nothing here talks to `fetch` on its own.
 */

const STORY_STATUS_LABEL: Record<StoryStatus, string> = {
  unknown: 'Unknown',
  ongoing: 'Ongoing',
  complete: 'Complete',
  hiatus: 'On hiatus',
  abandoned: 'Abandoned',
};

export function StoriesView(): React.JSX.Element {
  const library = useStoryLibrary();
  const [tag, setTag] = useState<string | null>(null);
  const [creator, setCreator] = useState<string | null>(null);
  const [source, setSource] = useState<string | null>(null);
  const [storyType, setStoryType] = useState<string | null>(null);
  const [status, setStatus] = useState<StoryStatus | null>(null);

  const query = useMemo<NoteListRequestInput>(
    () => ({
      kind: 'story',
      limit: 100,
      ...(tag === null ? {} : { tag: tag as TagName }),
      ...(creator === null ? {} : { creator }),
      ...(source === null ? {} : { storySource: source }),
      ...(storyType === null ? {} : { storyType }),
      ...(status === null ? {} : { storyStatus: status }),
    }),
    [tag, creator, source, storyType, status],
  );
  const stories = useNoteQuery(query);

  return (
    <>
      <PageHeader
        sub="Every theme, creator and kind already in use — pick one to narrow the list below."
        title="Stories"
      />

      {library.failed && (
        <p className="setrow-help">
          The filters below could not be loaded. The list itself still works.
        </p>
      )}

      {library.themes.length > 0 && (
        <FacetRow
          allLabel="All themes"
          label="Theme"
          onChange={setTag}
          options={library.themes.map((theme) => ({
            value: theme.tag,
            label: `${theme.tag} ${theme.storyCount}`,
          }))}
          value={tag}
        />
      )}

      {library.creators.length > 0 && (
        <FacetRow
          allLabel="All creators"
          label="Creator"
          onChange={setCreator}
          options={library.creators.map((entry) => ({
            value: entry.name,
            label: `${entry.name} ${entry.workCount}`,
          }))}
          value={creator}
        />
      )}

      {library.facets.storyType.length > 0 && (
        <FacetRow
          allLabel="All types"
          label="Type"
          onChange={setStoryType}
          options={library.facets.storyType.map((facet) => ({
            value: facet.value,
            label: `${facet.value} ${facet.count}`,
          }))}
          value={storyType}
        />
      )}

      {library.facets.source.length > 0 && (
        <FacetRow
          allLabel="All sources"
          label="Source"
          onChange={setSource}
          options={library.facets.source.map((facet) => ({
            value: facet.value,
            label: `${facet.value} ${facet.count}`,
          }))}
          value={source}
        />
      )}

      {library.facets.status.length > 0 && (
        <FacetRow
          allLabel="Any status"
          label="Status"
          onChange={(value) => setStatus(value === null ? null : (value as StoryStatus))}
          options={library.facets.status.map((facet) => ({
            value: facet.value,
            label: `${STORY_STATUS_LABEL[facet.value as StoryStatus] ?? facet.value} ${facet.count}`,
          }))}
          value={status}
        />
      )}

      <section className="sec">
        <div className="sec-head">
          <h2 className="sec-title">Stories</h2>
          <span className="sec-note num">{plural(stories.notes.length, 'result')}</span>
        </div>

        {stories.stale && <OfflineBanner what="stories" />}

        {stories.loading && stories.notes.length === 0 ? (
          <SkeletonRows count={4} />
        ) : stories.error !== null ? (
          <ErrorState
            body="The server did not answer and this device has nothing cached for this filter."
            onRetry={stories.reload}
            title="These stories could not be loaded"
          />
        ) : stories.notes.length === 0 ? (
          <EmptyState
            body="Nothing in your library matches every filter at once. Clear one and try again."
            title="No story matches"
          />
        ) : (
          <List label="Stories">
            {stories.notes.map((note) => (
              <NoteRow key={note.id} note={note} onChanged={stories.reload} />
            ))}
          </List>
        )}
      </section>
    </>
  );
}

/** One filter dimension: `All …`, then every value in use, each with its own count. */
function FacetRow({
  label,
  allLabel,
  options,
  value,
  onChange,
}: {
  readonly label: string;
  readonly allLabel: string;
  readonly options: readonly { readonly value: string; readonly label: string }[];
  readonly value: string | null;
  readonly onChange: (next: string | null) => void;
}): React.JSX.Element {
  return (
    <section className="sec">
      <div className="sec-head">
        <h2 className="sec-title">{label}</h2>
      </div>
      <div className="statusbar">
        <Segmented
          label={`Filter stories by ${label.toLowerCase()}`}
          onChange={(next) => onChange(next === '' ? null : next)}
          options={[{ value: '', label: allLabel }, ...options]}
          value={value ?? ''}
        />
      </div>
    </section>
  );
}
