import type { IncomingShare } from '@rosie-notes/schema';
import { useIncomingShares } from '../hooks/use-incoming-shares';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { ago, displayTitle, plural, shortWhen } from './labels';
import { Btn, Chip, Sep } from './primitives';
import { List, Row, SkeletonRows } from './rail';
import { EmptyState, ErrorState } from './states';

/**
 * "Shared with me": every note somebody else has handed this account access to.
 *
 * There is nowhere else in the app a note like this could ever surface — `docs/api.md` is
 * explicit that the account's own note listing compiles `notes.user_id = you` into every query on
 * purpose, so a note owned by somebody else is invisible everywhere except here. This screen is
 * the entire discovery path for a `kind: 'user'` share, which is why it earns a route of its own
 * rather than a filter chip on Home.
 *
 * Opening a row goes to the ordinary `{ name: 'note' }` route — **a shared note is a note**, not
 * a special screen. `NoteView` is the thing that decides, generically and by comparing
 * `note.ownerId` against the signed-in account, whether to grey the editor out; this screen's job
 * ends at "here is what exists and whose it is".
 */

export function SharedWithMeView(): React.JSX.Element {
  const shares = useIncomingShares();
  const navigate = useNavigate();

  return (
    <>
      <PageHeader
        sub={
          shares.loading && shares.shares.length === 0 ? (
            <span>Looking…</span>
          ) : (
            <span>{plural(shares.shares.length, 'note')} shared with you.</span>
          )
        }
        title="Shared with me"
      />
      <SharedWithMeBody
        error={shares.error !== null}
        hasMore={shares.hasMore}
        loading={shares.loading}
        onLoadMore={shares.loadMore}
        onOpen={(item) => navigate({ name: 'note', noteId: item.note.id as string })}
        onRetry={shares.reload}
        shares={shares.shares}
      />
    </>
  );
}

export interface SharedWithMeBodyProps {
  readonly shares: readonly IncomingShare[];
  readonly loading: boolean;
  readonly error: boolean;
  readonly hasMore: boolean;
  readonly onOpen: (item: IncomingShare) => void;
  readonly onRetry: () => void;
  readonly onLoadMore: () => void;
}

/**
 * The presentational half, taking plain props rather than reading the hook itself.
 *
 * Split out so the rendering — the one thing worth pinning with a test — does not need a
 * workspace, a session or a fake server behind it: a plain `render()` with a handful of fixture
 * shares is enough to prove an owner's name, a permission and the empty state all show up right.
 */
export function SharedWithMeBody({
  shares,
  loading,
  error,
  hasMore,
  onOpen,
  onRetry,
  onLoadMore,
}: SharedWithMeBodyProps): React.JSX.Element {
  if (loading && shares.length === 0) {
    return <SkeletonRows count={3} />;
  }

  if (error && shares.length === 0) {
    return (
      <ErrorState
        body="Nothing shared with you is kept on this device, so there is nothing to fall back to offline."
        onRetry={onRetry}
        title="Could not load what's shared with you"
      />
    );
  }

  if (shares.length === 0) {
    return (
      <EmptyState
        body="When somebody on this server shares one of their notes with your account — by username, for reading or for editing — it turns up here. Nothing you do creates one: ask whoever has the note to share it with your username."
        title="Nothing has been shared with you yet"
      />
    );
  }

  return (
    <>
      <List label="Shared with you">
        {shares.map((item) => (
          <IncomingShareRow item={item} key={item.shareId} onOpen={() => onOpen(item)} />
        ))}
      </List>
      {hasMore && (
        <div className="undertext">
          <Btn onClick={onLoadMore} small tone="quiet">
            Show more
          </Btn>
        </div>
      )}
    </>
  );
}

export interface IncomingShareRowProps {
  readonly item: IncomingShare;
  readonly onOpen: () => void;
}

/**
 * One shared note: whose it is, and — before anybody has to find out by typing — whether it can
 * be changed at all.
 *
 * The permission chip is the point of this whole row. `docs/api.md` says this endpoint exists so
 * "a client can... grey out an editor before the server has to refuse a write", and the row is
 * where that promise starts: the same word (`Read only` / `Can edit`) reappears on the note screen
 * itself once the row is opened, so nothing here is a claim the next screen might contradict.
 */
export function IncomingShareRow({ item, onOpen }: IncomingShareRowProps): React.JSX.Element {
  const title = displayTitle(item.note.title);
  const writable = item.permission === 'write';

  return (
    <Row
      excerpt={item.note.excerpt}
      kind="note"
      label={`${title}, shared by ${item.owner.displayName}, ${writable ? 'you can edit' : 'read only'}`}
      mark="none"
      meta={
        <>
          <span>{item.owner.displayName}</span>
          <Sep />
          <Chip icon={writable ? 'edit' : 'lock'} tone={writable ? 'sage' : 'private'}>
            {writable ? 'Can edit' : 'Read only'}
          </Chip>
          <Sep />
          <span>shared {ago(item.sharedAt)}</span>
          {item.expiresAt !== null && (
            <>
              <Sep />
              <span>until {shortWhen(item.expiresAt)}</span>
            </>
          )}
        </>
      }
      onOpen={onOpen}
      title={title}
    />
  );
}
