import type { Attachment, AttachmentId, NoteId } from '@rosie-notes/schema';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useWorkspace } from '../session/session-context';
import { Icon, type IconName } from './icons';
import { ago, plural } from './labels';
import { Btn, Callout } from './primitives';
import { useToast } from './toasts';

/**
 * Files kept with a note.
 *
 * Rose's use for it, in their own words: *"i wanna be able to upload some pdf's of things like
 * school report cards, assessment thingies, ect that im given by doctors so its all in a single
 * managable place"*. So the first-class case here is a **document somebody else handed you** —
 * not an inline image the editor would embed. That is why this is a list with names, sizes and
 * dates rather than a gallery.
 *
 * ## The sentence that has to be here
 *
 * `DECISIONS.md` D-03: the product claims **no encryption of any kind**, and says *who can read a
 * thing* rather than how it is stored. An assessment from a doctor is exactly the file somebody
 * would like reassurance about, which is exactly why the reassurance has to be true: whoever runs
 * the server can read it. Same wording as the sign-in screen and the backup screen, deliberately.
 */

/** Bytes, in the units a person reads. */
export function fileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

/** What kind the server should file it under, from the browser's own guess at the type. */
export function kindFor(mime: string): 'image' | 'audio' | 'video' | 'file' {
  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('audio/')) return 'audio';
  if (mime.startsWith('video/')) return 'video';
  return 'file';
}

/** A PDF should not look like a photo in a list. */
export function iconFor(attachment: { readonly mime: string }): IconName {
  if (attachment.mime.startsWith('image/')) return 'image';
  if (attachment.mime.startsWith('audio/')) return 'flask';
  return 'doc';
}

/**
 * The empty state, which differs by whether the viewer may add anything.
 *
 * Exported so the wording is testable without rendering: "nothing here yet" reads as an
 * invitation, and on somebody else's note that invitation is a lie.
 */
export function canAttachCopy(canAttach: boolean): string {
  return canAttach
    ? 'Nothing attached yet. A report card, an assessment, a screenshot — drop it here or pick one, and it stays with this note.'
    : 'No files on this note. Files belong to whoever owns the note, so they are the one who can add them.';
}

export interface AttachmentsProps {
  readonly noteId: NoteId;
  /**
   * Whether this viewer may add or remove files.
   *
   * False on a note somebody else owns, even with a write grant: the server scopes attachments to
   * the note's owner and charges the quota to them. Listing and downloading stay available —
   * a file on a note you can read is part of what that note says.
   */
  readonly canAttach?: boolean;
}

export function Attachments({ noteId, canAttach = true }: AttachmentsProps): React.JSX.Element {
  const workspace = useWorkspace();
  const toast = useToast();
  const picker = useRef<HTMLInputElement>(null);
  const [items, setItems] = useState<readonly Attachment[]>([]);
  const [busy, setBusy] = useState<string | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);

  const load = useCallback(async () => {
    try {
      const page = await workspace.client.attachments.list({ noteId });
      setItems(page.items);
    } catch {
      // Offline, or an older server. A note with no file list is still a readable note, so this
      // stays quiet rather than putting an error over somebody's writing.
      setItems([]);
    }
  }, [noteId, workspace]);

  useEffect(() => {
    void load();
  }, [load]);

  async function add(files: readonly File[]): Promise<void> {
    setFailure(null);
    for (const file of files) {
      setBusy(file.name);
      try {
        const bytes = new Uint8Array(await file.arrayBuffer());
        const mime = file.type === '' ? 'application/octet-stream' : file.type;
        await workspace.client.attachments.upload({
          noteId,
          filename: file.name,
          mime,
          bytes,
          kind: kindFor(mime),
        });
      } catch (error) {
        // Named, and the loop continues: one refused file must not lose the other four somebody
        // dropped in together.
        setFailure(
          `${file.name} — ${error instanceof Error ? error.message : 'could not be uploaded.'}`,
        );
      }
    }
    setBusy(null);
    await load();
    toast.show('Files added.', { icon: 'doc' });
  }

  async function open(attachment: Attachment): Promise<void> {
    try {
      // `GET /v1/attachments/:id` mints a short-lived token for the content route, so the file can
      // be opened in a tab without the app handing its own bearer token to the address bar.
      const fresh = await workspace.client.attachments.get(attachment.id);
      const url = fresh.downloadUrl;
      if (url === null) {
        setFailure('That file has no address yet — it may still be uploading.');
        return;
      }
      globalThis.open(url, '_blank', 'noopener,noreferrer');
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'That file could not be opened.');
    }
  }

  async function remove(attachment: Attachment): Promise<void> {
    await workspace.client.attachments.remove(attachment.id as AttachmentId);
    setItems((current) => current.filter((entry) => entry.id !== attachment.id));
    toast.show(`${attachment.filename} removed.`, { icon: 'trash' });
  }

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: a drop zone is not a control
    <section
      className={dragging ? 'files is-dragging' : 'files'}
      onDragLeave={() => setDragging(false)}
      onDragOver={(event) => {
        event.preventDefault();
        setDragging(true);
      }}
      onDrop={(event) => {
        event.preventDefault();
        setDragging(false);
        if (!canAttach) {
          return;
        }
        void add([...event.dataTransfer.files]);
      }}
    >
      <div className="sec-head">
        <h2 className="sec-title">Files</h2>
        <span className="sec-note num">{plural(items.length, 'file')}</span>
      </div>

      {items.length === 0 ? (
        <p className="setrow-help">
          {canAttachCopy(canAttach)}
        </p>
      ) : (
        <ul className="filelist">
          {items.map((attachment) => (
            <li className="filerow" key={attachment.id}>
              <span className="fileicon">
                <Icon name={iconFor(attachment)} />
              </span>
              <span className="filemain">
                <span className="filename">{attachment.filename}</span>
                <span className="filemeta num">
                  {fileSize(attachment.sizeBytes)} · added {ago(attachment.createdAt)}
                </span>
              </span>
              <span className="fileacts">
                <Btn onClick={() => void open(attachment)} small tone="quiet">
                  Open
                </Btn>
                {canAttach && (
                  <Btn onClick={() => void remove(attachment)} small tone="quiet">
                    Remove
                  </Btn>
                )}
              </span>
            </li>
          ))}
        </ul>
      )}

      {canAttach && (
        <div className="undertext">
          <Btn
            disabled={busy !== null}
            icon="plus"
            onClick={() => picker.current?.click()}
            small
            tone="quiet"
          >
            {busy === null ? 'Add a file' : `Uploading ${busy}…`}
          </Btn>
        </div>
      )}
      <input
        className="sr"
        multiple
        onChange={(event) => {
          const files = [...(event.target.files ?? [])];
          event.target.value = '';
          if (files.length > 0) void add(files);
        }}
        ref={picker}
        type="file"
      />

      {/* Who can read it, never how it is stored — D-03. An assessment from a doctor is exactly
          the file somebody would like reassurance about, which is exactly why the line has to be
          the true one. */}
      <Callout icon="eye" tone="quiet">
        Whoever runs this server can read anything you attach here. Nobody else can, unless you
        share the note.
      </Callout>

      {failure !== null && (
        <Callout icon="warn" tone="clay">
          {failure}
        </Callout>
      )}
    </section>
  );
}
