import type { CollectionId, GroupStructure } from '@rosie-notes/schema';
import { useCallback } from 'react';
import { useGroups } from './use-groups';
import { useNoteActions } from './use-note-actions';

/**
 * Turn a starting point's **structure** into real subgroups and real notes.
 *
 * A structure is a list of names, so this is a list of ordinary creates — which is the point.
 * Nothing it makes is special: the sections are groups, the starter notes are notes, and neither
 * records where it came from. Renaming or deleting any of them is exactly as free as it would be
 * had somebody made them by hand (`group-structure.ts`).
 *
 * **Sequential on purpose.** Positions are handed out in creation order, so `Design` before
 * `Production` is a consequence of awaiting one at a time rather than something a sort has to
 * repair later.
 *
 * **A failure part-way through is reported, not thrown.** The group itself already exists by the
 * time this runs, and destroying it because the fourth section clashed with a name would be a
 * worse answer than a group with six sections and a sentence saying so. Subgroup creation is the
 * one part that needs the server — notes go through the offline write queue — so this is also the
 * shape of "made a game project on a train".
 */

export interface StructureOutcome {
  readonly groups: number;
  readonly notes: number;
  /** Sections that could not be created. Their notes are skipped rather than misfiled. */
  readonly failed: number;
}

export type CreateStructure = (
  groupId: CollectionId,
  structure: GroupStructure,
) => Promise<StructureOutcome>;

export function useCreateStructure(): CreateStructure {
  const tree = useGroups();
  const actions = useNoteActions();

  return useCallback(
    async (groupId, structure) => {
      let groups = 0;
      let notes = 0;
      let failed = 0;

      async function addNotes(
        target: CollectionId,
        entries: GroupStructure['notes'],
      ): Promise<void> {
        for (const note of entries) {
          await actions.create({
            title: note.title,
            kind: note.kind,
            collectionIds: [target],
            ...(note.body === '' ? {} : { body: { format: 'markdown', text: note.body } }),
          });
          notes += 1;
        }
      }

      await addNotes(groupId, structure.notes);

      for (const subgroup of structure.subgroups) {
        let created: CollectionId;
        try {
          created = (await tree.create({ name: subgroup.name, parentId: groupId })).id;
        } catch {
          failed += 1;
          continue;
        }
        groups += 1;
        await addNotes(created, subgroup.notes);
      }

      return { groups, notes, failed };
    },
    [tree, actions],
  );
}
