import type { CollectionId, Group, TagName } from '@rosie-notes/schema';
import { useCallback, useMemo, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useNoteActions } from '../hooks/use-note-actions';
import { Icon } from './icons';
import { plural } from './labels';
import { Btn, Callout, Sheet, Switch } from './primitives';
import { tagTally, useSelection } from './selection-context';
import { useToast } from './toasts';

/**
 * What you can do to a selection, and the bar that offers it.
 *
 * Fixed to the bottom because that is where a thumb is and where the tab bar already lives on a
 * phone — it sits directly above that rather than over it, so the selection never covers the way
 * out of the screen it was made on.
 *
 * Three verbs, all of them recoverable: **move** (reversible by moving back), **tag** (reversible
 * by untagging) and **delete** (into the trash, never a purge). Nothing here can destroy anything,
 * which is the licence a bulk action needs before it is safe to put one tap away from forty notes.
 */

/**
 * Dropping a selection onto a group row.
 *
 * Rose asked for it in the same breath as the tickboxes: *"then you can like drag to move all
 * selected"*. The drag carries no payload — the selection is read from state — so this is the
 * same move the sheet performs, reached with a shorter gesture.
 *
 * Returns `undefined` when there is nothing to drop or the target is itself selected, which is
 * what makes a row stop advertising itself as a drop site rather than accepting a move into
 * itself and quietly detaching a whole branch.
 */
export function useSelectionDrop(targetGroupId: string): (() => void) | undefined {
  const tree = useGroups();
  const actions = useNoteActions();
  const selection = useSelection();
  const toast = useToast();

  const drop = useCallback(() => {
    void (async () => {
      const target = targetGroupId as CollectionId;
      const noteIds = selection.noteIds();
      const groupIds = selection.groupIds();
      // Anything whose ancestry passes through the selection would be moved inside itself.
      const selected = new Set<string>(groupIds as readonly string[]);
      const wouldDetach =
        selected.has(targetGroupId) ||
        tree.chain(targetGroupId).some((entry) => selected.has(entry.id as string));
      if (wouldDetach) {
        toast.show('A group cannot go inside itself.', { tone: 'clay', icon: 'warn' });
        return;
      }

      let moved = 0;
      let failed = 0;
      for (const id of groupIds) {
        try {
          await tree.update(id, { parentId: target });
          moved += 1;
        } catch {
          failed += 1;
        }
      }
      if (noteIds.length > 0) {
        const result = await actions.moveMany(noteIds, target);
        moved += result.done;
        failed += result.failed;
      }
      await tree.reload();
      selection.clear();
      const name = tree.byId.get(targetGroupId)?.name ?? 'there';
      toast.show(
        failed === 0
          ? `Moved ${moved} into ${name}.`
          : `Moved ${moved} into ${name}, and ${failed} would not.`,
        failed === 0 ? { icon: 'move' } : { tone: 'clay', icon: 'warn' },
      );
    })();
  }, [actions, selection, targetGroupId, toast, tree]);

  if (!selection.active) return undefined;
  return drop;
}

type Job = 'move' | 'tag' | 'delete' | null;

export function SelectionBar(): React.JSX.Element | null {
  const selection = useSelection();
  const [job, setJob] = useState<Job>(null);

  if (!selection.active) return null;

  const noteIds = selection.noteIds();
  const groupIds = selection.groupIds();
  const parts: string[] = [];
  if (noteIds.length > 0) parts.push(plural(noteIds.length, 'note'));
  if (groupIds.length > 0) parts.push(plural(groupIds.length, 'group'));

  return (
    <>
      <section aria-label="Selection" aria-live="polite" className="selbar">
        <div className="selbar-inner">
          <span className="selbar-count num">{parts.join(' and ')} selected</span>
          <div className="selbar-acts">
            <Btn icon="move" onClick={() => setJob('move')} small>
              Move
            </Btn>
            <Btn
              disabled={noteIds.length === 0}
              icon="tag"
              onClick={() => setJob('tag')}
              small
              title={noteIds.length === 0 ? 'Groups do not carry tags' : 'Tag every selected note'}
            >
              Tag
            </Btn>
            <Btn icon="trash" onClick={() => setJob('delete')} small tone="danger">
              Delete
            </Btn>
            <button
              className="selbar-clear"
              onClick={() => selection.clear()}
              title="Clear the selection"
              type="button"
            >
              <Icon name="x" />
              <span className="sr">Clear the selection</span>
            </button>
          </div>
        </div>
      </section>
      {job === 'move' && <MoveSheet onClose={() => setJob(null)} />}
      {job === 'tag' && <TagSheet onClose={() => setJob(null)} />}
      {job === 'delete' && <DeleteSheet onClose={() => setJob(null)} />}
    </>
  );
}

/**
 * Where a selection may be moved to.
 *
 * A group cannot be moved inside itself or inside anything under it — that would cut the branch
 * off the tree entirely, and the group and everything in it would simply stop being reachable.
 * The check walks the target's ancestry rather than the selection's descendants, which is the
 * same test written from the cheaper end.
 */
export function moveTargets(
  all: readonly { group: Group; path: string }[],
  chainOf: (id: string) => readonly Group[],
  selectedGroupIds: readonly string[],
): readonly { group: Group; path: string; blocked: string | null }[] {
  const selected = new Set(selectedGroupIds);
  return all.map(({ group, path }) => {
    if (selected.has(group.id as string)) {
      return { group, path, blocked: 'Selected' };
    }
    const ancestors = chainOf(group.id as string);
    const inside = ancestors.some((entry) => selected.has(entry.id as string));
    return { group, path, blocked: inside ? 'Inside the selection' : null };
  });
}

function MoveSheet({ onClose }: { readonly onClose: () => void }): React.JSX.Element {
  const tree = useGroups();
  const actions = useNoteActions();
  const selection = useSelection();
  const toast = useToast();
  const [busy, setBusy] = useState(false);

  const groupIds = selection.groupIds();
  const noteIds = selection.noteIds();

  const targets = useMemo(() => {
    const all = [...tree.byId.values()]
      .map((group) => ({
        group,
        path: tree
          .chain(group.id as string)
          .map((entry) => entry.name)
          .join(' / '),
      }))
      .sort((left, right) => left.path.localeCompare(right.path));
    return moveTargets(all, (id) => tree.chain(id).slice(0, -1), groupIds as readonly string[]);
  }, [tree, groupIds]);

  async function move(target: CollectionId | null): Promise<void> {
    setBusy(true);
    try {
      let moved = 0;
      let failed = 0;
      for (const id of groupIds) {
        try {
          await tree.update(id, { parentId: target });
          moved += 1;
        } catch {
          failed += 1;
        }
      }
      if (noteIds.length > 0 && target !== null) {
        const result = await actions.moveMany(noteIds, target);
        moved += result.done;
        failed += result.failed;
      }
      // A note has to live in a group, so "the top level" is a real destination for a group and
      // not one for a note. Saying so beats silently moving half of what was ticked.
      const orphaned = target === null ? noteIds.length : 0;
      await tree.reload();
      selection.clear();
      toast.show(
        failed === 0 && orphaned === 0
          ? `Moved ${moved}.`
          : `Moved ${moved}.${failed > 0 ? ` ${failed} would not.` : ''}${
              orphaned > 0 ? ` ${plural(orphaned, 'note')} stayed put — a note needs a group.` : ''
            }`,
        failed === 0 && orphaned === 0 ? { icon: 'move' } : { tone: 'clay', icon: 'warn' },
      );
      onClose();
    } finally {
      setBusy(false);
    }
  }

  return (
    <Sheet
      onClose={onClose}
      sub="Everything selected lands in the same place. Settings, sharing and quick tags come from wherever it lands."
      title={`Move ${plural(groupIds.length + noteIds.length, 'thing')}`}
    >
      <div className="setlist">
        {groupIds.length > 0 && (
          <button className="setrow" disabled={busy} onClick={() => void move(null)} type="button">
            <span className="setrow-main">
              <span className="setrow-label">The top level</span>
              <span className="setrow-help">
                {noteIds.length > 0
                  ? 'Groups only — a note has to live in a group.'
                  : 'Out of any group.'}
              </span>
            </span>
            <span className="setrow-value">
              <Icon className="chev" name="chev" />
            </span>
          </button>
        )}
        {targets.map(({ group, path, blocked }) => (
          <button
            className="setrow"
            disabled={busy || blocked !== null}
            key={group.id}
            onClick={() => void move(group.id)}
            type="button"
          >
            <span className="setrow-main">
              <span className="setrow-label">{group.name}</span>
              <span className="setrow-help">{path}</span>
            </span>
            <span className="setrow-value">
              {blocked !== null ? <span className="inh">{blocked}</span> : null}
              <Icon className="chev" name="chev" />
            </span>
          </button>
        ))}
      </div>
    </Sheet>
  );
}

function TagSheet({ onClose }: { readonly onClose: () => void }): React.JSX.Element {
  const actions = useNoteActions();
  const selection = useSelection();
  const toast = useToast();
  const [entry, setEntry] = useState('');
  const [busy, setBusy] = useState(false);

  const notes = selection.notes();
  const existing = tagTally(notes);

  async function add(tags: readonly TagName[]): Promise<void> {
    if (tags.length === 0) return;
    setBusy(true);
    try {
      const result = await actions.tagMany(notes, tags);
      toast.show(
        result.failed === 0
          ? `Tagged ${result.done}.`
          : `Tagged ${result.done}, and ${result.failed} would not.`,
        result.failed === 0 ? { icon: 'tag' } : { tone: 'clay', icon: 'warn' },
      );
      setEntry('');
      onClose();
    } finally {
      setBusy(false);
    }
  }

  async function remove(tag: TagName): Promise<void> {
    setBusy(true);
    try {
      const result = await actions.untagMany(notes, [tag]);
      toast.show(`Removed “${tag}” from ${result.done}.`, { icon: 'tag' });
    } finally {
      setBusy(false);
    }
  }

  // Commas and spaces both split, because both are what people type and neither is a valid tag
  // character worth defending.
  const parsed = entry
    .split(/[,\s]+/u)
    .map((part) => part.trim().toLowerCase())
    .filter((part) => part !== '') as TagName[];

  return (
    <Sheet
      footer={
        <Btn disabled={busy || parsed.length === 0} onClick={() => void add(parsed)} tone="primary">
          {parsed.length <= 1 ? 'Add the tag' : `Add ${parsed.length} tags`}
        </Btn>
      }
      onClose={onClose}
      sub={`To ${plural(notes.length, 'note')}. Tags a note already has are left alone.`}
      title="Tag the selection"
    >
      <div style={{ display: 'grid', gap: 12 }}>
        <label className="field-row">
          <span className="eyebrow">New tags</span>
          <input
            className="field"
            onChange={(event) => setEntry(event.target.value)}
            placeholder="transformation, draft"
            value={entry}
          />
          <span className="hint">Separate several with a comma or a space.</span>
        </label>

        {existing.length > 0 && (
          <div>
            <span className="eyebrow">Already on these notes</span>
            <div className="setlist">
              {existing.map(({ tag, count }) => (
                <div className="setrow" key={tag}>
                  <span className="setrow-main">
                    <span className="setrow-label">{tag}</span>
                    <span className="setrow-help">
                      on {count} of {notes.length}
                    </span>
                  </span>
                  <span className="setrow-value">
                    <Btn disabled={busy} onClick={() => void remove(tag)} small tone="quiet">
                      Remove
                    </Btn>
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </Sheet>
  );
}

function DeleteSheet({ onClose }: { readonly onClose: () => void }): React.JSX.Element {
  const tree = useGroups();
  const actions = useNoteActions();
  const selection = useSelection();
  const toast = useToast();
  const [alsoNotes, setAlsoNotes] = useState(false);
  const [busy, setBusy] = useState(false);

  const noteIds = selection.noteIds();
  const groupIds = selection.groupIds();

  // What is inside the selected groups, so the number is on screen before the button is pressed
  // rather than discovered afterwards.
  const inside = groupIds.reduce(
    (running, id) => {
      const counted = tree.tally(id as string);
      return { notes: running.notes + counted.notes, groups: running.groups + counted.groups };
    },
    { notes: 0, groups: 0 },
  );

  async function run(): Promise<void> {
    setBusy(true);
    try {
      const notes =
        noteIds.length === 0 ? { done: 0, failed: 0 } : await actions.trashMany(noteIds);
      const groups =
        groupIds.length === 0
          ? { removed: 0, failed: 0 }
          : await tree.removeMany(groupIds, { deleteNotes: alsoNotes });
      selection.clear();
      const failed = notes.failed + groups.failed;
      toast.show(
        failed === 0
          ? `Moved ${notes.done + groups.removed} to the trash.`
          : `Deleted ${notes.done + groups.removed}, and ${failed} would not.`,
        failed === 0 ? { icon: 'trash' } : { tone: 'clay', icon: 'warn' },
      );
      onClose();
    } finally {
      setBusy(false);
    }
  }

  return (
    <Sheet
      footer={
        <Btn disabled={busy} onClick={() => void run()} tone="danger">
          {busy ? 'Deleting…' : `Delete ${noteIds.length + groupIds.length}`}
        </Btn>
      }
      onClose={onClose}
      sub="Everything here goes to the trash, where you can get it back."
      title="Delete the selection"
    >
      <div style={{ display: 'grid', gap: 12 }}>
        <Callout icon="trash" tone="quiet">
          {noteIds.length > 0 && <>{plural(noteIds.length, 'note')}</>}
          {noteIds.length > 0 && groupIds.length > 0 && <> and </>}
          {groupIds.length > 0 && <>{plural(groupIds.length, 'group')}</>}. Nothing is erased — the
          trash is where it goes.
        </Callout>

        {groupIds.length > 0 && inside.notes > 0 && (
          <>
            {/*
              The default keeps the notes. A group is a shelf, and throwing out a shelf is not a
              decision to throw out what was on it — the server moves them up a level instead.
              Making the destructive option the one that has to be reached for is the whole point.
            */}
            <div className="setrow">
              <span className="setrow-main">
                <span className="setrow-label">Delete the notes inside too</span>
                <span className="setrow-help">
                  {alsoNotes
                    ? `${plural(inside.notes, 'note')} will go to the trash as well.`
                    : `${plural(inside.notes, 'note')} inside will move up a level and stay.`}
                </span>
              </span>
              <span className="setrow-value">
                <Switch
                  checked={alsoNotes}
                  label="Delete the notes inside too"
                  onChange={setAlsoNotes}
                />
              </span>
            </div>
            {inside.groups > 0 && (
              <p className="setrow-help">
                {plural(inside.groups, 'subgroup')} inside{' '}
                {alsoNotes ? 'will go too.' : 'will move up a level.'}
              </p>
            )}
          </>
        )}
      </div>
    </Sheet>
  );
}
