import {
  ACCENT_NAMES,
  type AccentName,
  DENSITY_NAMES,
  type DensityName,
  HOVER_NAMES,
  type HoverEmphasis,
} from '@rosie-notes/tokens';
import { useEffect, useRef, useState } from 'react';
import type { ThemePreference } from '../hooks/use-appearance';
import { useNavigate } from '../routing/use-route';
import { useSession } from '../session/session-context';
import { BackupSection } from './backup';
import { PageHeader } from './chrome';
import { ConfigProjectsSection } from './config-projects';
import { ConfigSection } from './config-view';
import { Icon } from './icons';
import { Btn, Callout, Segmented, SetGroup, SetRow, Sheet } from './primitives';
import { useShell } from './shell-context';
import { useToast } from './toasts';

/**
 * App settings: theme, density and accent, and nothing else pretending to be a preference.
 *
 * Three axes is on purpose. Every combination of these is one somebody designed and measured —
 * each accent clears 4.5:1 as text on all three surfaces in both themes, and each density step
 * moves ten values together rather than scaling a font size. A settings screen with thirty
 * toggles is a screen where most combinations have never been looked at.
 */

const ACCENT_LABEL: Record<AccentName, string> = {
  rose: 'Rose',
  orchid: 'Orchid',
  iris: 'Iris',
  cyan: 'Cyan',
  teal: 'Teal',
  slate: 'Slate',
};

const DENSITY_LABEL: Record<DensityName, string> = {
  roomy: 'Roomy',
  cosy: 'Cosy',
  compact: 'Compact',
};

const HOVER_LABEL: Record<HoverEmphasis, string> = {
  subtle: 'Subtle',
  clear: 'Clear',
  high: 'High',
};

export function SettingsView(): React.JSX.Element {
  const { appearance } = useShell();
  const session = useSession();
  const navigate = useNavigate();
  const toast = useToast();
  const [signingOut, setSigningOut] = useState(false);

  return (
    <>
      <PageHeader
        sub={
          <span>
            Theme, density and accent are all there is. That is on purpose — every combination is
            one somebody designed.
          </span>
        }
        title="Settings"
      />

      <SetGroup title="Appearance">
        <div className="setrow setrow-stack">
          <span className="setrow-label">Theme</span>
          <span className="setrow-help spaced">
            Dark is the default. Light is the same app, not a washed-out copy.
          </span>
          <Segmented<ThemePreference>
            label="Theme"
            onChange={appearance.setThemePreference}
            options={[
              { value: 'dark', label: 'Dark' },
              { value: 'light', label: 'Light' },
              { value: 'system', label: 'Follow system' },
            ]}
            value={appearance.themePreference}
            wide
          />
        </div>

        <div className="setrow setrow-stack">
          <span className="setrow-label">Density</span>
          <span className="setrow-help spaced">
            How much breathing room every screen gets. Compact puts each note on one line. Touch
            targets never shrink below 40px, whatever this says.
          </span>
          <Segmented<DensityName>
            label="Density"
            onChange={appearance.setDensity}
            options={DENSITY_NAMES.map((value) => ({ value, label: DENSITY_LABEL[value] }))}
            value={appearance.density}
            wide
          />
        </div>

        {/* The fourth axis, and the only one somebody asked for out loud: "on a poor screen
            hovering over buttons that just lightly glow are near impossible to see". Clear is the
            default and is the one that meets the 3:1 a state indicator owes; Subtle is an
            explicit opt-out of that, and it is named honestly in the help text rather than being
            presented as an equal choice. */}
        <div className="setrow setrow-stack">
          <span className="setrow-label">Pointer feedback</span>
          <span className="setrow-help spaced">
            How strongly the thing under your pointer says so. Clear is measured to stay visible on
            a poor screen; High goes further. Subtle is the quiet old look, and is the one setting
            here that does not meet the contrast bar the rest of the app is held to.
          </span>
          <Segmented<HoverEmphasis>
            label="Pointer feedback"
            onChange={appearance.setHover}
            options={HOVER_NAMES.map((value) => ({ value, label: HOVER_LABEL[value] }))}
            value={appearance.hover}
            wide
          />
        </div>

        <div className="setrow setrow-stack">
          <span className="setrow-label">Accent</span>
          <span className="setrow-help spaced">
            The colour of selection, focus and the primary action. Six that are measured for both
            themes. Any group can overrule it for itself.
          </span>
          <div className="swatches">
            {ACCENT_NAMES.map((name) => (
              <button
                aria-pressed={appearance.accent === name}
                className="sw"
                data-gc={name}
                key={name}
                onClick={() => appearance.setAccent(name)}
                type="button"
              >
                <i />
                {ACCENT_LABEL[name]}
              </button>
            ))}
          </div>
        </div>
      </SetGroup>

      <ConfigSection />
      <ConfigProjectsSection />
      <BackupSection />

      <SetGroup title="Making things">
        <SetRow
          help="What a new group begins as. Change one and the next group you make from it follows — the ones you have already made are untouched."
          label="Starting points"
          onClick={() => navigate({ name: 'templates' })}
          value={<span />}
        />
      </SetGroup>

      {/* Also a Places entry on wide screens (`app-shell.tsx`) — but Places is hidden below
          901px, and the tab bar's five slots are already spoken for, so this row is the only way
          a phone-width session ever reaches the screen at all. */}
      <SetGroup title="Sharing">
        <SetRow
          help="Notes other people on this server have shared with your account, by username."
          label="Shared with me"
          onClick={() => navigate({ name: 'sharedWithMe' })}
          value={<span />}
        />
      </SetGroup>

      <SetGroup title="Account">
        <SetRow
          label="Signed in as"
          value={<span>{session.user?.displayName ?? session.user?.username ?? 'you'}</span>}
        />
        <SetRow label="Server" value={<span className="chip chip-mono">{session.baseUrl}</span>} />
        <SetRow
          danger
          help="Keeps what is cached on this device. Sign out and forget removes it."
          label="Sign out"
          onClick={() => setSigningOut(true)}
          value={<span />}
        />
      </SetGroup>

      {/* The product makes no claim about encryption, at rest or in transit. What it can honestly
          say is *who can see a thing*, and that includes whoever runs the server. */}
      <Callout className="callout-spaced" icon="cloud" tone="quiet">
        <b>Your server, your notes.</b> Everything you write lives on the server you point this at,
        and whoever runs that server can read what is on it. Locking a note hides it from the other
        people in a group — not from the machine it sits on.
      </Callout>

      {signingOut && (
        <Sheet
          onClose={() => setSigningOut(false)}
          sub="Anything still waiting to reach the server will be sent first if it can be."
          title="Sign out?"
        >
          <div className="form__actions">
            <Btn onClick={() => setSigningOut(false)} tone="ghost">
              Stay signed in
            </Btn>
            <Btn
              onClick={() => {
                void session.signOut();
                toast.show('Signed out.');
              }}
              tone="default"
            >
              Sign out
            </Btn>
            <Btn
              onClick={() => {
                void session.signOut({ forget: true });
                toast.show('Signed out and cleared this device.');
              }}
              tone="danger"
            >
              Sign out and forget this device
            </Btn>
          </div>
        </Sheet>
      )}
    </>
  );
}

/** The topbar menu: the same four axes, one tap away from anywhere. */
export function AppearanceMenu({ onClose }: { readonly onClose: () => void }): React.JSX.Element {
  const { appearance } = useShell();
  const menuRef = useRef<HTMLDivElement | null>(null);

  /*
   * Escape closes it, and so does clicking anywhere else.
   *
   * It had neither, which made it the one thing on screen that could only be dismissed by hitting
   * the same button again — the interaction everybody tries second, after clicking away.
   *
   * `pointerdown` rather than `click`, so the menu is gone before the thing underneath reacts.
   * `.menu-wrap` is the exclusion rather than `.menu` itself, because the wrap also contains the
   * toggle button: a click on the toggle has to reach the toggle's own handler and close the menu
   * from there, or it would be closed here and reopened by the same click.
   */
  useEffect(() => {
    function onPointerDown(event: PointerEvent): void {
      const target = event.target;
      if (target instanceof Node && menuRef.current?.closest('.menu-wrap')?.contains(target)) {
        return;
      }
      onClose();
    }
    function onKeyDown(event: KeyboardEvent): void {
      if (event.key !== 'Escape') return;
      event.stopPropagation();
      onClose();
    }
    globalThis.addEventListener('pointerdown', onPointerDown, true);
    globalThis.addEventListener('keydown', onKeyDown);
    return () => {
      globalThis.removeEventListener('pointerdown', onPointerDown, true);
      globalThis.removeEventListener('keydown', onKeyDown);
    };
  }, [onClose]);

  return (
    <div className="menu" ref={menuRef} role="menu">
      <div className="menu-label">Theme</div>
      {(['dark', 'light', 'system'] as const).map((value) => (
        <button
          className="menu-item"
          key={value}
          onClick={() => {
            appearance.setThemePreference(value);
            onClose();
          }}
          role="menuitem"
          type="button"
        >
          <span className="tick">
            {appearance.themePreference === value && <Icon name="check" />}
          </span>
          {value === 'system' ? 'Follow system' : value === 'dark' ? 'Dark' : 'Light'}
        </button>
      ))}

      <div className="menu-sep" />
      <div className="menu-label">Density</div>
      {DENSITY_NAMES.map((value) => (
        <button
          className="menu-item"
          key={value}
          onClick={() => {
            appearance.setDensity(value);
            onClose();
          }}
          role="menuitem"
          type="button"
        >
          <span className="tick">{appearance.density === value && <Icon name="check" />}</span>
          {DENSITY_LABEL[value]}
        </button>
      ))}

      <div className="menu-sep" />
      <div className="menu-label">Pointer feedback</div>
      {HOVER_NAMES.map((value) => (
        <button
          className="menu-item"
          key={value}
          onClick={() => {
            appearance.setHover(value);
            onClose();
          }}
          role="menuitem"
          type="button"
        >
          <span className="tick">{appearance.hover === value && <Icon name="check" />}</span>
          {HOVER_LABEL[value]}
        </button>
      ))}

      <div className="menu-sep" />
      <div className="menu-label">Accent</div>
      <div className="menu-swatches swatches">
        {ACCENT_NAMES.map((name) => (
          <button
            aria-pressed={appearance.accent === name}
            className="sw"
            data-gc={name}
            key={name}
            onClick={() => appearance.setAccent(name)}
            title={ACCENT_LABEL[name]}
            type="button"
          >
            <i />
            <span className="sr">{ACCENT_LABEL[name]}</span>
          </button>
        ))}
      </div>
    </div>
  );
}
