import type { CollectionId } from '@rosie-notes/schema';
import { useRef, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useNoteActions } from '../hooks/use-note-actions';
import { type ImportFile, type ImportPlan, planImport, planSummary } from './import-plan';
import { plural } from './labels';
import { Btn, Callout, Sheet, Switch } from './primitives';
import { useToast } from './toasts';

/**
 * Bringing writing that already exists into the app.
 *
 * Two of Rose's asks, one machine (see `import-plan.ts`):
 *
 * - **T-35** — rosie-notes as its own first code project. Its docs, plans and prompts are markdown
 *   files; drop the folder in and they are notes.
 * - **T-39** — Rose's existing writing, the ADHD notes among it. The open question was *what
 *   format is it in*, and this answers the half that can be answered without asking: **text
 *   files, in folders**, which is what writing usually is.
 *
 * Nothing is created until the plan is on screen and somebody presses the button. The plan says
 * how many notes, how many subgroups, how many words — and **what it is leaving out and why**,
 * because the failure mode that matters here is finding out months later that half of it never
 * arrived.
 *
 * A folder is read entirely in the browser. Nothing is uploaded anywhere except the notes that
 * are created, which go the same way every other note does.
 */

export interface ImportFilesProps {
  /** Where everything lands. `null` puts it at the top level. */
  readonly groupId: string | null;
  readonly onClose: () => void;
  readonly onDone: () => void;
}

/** Read a `FileList` into memory, keeping the folder trail the browser reported. */
async function readAll(files: FileList): Promise<readonly ImportFile[]> {
  const out: ImportFile[] = [];
  for (const file of Array.from(files)) {
    // `webkitRelativePath` is what a directory picker fills in; a plain multi-file pick leaves it
    // empty and the name is the whole path. Both are handled the same way downstream.
    const path = (file as File & { webkitRelativePath?: string }).webkitRelativePath || file.name;
    out.push({ path, text: await file.text() });
  }
  return out;
}

export function ImportFiles({ groupId, onClose, onDone }: ImportFilesProps): React.JSX.Element {
  const tree = useGroups();
  const actions = useNoteActions();
  const toast = useToast();
  const picker = useRef<HTMLInputElement>(null);
  const folderPicker = useRef<HTMLInputElement>(null);
  const [plan, setPlan] = useState<ImportPlan | null>(null);
  const [files, setFiles] = useState<readonly ImportFile[]>([]);
  const [flatten, setFlatten] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(0);
  const [failure, setFailure] = useState<string | null>(null);

  function take(list: FileList | null, asFlat = flatten): void {
    if (list === null || list.length === 0) return;
    setFailure(null);
    void readAll(list).then((read) => {
      setFiles(read);
      setPlan(planImport(read, { flatten: asFlat }));
    });
  }

  function reflow(next: boolean): void {
    setFlatten(next);
    if (files.length > 0) setPlan(planImport(files, { flatten: next }));
  }

  async function run(): Promise<void> {
    if (plan === null) return;
    setBusy(true);
    setFailure(null);
    setProgress(0);
    try {
      // Folders first, parents before children — which `planImport` guarantees the order of.
      const madeFolders = new Map<string, string | null>([['', groupId]]);
      for (const trail of plan.folders) {
        const parentKey = trail.slice(0, -1).join('/');
        const parentId = madeFolders.get(parentKey) ?? groupId;
        const name = trail.at(-1) ?? '';
        const existing = tree
          .children(parentId)
          .find((group) => group.name.trim().toLowerCase() === name.trim().toLowerCase());
        const id =
          existing?.id ??
          (
            await tree.create({
              name,
              ...(parentId === null ? {} : { parentId: parentId as CollectionId }),
            })
          ).id;
        madeFolders.set(trail.join('/'), id as string);
      }

      let made = 0;
      let failed = 0;
      for (const note of plan.notes) {
        const parentId = madeFolders.get(note.folders.join('/')) ?? groupId;
        try {
          await actions.create({
            title: note.title,
            ...(parentId === null ? {} : { collectionIds: [parentId as CollectionId] }),
            body: { format: 'markdown', text: note.markdown },
          });
          made += 1;
        } catch {
          // One unreadable file must not lose the other forty. Counted and reported.
          failed += 1;
        }
        setProgress(made + failed);
      }

      await tree.reload();
      toast.show(
        failed === 0
          ? `Brought in ${plural(made, 'note')}.`
          : `Brought in ${made}, and ${failed} would not.`,
        failed === 0 ? { icon: 'doc' } : { tone: 'clay', icon: 'warn' },
      );
      onDone();
      onClose();
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'Nothing else was created.');
    } finally {
      setBusy(false);
    }
  }

  const where = groupId === null ? 'the top level' : (tree.byId.get(groupId)?.name ?? 'this group');

  return (
    <Sheet
      footer={
        <Btn
          disabled={busy || plan === null || plan.notes.length === 0}
          onClick={() => void run()}
          tone="primary"
        >
          {busy
            ? `Creating… ${progress} of ${plan?.notes.length ?? 0}`
            : plan === null
              ? 'Pick something first'
              : `Bring in ${plural(plan.notes.length, 'note')}`}
        </Btn>
      }
      onClose={onClose}
      sub={`Text files become notes in ${where}. Folders become subgroups.`}
      title="Bring in files"
    >
      <div style={{ display: 'grid', gap: 12 }}>
        <Callout icon="eye" tone="quiet">
          Everything is read <b>in this browser</b>. Nothing is uploaded except the notes that get
          created, which go the same way any note you type does.
        </Callout>

        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <Btn icon="doc" onClick={() => picker.current?.click()}>
            Pick files…
          </Btn>
          <Btn icon="box" onClick={() => folderPicker.current?.click()}>
            Pick a folder…
          </Btn>
        </div>
        <input
          accept=".md,.markdown,.txt,.text,.rst,.org,.adoc,.log,.json,.yml,.yaml,.toml,.csv"
          className="sr"
          multiple
          onChange={(event) => take(event.target.files)}
          ref={picker}
          type="file"
        />
        {/* `webkitdirectory` is non-standard and universally supported, which is the whole story:
            it is the only way a browser will hand over a folder tree. */}
        <input
          className="sr"
          multiple
          onChange={(event) => take(event.target.files)}
          ref={folderPicker}
          type="file"
          {...({ webkitdirectory: '' } as Record<string, string>)}
        />

        {plan !== null && (
          <>
            <div className="setrow">
              <span className="setrow-main">
                <span className="setrow-label">Keep the folders</span>
                <span className="setrow-help">
                  {flatten
                    ? `Everything goes straight into ${where}.`
                    : `${plural(plan.folders.length, 'subgroup')} will be made to match the folders.`}
                </span>
              </span>
              <span className="setrow-value">
                <Switch
                  checked={!flatten}
                  label="Keep the folders"
                  onChange={(on) => reflow(!on)}
                />
              </span>
            </div>

            <Callout icon="check" tone="quiet">
              <b>{planSummary(plan)}</b> will be created in {where}.
            </Callout>

            <div style={{ display: 'grid', gap: 2, maxHeight: '32vh', overflowY: 'auto' }}>
              {plan.notes.slice(0, 200).map((note) => (
                <div className="setrow" key={note.sourcePath}>
                  <span className="setrow-main">
                    <span className="setrow-label">{note.title}</span>
                    <span className="setrow-help">
                      {note.sourcePath} · {note.words} words
                    </span>
                  </span>
                </div>
              ))}
              {plan.notes.length > 200 && (
                <p className="setrow-help">
                  …and {plan.notes.length - 200} more. All of them will be created.
                </p>
              )}
            </div>

            {/*
              Always shown, never collapsed away when it is short. The failure this prevents is
              somebody finding out months later that half their writing never arrived.
            */}
            {plan.skipped.length > 0 && (
              <details className="skiplist">
                <summary>{plural(plan.skipped.length, 'file')} will not come in — see why</summary>
                <div style={{ display: 'grid', gap: 2, maxHeight: '24vh', overflowY: 'auto' }}>
                  {plan.skipped.map((entry) => (
                    <div className="setrow" key={entry.path}>
                      <span className="setrow-main">
                        <span className="setrow-label">{entry.path}</span>
                        <span className="setrow-help">{entry.why}</span>
                      </span>
                    </div>
                  ))}
                </div>
              </details>
            )}
          </>
        )}

        {failure !== null && (
          <Callout icon="warn" tone="clay">
            {failure}
          </Callout>
        )}
      </div>
    </Sheet>
  );
}

/** Kept out of the component so a caller can pre-read files in a test. */
export type { ImportFile, ImportPlan };
export { planImport, planSummary };
