import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * A sheet, as a history entry.
 *
 * `DESIGN-SYSTEM.md`: *"Every sheet, menu and picker is a history entry too: Back closes what is
 * on top of the screen before it moves the screen underneath."* That is not a flourish — it is
 * the behaviour both the phone's Back gesture and a mouse's thumb button already assume, and an
 * app that ignores it throws somebody two screens back when they meant to dismiss a dialog.
 *
 * The mechanism is a `pushState` that changes **nothing about the address**. The URL stays
 * exactly as it was, so the sheet is not linkable and a reload lands on the screen underneath —
 * which is right: a sheet is a transient thing you opened, not a place you went.
 *
 * Closing always goes through `history.back()` rather than through state directly. That way the
 * scrim, the Escape key, the close button and the hardware Back button all take the same path,
 * and the history stack cannot drift out of step with what is on screen.
 */

interface LayerState {
  readonly rnLayer?: number;
}

function currentDepth(): number {
  const state = globalThis.history?.state as LayerState | null;
  return typeof state?.rnLayer === 'number' ? state.rnLayer : 0;
}

export interface Layer<T> {
  /** What is open, or `null`. */
  readonly value: T | null;
  open(value: T): void;
  /** Dismiss. Goes back through history, which is what actually closes it. */
  close(): void;
  /**
   * Dismiss *because we are navigating somewhere from inside the sheet.*
   *
   * `close()` cannot be used for this. It calls `history.back()`, which is **asynchronous** — the
   * `popstate` arrives on a later task. A caller that closes and then navigates therefore pushes
   * its destination first and gets sent straight back by the pop that was already queued, landing
   * exactly where it started with the sheet merely dismissed. That was a real bug: every button in
   * the Add sheet appeared to do nothing.
   *
   * This clears the sheet without touching history, so the caller can navigate with
   * `{ replace: true }` and *replace* the sheet's entry with the destination. Back then returns to
   * the screen the sheet was opened from, which is what someone expects anyway.
   */
  closeForNavigation(): void;
}

export function useLayer<T>(): Layer<T> {
  const [value, setValue] = useState<T | null>(null);
  // Whether *this* hook owns the entry currently on top, so a stray popstate from an unrelated
  // navigation cannot close a sheet this hook never opened.
  const owned = useRef(false);

  useEffect(() => {
    function onPopState(): void {
      if (!owned.current) return;
      // The entry we pushed has been popped — either by Back, or by our own close().
      if (currentDepth() === 0) {
        owned.current = false;
        setValue(null);
      }
    }
    globalThis.addEventListener('popstate', onPopState);
    return () => globalThis.removeEventListener('popstate', onPopState);
  }, []);

  const open = useCallback((next: T) => {
    setValue((existing) => {
      // Re-opening while already open replaces the contents rather than stacking a second entry;
      // otherwise Back would have to be pressed twice to dismiss one visible sheet.
      if (existing === null) {
        try {
          globalThis.history.pushState({ rnLayer: 1 }, '', globalThis.location.href);
          owned.current = true;
        } catch {
          // A sandboxed frame with no history access: the sheet still opens, Back simply will
          // not close it. Degrading here is better than refusing to show the sheet at all.
          owned.current = false;
        }
      }
      return next;
    });
  }, []);

  const close = useCallback(() => {
    if (owned.current) {
      // `popstate` does the closing, so every route in — scrim, Escape, button, thumb — is one path.
      globalThis.history.back();
      return;
    }
    setValue(null);
  }, []);

  // Hides the sheet without popping. The caller is expected to navigate with `replace: true`,
  // which overwrites the entry this hook pushed — so the stack stays exactly as deep as it was
  // and nothing is left dangling. See the doc comment on `closeForNavigation` above.
  const closeForNavigation = useCallback(() => {
    owned.current = false;
    setValue(null);
  }, []);

  return { value, open, close, closeForNavigation };
}
