import { appendParagraph, bodyParagraphs, isNoteEmpty, noteText } from '@rosie-notes/core';
import type { NoteId } from '@rosie-notes/schema';
import { useCallback, useEffect, useState } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * Reading and writing a note's text **without the editor**.
 *
 * The columns screen edits notes it is not showing an editor for, and so will the importers and
 * anything else that writes a body from outside a webview. The rule it has to respect is the one
 * `NotesStore` documents at length: the **Yjs document is the note**, and `body` on the server is
 * a projection of it written by whichever client last had it open. Writing only the projection
 * means the next client to open the editor overwrites it from a document that never heard about
 * the change — the edit disappears, and nothing anywhere reports an error.
 *
 * So both are written, in that order: the document first, through the sync engine that carries
 * it to every other device, and then the projection, so search and excerpts agree with it.
 */

export interface NoteBodyState {
  readonly text: string;
  readonly loading: boolean;
  /** Replace the whole body. Debouncing and change-detection are the caller's business. */
  write(next: string): Promise<void>;
}

export function useNoteBody(noteId: NoteId | null): NoteBodyState {
  const workspace = useWorkspace();
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(noteId !== null);

  useEffect(() => {
    if (noteId === null) {
      setText('');
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const doc = await workspace.engine.open(noteId);
        if (cancelled) return;
        /*
         * A note whose text only ever existed as a **body** opens empty here.
         *
         * `open` rehydrates the Yjs document from the local cache and does not go to the network.
         * That is right for a note somebody has typed — but a note that arrived from a backup
         * restore, or an import, or the API, has a `body` column on the server and no Yjs updates
         * at all, so its document is genuinely empty and reading it gives ''.
         *
         * The sync engine already knows how to fix this: its pull path seeds an empty document
         * from the server's body (`seedNoteBody`). It simply has to be asked. This showed up as
         * Rose's imported ADHD points rendering as an empty column — the note was perfect, and
         * this hook was looking in the only place the text was not.
         */
        if (isNoteEmpty(doc)) {
          await workspace.engine.pull(noteId);
          if (cancelled) return;
        }
        setText(noteText(workspace.engine.doc(noteId) ?? doc));
      } catch {
        // Offline, or a note the server has never heard of. An empty column is a truthful
        // rendering of "nothing has been written here yet" and stays editable.
        if (!cancelled) setText('');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [noteId, workspace]);

  const write = useCallback(
    async (next: string) => {
      if (noteId === null) return;
      setText(next);
      const doc = await workspace.engine.open(noteId);
      const paragraphs = bodyParagraphs(next);
      /*
       * Replace the whole body in one transaction.
       *
       * Coarse, and deliberately so. A per-line diff would merge two people typing in the same
       * column, and a column has exactly one author by construction (`DECISIONS.md` D-22) — so
       * the merge would never fire, while the code to do it would be there forever. One
       * transaction also means one update in the outbox instead of one per line.
       */
      doc.doc.transact(() => {
        if (doc.body.length > 0) doc.body.delete(0, doc.body.length);
        for (const paragraph of paragraphs) appendParagraph(doc, paragraph);
      });
      await workspace.writes.submit({
        kind: 'update',
        noteId,
        patch: { body: { format: 'markdown', text: next } },
      });
    },
    [noteId, workspace],
  );

  return { text, loading, write };
}
