import { isClientError } from '@rosie-notes/client';
import type { SearchHit } from '@rosie-notes/schema';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useNavigate } from '../routing/use-route';
import { useWorkspace } from '../session/session-context';
import { PageHeader } from './chrome';
import { parseHighlight } from './highlight';
import { Icon } from './icons';
import { ago, plural } from './labels';
import { Sep } from './primitives';
import { List, Row, SkeletonRows } from './rail';
import { orderedItems, useRowSelection } from './selection-context';
import { EmptyState, ErrorState } from './states';

/**
 * Search: every note, as you type.
 *
 * The query lives in the URL (`#/search?q=…`), so a search is linkable and survives a reload like
 * every other screen. The input is debounced into the route rather than into a separate piece of
 * state, which is what keeps the two from disagreeing after a back button.
 *
 * The server highlights matches; those come back as offsets and are rendered as `<mark>` around
 * **plain text nodes**, never as markup — a note whose body contains a script tag must not become
 * one because it was searched for.
 */

const DEBOUNCE_MS = 220;

export interface SearchViewProps {
  readonly query: string;
}

export function SearchView({ query }: SearchViewProps): React.JSX.Element {
  const workspace = useWorkspace();
  const navigate = useNavigate();
  const tree = useGroups();
  const [draft, setDraft] = useState(query);
  const [hits, setHits] = useState<readonly SearchHit[]>([]);
  // Draw order, for shift-click ranges over the results.
  const hitIds = useMemo(() => hits.map((hit) => hit.note.id as string), [hits]);
  const [loading, setLoading] = useState(false);
  const [failure, setFailure] = useState<'offline' | 'error' | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);

  // The route is the source of truth. Typing writes into it on a debounce; arriving at the screen
  // — including by Back — writes back into the field.
  useEffect(() => {
    setDraft(query);
  }, [query]);

  useEffect(() => {
    if (draft === query) return;
    const timer = globalThis.setTimeout(() => {
      navigate({ name: 'search', query: draft }, { replace: true });
    }, DEBOUNCE_MS);
    return () => globalThis.clearTimeout(timer);
  }, [draft, query, navigate]);

  useEffect(() => {
    const trimmed = query.trim();
    if (trimmed === '') {
      setHits([]);
      setFailure(null);
      return;
    }
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const response = await workspace.store.search({ query: trimmed, limit: 40 });
        if (cancelled) return;
        setHits(response.items);
        setFailure(null);
      } catch (error) {
        if (cancelled) return;
        setHits([]);
        // Full-text search is the server's job — there is no index on this device — so being
        // offline is a specific, explainable answer rather than "no results".
        setFailure(isClientError(error) && error.kind === 'network' ? 'offline' : 'error');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [query, workspace]);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const trimmed = query.trim();

  return (
    <>
      <PageHeader
        sub={
          trimmed === '' ? (
            <span>Every note, as you type.</span>
          ) : (
            <span className="echo">for &ldquo;{trimmed}&rdquo;</span>
          )
        }
        title={trimmed === '' ? 'Search' : 'Results'}
      />

      {/* The topbar carries the field at ≥901px; this is its stand-in below that, where the
          topbar has given the room to the drill-down chrome instead. */}
      <div className="only-narrow" style={{ marginBottom: 20 }}>
        <input
          aria-label="Search notes"
          className="field"
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Search every note"
          ref={inputRef}
          type="search"
          value={draft}
        />
      </div>

      {trimmed === '' ? (
        <EmptyState
          body="Type a word and every note that says it will appear. Searching happens on the server, so it needs a connection."
          title="Nothing searched yet"
        />
      ) : failure === 'offline' ? (
        <ErrorState
          body="Searching happens on the server — there is no index on this device. What you have already opened is still readable from your groups."
          title="Search needs the server"
        />
      ) : failure === 'error' ? (
        <ErrorState body="The server answered, but not with results." title="That search failed" />
      ) : loading && hits.length === 0 ? (
        <SkeletonRows count={4} />
      ) : hits.length === 0 ? (
        <EmptyState body="Try a shorter word, or a tag." title="No note says that" />
      ) : (
        <>
          <p className="undertext" style={{ marginBottom: 6 }}>
            {plural(hits.length, 'match', 'matches')}
          </p>
          <List label="Search results">
            {hits.map((hit) => (
              <SearchRow
                hit={hit}
                key={hit.note.id}
                onOpen={(id) => navigate({ name: 'note', noteId: id })}
                siblings={hitIds}
                path={tree
                  .chain((hit.note.collectionIds[0] as string | undefined) ?? null)
                  .map((group) => group.name)
                  .join(' / ')}
              />
            ))}
          </List>
        </>
      )}
    </>
  );
}

function SearchRow({
  hit,
  path,
  onOpen,
  siblings = [],
}: {
  readonly hit: SearchHit;
  readonly path: string;
  readonly onOpen: (noteId: string) => void;
  /** The results as drawn, so a shift-click can take a run of them. */
  readonly siblings?: readonly string[];
}): React.JSX.Element {
  const ordered = useMemo(() => orderedItems('note', siblings), [siblings]);
  // Results are the one place a bulk action is most wanted: search for a tag, take the lot.
  const select = useRowSelection('note', hit.note.id as string, ordered, hit.note);
  const title = hit.note.title === '' ? 'Untitled' : hit.note.title;
  const snippet = hit.highlights[0]?.snippet;

  return (
    <Row
      icon={<Icon name="page" />}
      kind="note"
      label={title}
      mark="none"
      meta={
        <>
          {path !== '' && (
            <>
              <span>{path}</span>
              <Sep />
            </>
          )}
          <span>{ago(hit.note.updatedAt)}</span>
        </>
      }
      onOpen={() => onOpen(hit.note.id as string)}
      select={select}
      title={title}
      excerpt={
        snippet === undefined ? (
          hit.note.excerpt
        ) : (
          // The snippet is somebody's note body coming back through a query. It is parsed into
          // text segments and rendered as React nodes, never as markup.
          <span className="search__snippet">
            {parseHighlight(snippet).map((segment, index) =>
              segment.marked ? (
                // biome-ignore lint/suspicious/noArrayIndexKey: segments have no identity
                <mark key={index}>{segment.text}</mark>
              ) : (
                // biome-ignore lint/suspicious/noArrayIndexKey: segments have no identity
                <span key={index}>{segment.text}</span>
              ),
            )}
          </span>
        )
      }
    />
  );
}
