import type { Backup, BackupRestoreMode, BackupRestoreReport } from '@rosie-notes/schema';
import { BackupSchema } from '@rosie-notes/schema';
import { useState } from 'react';
import { useWorkspace } from '../session/session-context';
import { ago, plural } from './labels';
import { Btn, Callout, SetGroup, SetRow, Sheet } from './primitives';
import { useToast } from './toasts';

/**
 * Full backup: everything, not just setup.
 *
 * `DECISIONS.md` D-42 is why this is not a bigger `ConfigSection` (`config-view.tsx`). A config
 * is the shape of a filing system — project types, path templates — and importing one creates
 * nothing on its own. A backup **is** the filing: every note's body, every group, tag and
 * starting point, restorable onto an account with nothing in it. Rose's own framing was the meds
 * tracker: *"it just exports everything and lets me import everything."* This is that.
 *
 * `DECISIONS.md` D-43: restore never guesses. The sheet shows what a file contains before
 * anything happens, and asks merge-or-replace with **neither pre-selected** — picking one is the
 * whole safety mechanism, so there is nothing here for a person to click through without noticing.
 */

function backupFilename(): string {
  return `rosie-notes-backup-${new Date().toISOString().slice(0, 10)}.json`;
}

/** A named download from data already in memory — no server round trip for the file itself. */
function triggerDownload(backup: Backup): void {
  const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  try {
    const link = document.createElement('a');
    link.href = url;
    link.download = backupFilename();
    document.body.appendChild(link);
    link.click();
    link.remove();
  } finally {
    // Revoked once the click has had a chance to start the save — holding onto it any longer
    // just leaks memory for a link nothing will click again.
    URL.revokeObjectURL(url);
  }
}

/** The one sentence D-03 requires wherever this file is offered: plain, not "secure". */
function UnencryptedNotice(): React.JSX.Element {
  return (
    <Callout icon="eye" tone="quiet">
      <b>This file is not encrypted.</b> It contains everything you have written, in plain text.
      Anyone who opens it can read your notes.
    </Callout>
  );
}

export function BackupSection(): React.JSX.Element {
  const workspace = useWorkspace();
  const toast = useToast();
  const [exporting, setExporting] = useState(false);
  const [restoring, setRestoring] = useState(false);

  async function downloadNow(): Promise<void> {
    setExporting(true);
    try {
      const backup = await workspace.client.backup.export();
      triggerDownload(backup);
      toast.show('Backup downloaded.');
    } catch (error) {
      toast.show(error instanceof Error ? error.message : 'Could not download a backup.', {
        tone: 'clay',
        icon: 'warn',
      });
    } finally {
      setExporting(false);
    }
  }

  return (
    <>
      <SetGroup title="Backup">
        <SetRow
          help="Every note's text, every group, tag and starting point — as one file you keep."
          label="Download a backup"
          onClick={() => void downloadNow()}
          value={<span>{exporting ? 'Preparing…' : 'Download'}</span>}
        />
        <SetRow
          help="Read a backup file back in. Nothing changes until you say what to do with it."
          label="Restore from a backup"
          onClick={() => setRestoring(true)}
          value={<span />}
        />
        <UnencryptedNotice />
      </SetGroup>

      {restoring && <RestoreSheet onClose={() => setRestoring(false)} />}
    </>
  );
}

function RestoreSheet({ onClose }: { readonly onClose: () => void }): React.JSX.Element {
  const workspace = useWorkspace();
  const toast = useToast();
  const [reading, setReading] = useState(false);
  const [parsed, setParsed] = useState<Backup | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [mode, setMode] = useState<BackupRestoreMode | null>(null);
  const [busy, setBusy] = useState(false);
  const [report, setReport] = useState<BackupRestoreReport | null>(null);

  /**
   * Read the chosen file. Two failures worth telling apart, same as the config importer: text
   * that is not JSON at all, and JSON whose shape is not a backup — usually a config file, since
   * the two live on the same settings screen and are easy to reach for by mistake.
   */
  async function readFile(file: File | undefined): Promise<void> {
    setParsed(null);
    setFailure(null);
    setMode(null);
    if (file === undefined) return;

    setReading(true);
    try {
      let raw: unknown;
      try {
        raw = JSON.parse(await file.text());
      } catch {
        setFailure('That is not valid JSON. Choose the whole file, unedited.');
        return;
      }
      const result = BackupSchema.safeParse(raw);
      if (!result.success) {
        setFailure(
          'That is not a rosie-notes backup file — check it is the one from "Download a backup", not a config.',
        );
        return;
      }
      setParsed(result.data);
    } finally {
      setReading(false);
    }
  }

  async function apply(): Promise<void> {
    if (parsed === null || mode === null) return;
    setBusy(true);
    setFailure(null);
    try {
      const result = await workspace.client.backup.restore(parsed, mode);
      setReport(result);
      toast.show(
        `Restored ${plural(result.created.notes, 'note')} and ${plural(result.created.groups, 'group')}.`,
      );
    } catch (error) {
      setFailure(
        error instanceof Error ? error.message : 'The server did not accept it. Nothing changed.',
      );
    } finally {
      setBusy(false);
    }
  }

  if (report !== null) {
    const skippedTotal = report.skipped.notes + report.skipped.groups;
    return (
      <Sheet
        footer={
          <Btn
            onClick={() => {
              onClose();
              // The whole account's content may have just changed underneath every screen that
              // is currently open — a full reload is the honest way to make everything agree
              // with what is actually in the database now, rather than patching a dozen caches.
              globalThis.location.reload();
            }}
            tone="primary"
          >
            Done
          </Btn>
        }
        onClose={onClose}
        title="Restore complete"
      >
        <div style={{ display: 'grid', gap: 10 }}>
          <p className="setrow-help">
            Created <b>{plural(report.created.notes, 'note')}</b> and{' '}
            <b>{plural(report.created.groups, 'group')}</b>.
            {skippedTotal > 0 &&
              ` Left ${plural(skippedTotal, 'thing')} that were already here untouched.`}
            {report.trashed > 0 &&
              ` Trashed ${plural(report.trashed, 'note')} that were here before restoring.`}
          </p>
          {report.problems.length > 0 && (
            <Callout icon="warn" tone="clay">
              <b>{plural(report.problems.length, 'note')} for you to know about:</b>
              <ul style={{ margin: '6px 0 0', paddingLeft: 18 }}>
                {report.problems.map((problem) => (
                  <li key={problem}>{problem}</li>
                ))}
              </ul>
            </Callout>
          )}
        </div>
      </Sheet>
    );
  }

  return (
    <Sheet
      onClose={onClose}
      sub="Choose the file, then say what happens to what is already here."
      title="Restore from a backup"
    >
      <div style={{ display: 'grid', gap: 10 }}>
        <input
          accept="application/json,.json"
          aria-label="Backup file"
          className="field"
          disabled={reading}
          onChange={(event) => void readFile(event.target.files?.[0])}
          type="file"
        />

        {failure !== null && (
          <p className="banner banner-clay" role="alert">
            {failure}
          </p>
        )}

        {parsed !== null && (
          <>
            <p className="setrow-help">
              <b>
                {plural(parsed.counts.notes, 'note')}, {plural(parsed.counts.groups, 'group')}
              </b>
              , exported {ago(parsed.exportedAt)}.
            </p>

            <UnencryptedNotice />

            <div style={{ display: 'grid', gap: 6 }}>
              <span className="setrow-label">If something is already here</span>
              <div style={{ display: 'flex', gap: 8 }}>
                <Btn
                  onClick={() => setMode('merge')}
                  tone={mode === 'merge' ? 'primary' : 'default'}
                >
                  Merge — add what is missing
                </Btn>
                <Btn
                  onClick={() => setMode('replace')}
                  tone={mode === 'replace' ? 'primary' : 'default'}
                >
                  Replace — trash what is here first
                </Btn>
              </div>
              {mode === 'replace' && (
                <span className="setrow-help">
                  Nothing already here is deleted outright — notes go to the trash, exactly as if
                  you had trashed them yourself.
                </span>
              )}
            </div>
          </>
        )}
      </div>

      <div className="form__actions" style={{ marginTop: 16 }}>
        <Btn onClick={onClose} tone="ghost">
          Cancel
        </Btn>
        <Btn
          disabled={parsed === null || mode === null || busy}
          onClick={() => void apply()}
          tone="primary"
        >
          {busy ? 'Restoring…' : 'Restore'}
        </Btn>
      </div>
    </Sheet>
  );
}
