import { isApiError } from '@rosie-notes/client';
import type { HandoffSet } from '@rosie-notes/schema';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * A project's handoff set, fetched once per project and shared by everything showing it.
 *
 * A group that names a `handoffProject` already has a task list somebody maintains on disk, so
 * its progress is a fact rather than a second thing to keep up to date. What this hook exists to
 * get right is the *absence* of one: **`handoff.not_found` is the normal case**, not a failure.
 * Most groups will never name a project, most named projects will not have been pushed yet, and a
 * list of rows that each shouted about a missing set would be unusable.
 *
 * The store is a context rather than a module-level cache for two reasons: several rows naming
 * one project make one request, and the whole thing dies with the app tree — a module cache would
 * survive a sign-out and hand the next account the previous one's answers.
 *
 * A miss is remembered; a *failure* is not. A project that has never been pushed will not appear
 * on the next render either, so re-asking is pure noise — but a request that fell over on a train
 * should be allowed to succeed once the network comes back.
 */

export interface HandoffState {
  readonly set: HandoffSet | null;
  readonly loading: boolean;
  /** The server answered, and there is no set for this project. Normal. */
  readonly missing: boolean;
}

const NOTHING: HandoffState = { set: null, loading: false, missing: false };

interface HandoffStore {
  readonly states: ReadonlyMap<string, HandoffState>;
  load(project: string): void;
}

const HandoffContext = createContext<HandoffStore | null>(null);

export function HandoffProvider({ children }: { readonly children: ReactNode }): React.JSX.Element {
  const workspace = useWorkspace();
  const [states, setStates] = useState<ReadonlyMap<string, HandoffState>>(() => new Map());
  /** Projects already asked about, so ten rows naming one project make one request. */
  const asked = useRef<Set<string>>(new Set());

  const put = useCallback((project: string, state: HandoffState) => {
    setStates((current) => new Map(current).set(project, state));
  }, []);

  const load = useCallback(
    (project: string) => {
      if (asked.current.has(project)) return;
      asked.current.add(project);
      put(project, { set: null, loading: true, missing: false });

      void (async () => {
        try {
          put(project, {
            set: await workspace.client.handoff.get(project),
            loading: false,
            missing: false,
          });
        } catch (error) {
          const missing = isApiError(error) && error.code === 'handoff.not_found';
          put(project, { set: null, loading: false, missing });
          // Only a real answer is worth remembering. Anything else — offline, a 500 — is allowed
          // to be asked again, because it may well answer differently next time.
          if (!missing) asked.current.delete(project);
        }
      })();
    },
    [workspace, put],
  );

  const value = useMemo<HandoffStore>(() => ({ states, load }), [states, load]);

  return <HandoffContext.Provider value={value}>{children}</HandoffContext.Provider>;
}

/**
 * One project's set, or nothing.
 *
 * `null` for the project is the ordinary case — a group with no handoff set named — and asks for
 * nothing. Rendered outside the provider it is inert rather than throwing: a row is not the kind
 * of component that should care whether the shell has mounted around it.
 */
export function useHandoffProject(project: string | null): HandoffState {
  const store = useContext(HandoffContext);
  // `load` rather than the whole store: the store's identity changes every time any project
  // resolves, and depending on it would re-run this effect once per row per answer.
  const load = store?.load;

  useEffect(() => {
    if (project !== null && load !== undefined) load(project);
  }, [project, load]);

  if (project === null || store === null) return NOTHING;
  return store.states.get(project) ?? NOTHING;
}
