import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Dictation, through the browser's own speech recogniser.
 *
 * Rose asked for voice notes (T-22) and the constraint is `DECISIONS.md` D-24: **free engines
 * only**. On the web that is the Web Speech API, which is already modelled in the schema as
 * `browser_speech` — and D-23 says every engine is named, with where the audio actually goes
 * stated in plain language. That is not decoration here: in Chrome this **streams audio to
 * Google**, and somebody dictating a private note deserves to know that before they press it,
 * not in a settings page they never opened.
 *
 * This hook is only the machine. The screen that uses it owes the sentence.
 *
 * ## Why the transcript is split in two
 *
 * The recogniser emits *interim* results that it then revises — "recognise" becoming "recognize"
 * becoming "recognise" again as more audio arrives. Inserting those into a document as they
 * arrive produces text that rewrites itself under the caret. So interim text is shown, live, in
 * the panel, and only **final** results are handed over for insertion.
 */

export type DictationState = 'unsupported' | 'idle' | 'listening' | 'denied' | 'error';

interface SpeechAlternative {
  readonly transcript: string;
}
interface SpeechResult {
  readonly isFinal: boolean;
  readonly length: number;
  readonly [index: number]: SpeechAlternative | undefined;
}
interface SpeechResultList {
  readonly length: number;
  readonly [index: number]: SpeechResult | undefined;
}
interface SpeechEvent {
  readonly resultIndex: number;
  readonly results: SpeechResultList;
}
interface SpeechErrorEvent {
  readonly error: string;
}
interface SpeechRecognizer {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  onresult: ((event: SpeechEvent) => void) | null;
  onerror: ((event: SpeechErrorEvent) => void) | null;
  onend: (() => void) | null;
  start(): void;
  stop(): void;
  abort(): void;
}
type RecognizerConstructor = new () => SpeechRecognizer;

function recognizerClass(): RecognizerConstructor | null {
  const scope = globalThis as {
    SpeechRecognition?: RecognizerConstructor;
    webkitSpeechRecognition?: RecognizerConstructor;
  };
  return scope.SpeechRecognition ?? scope.webkitSpeechRecognition ?? null;
}

export interface Dictation {
  readonly state: DictationState;
  /** What the recogniser is currently guessing, and has not committed to. Shown, never inserted. */
  readonly interim: string;
  /** Why it stopped, in words worth reading. `null` unless `state` is `denied` or `error`. */
  readonly problem: string | null;
  start(): void;
  stop(): void;
}

export interface DictationOptions {
  /** Called with each committed phrase. The caller decides where it goes. */
  readonly onPhrase: (text: string) => void;
  /** BCP-47. Defaults to the browser's own, which is the right guess and the only one available. */
  readonly language?: string;
}

const PROBLEM: Readonly<Record<string, string>> = {
  'not-allowed': 'The microphone was blocked. Allow it for this site and try again.',
  'service-not-allowed': 'The microphone was blocked. Allow it for this site and try again.',
  'no-speech': 'Nothing was picked up. Check the microphone is the one you think it is.',
  'audio-capture': 'No microphone was found.',
  network: 'The speech service could not be reached.',
  aborted: 'Stopped.',
};

export function useDictation({ onPhrase, language }: DictationOptions): Dictation {
  const supported = recognizerClass() !== null;
  const [state, setState] = useState<DictationState>(supported ? 'idle' : 'unsupported');
  const [interim, setInterim] = useState('');
  const [problem, setProblem] = useState<string | null>(null);
  const recognizer = useRef<SpeechRecognizer | null>(null);
  // The callback changes identity every render; a ref keeps the recogniser's handler pointing at
  // the current one without tearing the recogniser down and losing the audio stream mid-sentence.
  const phrase = useRef(onPhrase);
  phrase.current = onPhrase;

  const stop = useCallback(() => {
    recognizer.current?.stop();
    recognizer.current = null;
    setInterim('');
    setState((current) => (current === 'listening' ? 'idle' : current));
  }, []);

  const start = useCallback(() => {
    const Recognizer = recognizerClass();
    if (Recognizer === null) {
      setState('unsupported');
      return;
    }
    if (recognizer.current !== null) return;

    const instance = new Recognizer();
    instance.continuous = true;
    instance.interimResults = true;
    if (language !== undefined) instance.lang = language;

    instance.onresult = (event) => {
      let pending = '';
      for (let index = event.resultIndex; index < event.results.length; index += 1) {
        const result = event.results[index];
        const text = result?.[0]?.transcript ?? '';
        if (result?.isFinal === true) {
          const trimmed = text.trim();
          if (trimmed !== '') phrase.current(`${trimmed} `);
        } else {
          pending += text;
        }
      }
      setInterim(pending);
    };

    instance.onerror = (event) => {
      const message = PROBLEM[event.error] ?? `The recogniser stopped: ${event.error}.`;
      // A blocked microphone is a different situation from a fault, and the screen says so
      // differently: one is fixed in the browser's own settings, the other is worth retrying.
      setState(
        event.error === 'not-allowed' || event.error === 'service-not-allowed' ? 'denied' : 'error',
      );
      setProblem(message);
      recognizer.current = null;
    };

    instance.onend = () => {
      recognizer.current = null;
      setInterim('');
      setState((current) => (current === 'listening' ? 'idle' : current));
    };

    recognizer.current = instance;
    setProblem(null);
    setState('listening');
    try {
      instance.start();
    } catch {
      // Already started, which the spec makes a throw rather than a no-op.
      setState('listening');
    }
  }, [language]);

  // A recogniser left running after the screen is gone keeps the microphone light on, which reads
  // as the app listening to you — the single worst impression a dictation feature can leave.
  useEffect(() => () => recognizer.current?.abort(), []);

  return { state, interim, problem, start, stop };
}
