import type { Filter, Note, Sort } from '@rosie-notes/schema';

/**
 * The filter AST, evaluated against a cached note.
 *
 * The server compiles the same tree to SQL. This is the offline half: when the API cannot be
 * reached, every scoped view (a collection, a tag, the trash) falls back to running the filter
 * over what IndexedDB already holds, so "show me my rust notes" still works on a train.
 *
 * It is deliberately a best-effort approximation of the server, and it says so:
 *
 * - `text` matches title and excerpt, because the cache holds no bodies. A note whose body
 *   matches but whose excerpt does not will be missing offline and appear when the server
 *   answers again. Better than an empty screen, and honest about being a cache.
 * - `linkedTo` with `direction: 'incoming'` can only be answered from the source note's own
 *   `links`, which the cache does have — so it works, note by note.
 */

function noteText(note: Note): string {
  return `${note.title}\n${note.excerpt}`.toLowerCase();
}

function textMatches(note: Note, filter: Extract<Filter, { type: 'text' }>): boolean {
  const haystack = (() => {
    switch (filter.field ?? 'all') {
      case 'title':
        return note.title.toLowerCase();
      case 'body':
        return note.excerpt.toLowerCase();
      default:
        return noteText(note);
    }
  })();

  const query = filter.query.trim().toLowerCase();
  if (query === '') {
    return true;
  }
  if ((filter.mode ?? 'terms') === 'phrase') {
    return haystack.includes(query);
  }
  // `terms` and `prefix` behave the same here: every word must appear somewhere, and a partial
  // last word is a prefix of a real one, so `includes` covers both.
  return query.split(/\s+/u).every((term) => haystack.includes(term));
}

function hasMatches(note: Note, target: Extract<Filter, { type: 'has' }>['target']): boolean {
  switch (target) {
    case 'link':
      return note.links.length > 0;
    case 'backlink':
      return note.backlinkCount > 0;
    case 'file':
      return note.attachments.length > 0;
    default:
      return note.attachments.some((attachment) => attachment.kind === target);
  }
}

/** Does this note satisfy the filter? */
export function matchesFilter(note: Note, filter: Filter): boolean {
  switch (filter.type) {
    case 'all':
      return true;
    case 'and':
      return filter.filters.every((child) => matchesFilter(note, child));
    case 'or':
      return filter.filters.some((child) => matchesFilter(note, child));
    case 'not':
      return !matchesFilter(note, filter.filter);
    case 'tag':
      return note.tags.includes(filter.tag);
    case 'collection':
      return note.collectionIds.includes(filter.collectionId);
    case 'kind':
      return note.kind === filter.kind;
    case 'text':
      return textMatches(note, filter);
    case 'has':
      return hasMatches(note, filter.target);
    case 'date': {
      // ISO-8601 UTC, so string comparison is chronological comparison.
      const value = filter.field === 'created' ? note.createdAt : note.updatedAt;
      return filter.op === 'after' ? value >= filter.value : value <= filter.value;
    }
    case 'linkedTo': {
      const direction = filter.direction ?? 'either';
      const outgoing = note.links.some((link) => link.targetNoteId === filter.noteId);
      if (direction === 'outgoing') {
        return outgoing;
      }
      // Incoming cannot be answered from this note alone; `filterNotes` handles the whole-set
      // case, so treat it as "not from here" and let the caller widen it.
      return direction === 'either' ? outgoing : false;
    }
    case 'flag':
      switch (filter.flag) {
        case 'pinned':
          return note.pinned === filter.value;
        case 'archived':
          return note.archived === filter.value;
        default:
          return note.trashed === filter.value;
      }
    default:
      return true;
  }
}

/** Does the tree mention `trashed` anywhere? Decides whether the default exclusion applies. */
export function mentionsFlag(filter: Filter | null, flag: 'trashed' | 'archived'): boolean {
  if (filter === null) {
    return false;
  }
  switch (filter.type) {
    case 'flag':
      return filter.flag === flag;
    case 'and':
    case 'or':
      return filter.filters.some((child) => mentionsFlag(child, flag));
    case 'not':
      return mentionsFlag(filter.filter, flag);
    default:
      return false;
  }
}

function compare(left: Note, right: Note, sort: Sort): number {
  const direction = sort.direction === 'asc' ? 1 : -1;
  switch (sort.field) {
    case 'title':
      return left.title.localeCompare(right.title) * direction;
    case 'kind':
      return left.kind.localeCompare(right.kind) * direction;
    case 'wordCount':
      return (left.wordCount - right.wordCount) * direction;
    case 'createdAt':
      return left.createdAt.localeCompare(right.createdAt) * direction;
    case 'lastSeenAt':
      return (left.lastSeenAt ?? '').localeCompare(right.lastSeenAt ?? '') * direction;
    default:
      return left.updatedAt.localeCompare(right.updatedAt) * direction;
  }
}

export interface LocalQuery {
  readonly filter?: Filter | null | undefined;
  readonly sort?: Sort | undefined;
  readonly limit?: number | undefined;
}

/**
 * Run a query over cached notes, applying the server's own defaults: trashed notes are excluded
 * unless the filter says otherwise, and pinned notes float to the top of an `updatedAt` sort.
 */
export function filterNotes(notes: readonly Note[], query: LocalQuery = {}): Note[] {
  const filter = query.filter ?? null;
  const includeTrashed = mentionsFlag(filter, 'trashed');

  const matched = notes.filter((note) => {
    if (!includeTrashed && note.trashed) {
      return false;
    }
    return filter === null || matchesFilter(note, filter);
  });

  const sort: Sort = query.sort ?? { field: 'updatedAt', direction: 'desc' };
  matched.sort((left, right) => {
    if (sort.field === 'updatedAt' && left.pinned !== right.pinned) {
      return left.pinned ? -1 : 1;
    }
    return compare(left, right, sort);
  });

  return query.limit === undefined ? matched : matched.slice(0, query.limit);
}
