import type { Note, StoryMeta, StoryStatus } from '@rosie-notes/schema';
import { StoryMetaSchema } from '@rosie-notes/schema';
import { useEffect, useId, useState } from 'react';
import { useNoteActions } from '../hooks/use-note-actions';
import { useStoryLibrary } from '../hooks/use-stories';
import { useNavigate } from '../routing/use-route';
import { Btn, OptionStrip, SetGroup, SetRow, SetTextRow } from './primitives';

/**
 * A story's own facts — creator, source, kind, status, rating — editable right on the note (T-20).
 *
 * Rose: *"with stories it also needs to be able to handle like usernames, source, ect fields so
 * then we can have like 'profiles of users', types, ect"*. `creator` and `source` are free text
 * with a `<datalist>` of what is already in use, built from `/v1/stories/creators` and
 * `/v1/stories/facets` — a suggestion list, never a closed one, because the whole point is that a
 * name Rose has not typed before must still go straight in.
 *
 * Every commit sends the **entire** `story` object, never a one-field patch. `NoteUpdateRequest`
 * replaces `meta.story` wholesale when the key is present at all — see the warning on
 * `OptionalNoteMetaSchema` in `note-meta.ts` — so a patch of just `{ rating: '9' }` would silently
 * erase the creator this same screen just saved. `draft` exists so every field has the rest of the
 * bag to hand when any one of them blurs.
 */

export interface StoryFieldsProps {
  readonly note: Note;
}

const EMPTY_STORY: StoryMeta = StoryMetaSchema.parse({});

const STATUS_OPTIONS: readonly { readonly value: StoryStatus; readonly label: string }[] = [
  { value: 'unknown', label: 'Unknown' },
  { value: 'ongoing', label: 'Ongoing' },
  { value: 'complete', label: 'Complete' },
  { value: 'hiatus', label: 'On hiatus' },
  { value: 'abandoned', label: 'Abandoned' },
];

export function StoryFields({ note }: StoryFieldsProps): React.JSX.Element {
  const actions = useNoteActions();
  const navigate = useNavigate();
  const library = useStoryLibrary();
  const [draft, setDraft] = useState<StoryMeta>(note.meta?.story ?? EMPTY_STORY);
  const [statusExpanded, setStatusExpanded] = useState(false);

  // Re-seeded whenever the note object changes, same as the title field above it on this screen —
  // an edit that has not yet been committed (not blurred) can be overwritten by a sync update from
  // another device, which is the accepted trade-off here rather than something new to this field.
  useEffect(() => {
    setDraft(note.meta?.story ?? EMPTY_STORY);
  }, [note]);

  function change<K extends keyof StoryMeta>(key: K, value: StoryMeta[K]): void {
    setDraft((current) => ({ ...current, [key]: value }));
  }

  function commit(patch: Partial<StoryMeta> = {}): void {
    const next = { ...draft, ...patch };
    setDraft(next);
    void actions.update(note.id, { meta: { story: next } });
  }

  const creatorListId = useId();
  const sourceListId = useId();
  const trimmedCreator = draft.creator.trim();

  return (
    <SetGroup title="Story details">
      <div className="setrow setrow-stack">
        <label className="setrow-label" htmlFor={creatorListId}>
          Creator
        </label>
        <input
          className="field"
          id={creatorListId}
          list={`${creatorListId}-options`}
          onBlur={() => commit()}
          onChange={(event) => change('creator', event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') event.currentTarget.blur();
          }}
          placeholder="Who made this"
          value={draft.creator}
        />
        <datalist id={`${creatorListId}-options`}>
          {library.creators.map((creator) => (
            <option key={creator.name} value={creator.name} />
          ))}
        </datalist>
      </div>

      {trimmedCreator !== '' && (
        <div className="setrow">
          <Btn
            icon="people"
            onClick={() => navigate({ name: 'creator', creatorName: trimmedCreator })}
            small
            tone="quiet"
          >
            Everything by {trimmedCreator}
          </Btn>
        </div>
      )}

      <SetTextRow
        label="Creator's page"
        onChange={(value) => change('creatorUrl', value)}
        onCommit={() => commit()}
        placeholder="https://…"
        value={draft.creatorUrl}
      />

      <div className="setrow setrow-stack">
        <label className="setrow-label" htmlFor={sourceListId}>
          Source
        </label>
        <input
          className="field"
          id={sourceListId}
          list={`${sourceListId}-options`}
          onBlur={() => commit()}
          onChange={(event) => change('source', event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') event.currentTarget.blur();
          }}
          placeholder="Where you found it"
          value={draft.source}
        />
        <datalist id={`${sourceListId}-options`}>
          {library.facets.source.map((facet) => (
            <option key={facet.value} value={facet.value} />
          ))}
        </datalist>
      </div>

      <SetTextRow
        label="Source link"
        onChange={(value) => change('sourceUrl', value)}
        onCommit={() => commit()}
        placeholder="https://…"
        value={draft.sourceUrl}
      />

      <SetTextRow
        label="Type"
        onChange={(value) => change('storyType', value)}
        onCommit={() => commit()}
        placeholder="Whatever you'd call it"
        value={draft.storyType}
      />

      <SetRow
        expanded={statusExpanded}
        label="Status"
        onClick={() => setStatusExpanded((expanded) => !expanded)}
        value={STATUS_OPTIONS.find((option) => option.value === draft.status)?.label ?? 'Unknown'}
      >
        <OptionStrip
          label="Status"
          onChange={(value) => {
            commit({ status: value });
            setStatusExpanded(false);
          }}
          options={STATUS_OPTIONS}
          value={draft.status}
        />
      </SetRow>

      <SetTextRow
        label="Rating"
        onChange={(value) => change('rating', value)}
        onCommit={() => commit()}
        placeholder="However you rate it"
        value={draft.rating}
      />
    </SetGroup>
  );
}
