import { type ReactNode, useEffect, useRef, useState } from 'react';
import { Icon, type IconName } from './icons';

/**
 * The menu you get from a right-click.
 *
 * Rose: *"you should be able to right click it to see a right click menu that allows you to do
 * some quick actions such as, rename, move to, delete, ect"*.
 *
 * This replaces what right-click did before — tick the row for multi-select — which was a
 * reasonable guess and is not what a right-click means to anybody. Selecting is still in the menu,
 * so nothing is lost.
 *
 * ## Where it opens, and why that is fiddly
 *
 * At the pointer, clamped so it never hangs off the screen. A menu that opens half off the bottom
 * edge on the last row of a list is exactly the case that matters, because the last row is the one
 * people right-click most.
 *
 * ## Keyboard
 *
 * Escape closes, arrows move, Enter runs. It is also reachable **without a pointer at all**: the
 * `Menu` key and Shift+F10 are what a keyboard sends for "context menu", and both are handled
 * where the row is, so this is not a mouse-only feature.
 */

export interface RowMenuItem {
  readonly label: string;
  readonly icon: IconName;
  readonly run: () => void;
  /** Renders in the danger tone and sits below a separator. */
  readonly danger?: boolean;
  readonly disabled?: boolean;
}

export interface RowMenuProps {
  readonly x: number;
  readonly y: number;
  /** Named so a screen reader says what the menu is for, not just "menu". */
  readonly label: string;
  readonly items: readonly RowMenuItem[];
  readonly onClose: () => void;
}

/** Roughly what one item costs, for the clamp. Exact enough; the menu is re-clamped once mounted. */
const ITEM_HEIGHT = 36;
const MENU_WIDTH = 210;
const EDGE = 8;

export function RowMenu({ x, y, label, items, onClose }: RowMenuProps): React.JSX.Element {
  const menu = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(0);
  const live = items.filter((item) => item.disabled !== true);

  useEffect(() => {
    // Focus the menu itself rather than the first item: a screen reader then announces the menu's
    // name before its contents, which is the difference between "Actions for Dreams" and "Rename".
    menu.current?.focus();
  }, []);

  useEffect(() => {
    const close = (): void => onClose();
    // `pointerdown` rather than `click`, so a press anywhere else dismisses before that press
    // becomes a click on whatever is underneath.
    globalThis.addEventListener('pointerdown', close);
    globalThis.addEventListener('resize', close);
    globalThis.addEventListener('scroll', close, true);
    return () => {
      globalThis.removeEventListener('pointerdown', close);
      globalThis.removeEventListener('resize', close);
      globalThis.removeEventListener('scroll', close, true);
    };
  }, [onClose]);

  const height = items.length * ITEM_HEIGHT + 12;
  const width = globalThis.innerWidth ?? 1024;
  const viewport = globalThis.innerHeight ?? 768;
  const left = Math.min(Math.max(EDGE, x), Math.max(EDGE, width - MENU_WIDTH - EDGE));
  // Flip above the pointer when there is no room below — the last row of a list is the one people
  // right-click most, and it is the one with no room.
  const top = y + height + EDGE > viewport ? Math.max(EDGE, y - height) : y;

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>): void {
    if (event.key === 'Escape') {
      event.preventDefault();
      onClose();
      return;
    }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      const step = event.key === 'ArrowDown' ? 1 : -1;
      setActive((current) => (current + step + live.length) % live.length);
      return;
    }
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      const item = live[active];
      if (item !== undefined) {
        onClose();
        item.run();
      }
    }
  }

  return (
    <div
      aria-label={label}
      className="rowmenu"
      onKeyDown={onKeyDown}
      // The menu swallows its own pointerdown so the dismiss listener above does not close it
      // before the click on an item lands.
      onPointerDown={(event) => event.stopPropagation()}
      ref={menu}
      role="menu"
      style={{ left, top }}
      tabIndex={-1}
    >
      {items.map((item, index) => (
        <button
          aria-disabled={item.disabled === true}
          className={item.danger === true ? 'rowmenu-item is-danger' : 'rowmenu-item'}
          data-active={live[active] === item ? 'true' : undefined}
          disabled={item.disabled === true}
          key={item.label}
          onClick={() => {
            onClose();
            item.run();
          }}
          onMouseEnter={() => {
            const at = live.indexOf(item);
            if (at !== -1) setActive(at);
          }}
          role="menuitem"
          type="button"
        >
          <Icon name={item.icon} />
          <span>{item.label}</span>
        </button>
      ))}
    </div>
  );
}

/** What a row needs to open one. Kept together so a row hands over one object. */
export interface RowMenuState {
  readonly x: number;
  readonly y: number;
  readonly label: string;
  readonly items: readonly RowMenuItem[];
}

/**
 * Where to put a menu opened from the keyboard.
 *
 * `Menu` and Shift+F10 carry no coordinates, so the menu goes at the row's own bottom-left — which
 * is where a mouse user would have opened it anyway.
 */
export function anchorFor(element: HTMLElement | null): { x: number; y: number } {
  const box = element?.getBoundingClientRect();
  return box === undefined ? { x: 40, y: 80 } : { x: box.left + 24, y: box.bottom - 4 };
}

/** Convenience for the common "a separator before the destructive one" shape. */
export function menuItems(...items: (RowMenuItem | null)[]): readonly RowMenuItem[] {
  return items.filter((item): item is RowMenuItem => item !== null);
}

export type { ReactNode };
