import type { CollectionId, GroupSettings, GroupSettingsOverrides } from '@rosie-notes/schema';
import { useCallback, useRef, useState } from 'react';
import { useGroupSettings, useGroups } from '../hooks/use-groups';
import { useNavigate } from '../routing/use-route';
import { Breadcrumb, PageHeader } from './chrome';
import { GroupSettingsForm } from './group-settings-form';
import { settingsSentence } from './labels';
import { Btn, SetGroup, SetRow, SetTextRow, Sheet } from './primitives';
import type { OriginProps } from './settings-rows';
import { LoadingState, NotFoundState, OfflineBanner } from './states';
import { useToast } from './toasts';

/**
 * A group's settings, as a screen rather than a sheet.
 *
 * It is a screen for two reasons. It is linkable — `#/group/xyz/settings` is a thing one person
 * sends another — and it is long: fifteen settings in a bottom sheet is a scroll inside a scroll,
 * which is the worst shape a phone can be given.
 *
 * It opens with the settings **read back as a sentence**. That paragraph is what stops fifteen
 * rows feeling like a control panel: a person can read one line and know what this group is
 * without parsing a form.
 */

export interface GroupSettingsViewProps {
  readonly groupId: string;
}

export function GroupSettingsView({ groupId }: GroupSettingsViewProps): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const toast = useToast();
  const state = useGroupSettings(groupId);
  const [name, setName] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [saving, setSaving] = useState(false);
  /** The name currently being written, so blur and the Save button do not both send it. */
  const renaming = useRef<string | null>(null);

  const group = tree.byId.get(groupId);

  const nameOf = useCallback(
    (id: string | null) => (id === null ? null : (tree.byId.get(id)?.name ?? null)),
    [tree],
  );

  if (group === undefined) {
    if (tree.loading) return <LoadingState label="Opening the group…" />;
    return <NotFoundState onBack={() => navigate({ name: 'home' })} what="That group" />;
  }

  const settings = state.effective;
  const origin: OriginProps = { origins: state.resolved.origins, nameOf, groupId };

  /**
   * A patch of a patch.
   *
   * What is stored on a group is only what is **explicitly set here**, so writing a value the
   * person just chose is what "set here" means — and it is why a row that was inherited becomes
   * "Set here" the moment it is touched. Going back to inheriting is `null`, which the delete
   * affordance on each family would use; see the seam note in the report.
   */
  async function patch(next: Partial<GroupSettings>): Promise<void> {
    setSaving(true);
    try {
      await tree.update(groupId as CollectionId, { settings: next as GroupSettingsOverrides });
      state.reload();
    } catch {
      toast.show('That change did not reach the server.', { tone: 'clay', icon: 'warn' });
    } finally {
      setSaving(false);
    }
  }

  /**
   * Commit the name, if there is one to commit.
   *
   * Wired to **blur, Enter and Done** as well as the explicit button, because those are the three
   * things a person actually does when they have finished typing in a field — and a rename that
   * is silently discarded by all three is indistinguishable from one that saved. The note title
   * on the note screen commits the same way; this field was the odd one out.
   *
   * `name` is cleared on success so the field goes back to tracking the group, and the "not saved
   * yet" row disappears rather than lingering over a value that *is* saved.
   */
  async function rename(): Promise<void> {
    const trimmed = (name ?? '').trim();
    if (trimmed === '' || trimmed === group?.name) {
      // Nothing to save. An emptied field is a mistake, not an instruction — put the name back.
      if (name !== null) setName(null);
      return;
    }
    // Clicking "Save name" blurs the field first, so both paths fire for one intention. The
    // guard is a ref rather than state because it has to be true *before* the next render.
    if (renaming.current === trimmed) return;
    renaming.current = trimmed;
    try {
      await tree.update(groupId as CollectionId, { name: trimmed });
      setName(null);
      toast.show('Renamed.');
    } catch {
      toast.show('That rename did not reach the server.', { tone: 'clay', icon: 'warn' });
    } finally {
      renaming.current = null;
    }
  }

  return (
    <>
      <Breadcrumb
        chain={tree.chain(groupId)}
        leaf="Settings"
        onHome={() => navigate({ name: 'home' })}
        onOpen={(ancestor) => navigate({ name: 'group', groupId: ancestor.id as string })}
      />
      <PageHeader
        actions={
          <Btn
            onClick={() => {
              // Leaving the screen is also "I am finished with that field".
              void rename().then(() => navigate({ name: 'group', groupId }));
            }}
            tone="ghost"
          >
            Done
          </Btn>
        }
        icon={group.icon}
        sub={<span>{settingsSentence(settings, [])}</span>}
        title={`${group.name} settings`}
      />

      {state.local && !state.loading && <OfflineBanner what="settings" />}

      <SetGroup title="Identity">
        <SetTextRow
          help="Renaming is free — notes point at the group, not at its name."
          label="Name"
          onChange={setName}
          onCommit={() => void rename()}
          value={name ?? group.name}
        />
        {name !== null && name.trim() !== group.name && (
          <div className="setrow">
            <span className="setrow-main">
              <span className="setrow-help">Not saved yet.</span>
            </span>
            <Btn onClick={() => void rename()} small tone="primary">
              Save name
            </Btn>
          </div>
        )}
      </SetGroup>

      <GroupSettingsForm
        groupId={groupId}
        groupName={group.name}
        onChange={(next) => void patch(next)}
        origin={origin}
        resolved={state.resolved}
        settings={settings}
      />

      <SetGroup title="This group">
        <SetRow
          danger
          help="Moves it to the trash. Subgroups are promoted rather than destroyed with it, and the notes are kept unless you say otherwise."
          label="Delete group"
          onClick={() => setConfirmDelete(true)}
          value={<span />}
        />
      </SetGroup>

      {saving && <span className="sr">Saving…</span>}

      {confirmDelete && (
        <Sheet
          onClose={() => setConfirmDelete(false)}
          sub={
            <>
              Its subgroups move up to the top level rather than going with it, and the notes in it
              are kept. Nothing here is removed from anyone you shared it with until you say so.
            </>
          }
          title={`Delete ${group.name}?`}
        >
          <p className="setrow-help">
            {tree.tally(groupId).groups} subgroups and {tree.tally(groupId).notes} notes are inside
            it right now.
          </p>
          <div className="form__actions" style={{ marginTop: 16 }}>
            <Btn onClick={() => setConfirmDelete(false)} tone="ghost">
              Keep it
            </Btn>
            <Btn
              onClick={() => {
                void tree.remove(groupId as CollectionId).then(() => {
                  toast.show('Deleted.', { tone: 'clay', icon: 'trash' });
                  navigate({ name: 'home' }, { replace: true });
                });
              }}
              tone="danger"
            >
              Delete {group.name}
            </Btn>
          </div>
        </Sheet>
      )}
    </>
  );
}
