import { useEffect, useRef, useState } from 'react';
import { useWorkspace } from '../session/session-context';
import { Icon } from './icons';

/**
 * Reading the text out of a screenshot, and putting it in the note (T-23).
 *
 * The value, in Rose's own terms: a screenshot of an error message becomes findable by its text.
 * The OCR happens on the server that already holds the notes — free, on their own laptop, and
 * working in any browser, which the two browser-side options are not (see `api/src/services/ocr.ts`
 * for why).
 *
 * Same shape as {@link Dictate} next to it, for the same reason: `DECISIONS.md` D-23 asks that the
 * engine be named and that where the image goes be said in plain language. Here the sentence is
 * short and true — the image goes to your own server and no further.
 *
 * ## Nothing rather than a dead button
 *
 * `tesseract` is an optional layer in the API image, so a healthy server may not have it. The
 * status is asked once, and when the answer is no this renders **nothing** — the same rule
 * dictation follows for a browser with no recogniser. Offering a control that cannot work is
 * worse than not mentioning the feature.
 */

/**
 * A file as base64, without a data-URI prefix.
 *
 * `FileReader` rather than looping over the bytes: `String.fromCharCode(...bytes)` blows the
 * argument limit on anything above a megabyte or so, and a screenshot always is.
 */
function toBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('That file could not be read.'));
    reader.onload = () => {
      const result = typeof reader.result === 'string' ? reader.result : '';
      resolve(result.slice(result.indexOf(',') + 1));
    };
    reader.readAsDataURL(file);
  });
}

export interface ReadImageProps {
  /** Where the text goes. Typically the editor's `insertText` command. */
  readonly onText: (text: string) => void;
  readonly disabled?: boolean;
}

type State = 'unknown' | 'unavailable' | 'ready' | 'reading' | 'failed';

export function ReadImage({ onText, disabled = false }: ReadImageProps): React.JSX.Element | null {
  const workspace = useWorkspace();
  const picker = useRef<HTMLInputElement>(null);
  const [state, setState] = useState<State>('unknown');
  const [engine, setEngine] = useState<string | null>(null);
  const [problem, setProblem] = useState<string | null>(null);
  const [found, setFound] = useState<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const status = await workspace.client.ocr.status();
        if (cancelled) return;
        setEngine(status.version);
        setState(status.available ? 'ready' : 'unavailable');
      } catch {
        // An older server has no such route. Same outcome as not installed, and just as quiet.
        if (!cancelled) setState('unavailable');
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspace]);

  async function read(file: File): Promise<void> {
    setState('reading');
    setProblem(null);
    setFound(null);
    try {
      const result = await workspace.client.ocr.read(await toBase64(file));
      setEngine(result.engine);
      if (result.text.trim() === '') {
        // A real answer, and a common one for a photo of a whiteboard. Saying so beats inserting
        // nothing and leaving somebody wondering whether the button worked.
        setProblem('No text was found in that image.');
        setState('ready');
        return;
      }
      onText(`${result.text}\n`);
      setFound(result.text.split(/\s+/u).filter((word) => word !== '').length);
      setState('ready');
    } catch (error) {
      setProblem(error instanceof Error ? error.message : 'That image could not be read.');
      setState('failed');
    }
  }

  if (state === 'unknown' || state === 'unavailable') return null;

  return (
    <div className="dictate">
      <button
        className="dictate-btn"
        disabled={disabled || state === 'reading'}
        onClick={() => picker.current?.click()}
        type="button"
      >
        <Icon name="image" />
        <span>{state === 'reading' ? 'Reading…' : 'Read an image'}</span>
      </button>
      <input
        accept="image/*"
        className="sr"
        onChange={(event) => {
          const file = event.target.files?.[0];
          // Cleared so picking the same file twice in a row fires `change` the second time.
          event.target.value = '';
          if (file !== undefined) void read(file);
        }}
        ref={picker}
        type="file"
      />

      <span className="dictate-where">
        {engine === null ? 'Your own server' : engine} — the image is sent to your own server, and
        no further.
      </span>

      {found !== null && (
        <span className="dictate-interim" role="status">
          {found} {found === 1 ? 'word' : 'words'} added.
        </span>
      )}
      {problem !== null && (
        <span className="dictate-problem" role="alert">
          {problem}
        </span>
      )}
    </div>
  );
}
