import type { ExportDocument, ExportFormat, ExportResult } from '@rosie-notes/editor';
import { EXPORT_FORMATS, exportDocuments, exportFormat } from '@rosie-notes/editor';
import type { CollectionId, Note, NoteId } from '@rosie-notes/schema';
import { useCallback, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useWorkspace } from '../session/session-context';
import { NOTE_KIND_LABEL, plural } from './labels';
import { Callout, Sheet } from './primitives';
import { useToast } from './toasts';

/**
 * Exporting, from the app (T-17).
 *
 * Rose: *"everything exportable — notes, groups, all of it"*. The rendering all lives in
 * `@rosie-notes/editor`, over the same AST the editor parses markdown into, so what comes out
 * cannot disagree with what is on screen. This file is only the three things a browser adds:
 * fetching the bodies, choosing a format, and handing the file over.
 *
 * A group export takes **everything under it**, at every depth, because "export this project"
 * meaning "export the six notes at its top level and none of the forty below" would be a
 * surprise discovered after the fact.
 */

/** Hand a rendered file to the browser. */
function download(result: ExportResult): void {
  const blob = new Blob([result.bytes as BlobPart], { type: result.mime });
  const url = URL.createObjectURL(blob);
  const anchor = globalThis.document.createElement('a');
  anchor.href = url;
  anchor.download = result.filename;
  anchor.rel = 'noopener';
  globalThis.document.body.append(anchor);
  anchor.click();
  anchor.remove();
  // Revoked on the next task rather than immediately: Safari has historically cancelled the
  // download when the URL went away in the same tick as the click.
  globalThis.setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/**
 * Open a printable page in a new tab and offer the print dialog.
 *
 * This is the whole of "PDF". A hand-written PDF would be worse than the one the browser makes
 * from a print stylesheet, so the button says *"Print, or save as PDF"* — which is what happens.
 * A blocked pop-up falls back to downloading the page, because losing the export entirely
 * because of a browser setting is not an acceptable outcome.
 */
function print(result: ExportResult, onBlocked: () => void): void {
  const blob = new Blob([result.bytes as BlobPart], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const tab = globalThis.open(url, '_blank', 'noopener');
  if (tab === null) {
    URL.revokeObjectURL(url);
    onBlocked();
    download(result);
    return;
  }
  tab.addEventListener('load', () => tab.print(), { once: true });
  globalThis.setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

/** The metadata block an exported note carries above its body. */
function metaOf(note: Note): readonly (readonly [string, string])[] {
  const meta: (readonly [string, string])[] = [['Kind', NOTE_KIND_LABEL[note.kind]]];
  if (note.tags.length > 0) meta.push(['Tags', note.tags.join(', ')]);
  meta.push(['Updated', note.updatedAt.slice(0, 10)]);
  return meta;
}

export interface ExportSubject {
  /** What is being exported, for the sheet's title and the filename. */
  readonly name: string;
  /** A single note, or every note under a group. */
  readonly source: { readonly note: NoteId } | { readonly group: CollectionId };
}

export function ExportSheet({
  subject,
  onClose,
}: {
  readonly subject: ExportSubject;
  readonly onClose: () => void;
}): React.JSX.Element {
  const workspace = useWorkspace();
  const tree = useGroups();
  const toast = useToast();
  const [busy, setBusy] = useState<ExportFormat | null>(null);
  const [failure, setFailure] = useState<string | null>(null);

  const pathOf = useCallback(
    (note: Note): readonly string[] =>
      tree.chain((note.collectionIds[0] as string | undefined) ?? null).map((group) => group.name),
    [tree],
  );

  /**
   * Gather the bodies.
   *
   * `includeBody` on the listing rather than one `GET /v1/notes/:id` per note: exporting a group
   * of ninety notes as ninety round trips over a tunnel is slow enough to look broken, and the
   * server already has the flattened body it indexes for search.
   */
  const gather = useCallback(async (): Promise<readonly ExportDocument[]> => {
    if ('note' in subject.source) {
      const note = await workspace.client.notes.get(subject.source.note);
      return [
        {
          title: note.title === '' ? 'Untitled' : note.title,
          markdown: note.body?.text ?? '',
          path: pathOf(note),
          meta: metaOf(note),
        },
      ];
    }

    const descendants = new Set<string>([subject.source.group as string]);
    const stack = [subject.source.group as string];
    while (stack.length > 0) {
      const next = stack.pop();
      if (next === undefined) continue;
      for (const child of tree.children(next)) {
        descendants.add(child.id as string);
        stack.push(child.id as string);
      }
    }

    const out: ExportDocument[] = [];
    for (const groupId of descendants) {
      let cursor: string | null = null;
      do {
        const page = await workspace.client.notes.list({
          collectionId: groupId as CollectionId,
          includeBody: true,
          limit: 100,
          ...(cursor === null ? {} : { cursor }),
        });
        for (const note of page.items) {
          if (note.trashed) continue;
          out.push({
            title: note.title === '' ? 'Untitled' : note.title,
            markdown: note.body?.text ?? note.excerpt,
            path: pathOf(note),
            meta: metaOf(note),
          });
        }
        cursor = page.nextCursor ?? null;
      } while (cursor !== null);
    }
    return out;
  }, [pathOf, subject.source, tree, workspace]);

  async function run(format: ExportFormat): Promise<void> {
    setBusy(format);
    setFailure(null);
    try {
      const documents = await gather();
      const result = exportDocuments(documents, format, { name: subject.name });
      if (format === 'pdf') {
        print(result, () => toast.show('Your browser blocked the tab, so it downloaded instead.'));
      } else {
        download(result);
      }
      toast.show(`Exported ${plural(documents.length, 'note')} as ${exportFormat(format).label}.`, {
        icon: 'doc',
      });
      onClose();
    } catch (error) {
      setFailure(
        error instanceof Error ? error.message : 'That did not export. Nothing was changed.',
      );
    } finally {
      setBusy(null);
    }
  }

  const many = 'group' in subject.source;

  return (
    <Sheet
      onClose={onClose}
      sub={
        many
          ? 'Everything in this group and everything under it.'
          : 'This note, as it is written now.'
      }
      title={`Export ${subject.name}`}
    >
      <div style={{ display: 'grid', gap: 10 }}>
        {/* Says who can read the file, never how it is stored — the same rule as everywhere else
            in the app (DECISIONS.md D-03). An exported file leaves every protection behind. */}
        <Callout icon="eye" tone="quiet">
          An exported file is <b>plain</b>. Anyone who opens it can read it, so put it somewhere you
          would be happy for it to be read.
        </Callout>

        <div className="setlist">
          {EXPORT_FORMATS.map((format) => (
            <button
              className="setrow"
              disabled={busy !== null}
              key={format.id}
              onClick={() => void run(format.id)}
              type="button"
            >
              <span className="setrow-main">
                <span className="setrow-label">{format.label}</span>
                <span className="setrow-help">{format.note}</span>
              </span>
              <span className="setrow-value">
                {busy === format.id ? <span className="inh">Working…</span> : null}
              </span>
            </button>
          ))}
        </div>

        {failure !== null && (
          <Callout icon="warn" tone="clay">
            {failure}
          </Callout>
        )}
      </div>
    </Sheet>
  );
}
