import type { Note, NoteId } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNoteQuery } from '../hooks/use-note-query';
import { useNavigate } from '../routing/use-route';
import { plural } from './labels';
import { Sep, Switch } from './primitives';
import { AddRow, List, Row } from './rail';

/**
 * The chapter list under a story (T-19, D-41).
 *
 * A chapter is a child note — `note.parentId` already gives the tree, so this reads it through
 * `useNoteQuery({ parentId: storyId })` exactly like any other scoped listing rather than a
 * chapter table of its own. That is also what keeps a chapter a completely ordinary note: it is
 * searchable, exportable, taggable and syncable for free, and this component's only job is
 * presenting `chapterNumber` order and the `skippable` flag, not storing either one.
 *
 * Mounted on every `story`-kind note, chapters and top-level stories alike — nothing here assumes
 * it is sitting under "the" story rather than under a chapter that happens to have sub-chapters of
 * its own. If there are no children yet it still renders, as a single "Add a chapter" row, because
 * that is the only way the first one gets made.
 */

export interface ChaptersProps {
  readonly storyId: NoteId;
}

/** A child's `meta.story.chapterNumber`, or `null` when it was never set. */
export function chapterNumberOf(note: Note): number | null {
  return note.meta?.story?.chapterNumber ?? null;
}

export function isSkippable(note: Note): boolean {
  return note.meta?.story?.skippable ?? false;
}

/**
 * Numbered chapters first, in order; anything without a number after them, oldest first. A child
 * note with no `chapterNumber` is not an error — it might be a stray note someone dropped in here
 * before deciding it was a chapter at all — so it is shown rather than hidden, just last.
 */
export function orderChapters(notes: readonly Note[]): Note[] {
  return [...notes].sort((left, right) => {
    const leftNumber = chapterNumberOf(left);
    const rightNumber = chapterNumberOf(right);
    if (leftNumber !== null && rightNumber !== null) {
      return leftNumber - rightNumber || left.createdAt.localeCompare(right.createdAt);
    }
    if (leftNumber !== null) return -1;
    if (rightNumber !== null) return 1;
    return left.createdAt.localeCompare(right.createdAt);
  });
}

/** One past the highest number in use, or `1` for the first chapter. Gaps are never filled in. */
export function nextChapterNumber(chapters: readonly Note[]): number {
  const highest = chapters.reduce((max, note) => Math.max(max, chapterNumberOf(note) ?? 0), 0);
  return highest + 1;
}

export function Chapters({ storyId }: ChaptersProps): React.JSX.Element | null {
  const navigate = useNavigate();
  const actions = useNoteActions();
  const query = useMemo(() => ({ parentId: storyId, limit: 200 }), [storyId]);
  const children = useNoteQuery(query);
  const [hideSkippable, setHideSkippable] = useState(false);

  const chapters = useMemo(() => orderChapters(children.notes), [children.notes]);
  const skippableCount = chapters.filter(isSkippable).length;
  const visible = hideSkippable ? chapters.filter((note) => !isSkippable(note)) : chapters;

  async function addChapter(): Promise<void> {
    const number = nextChapterNumber(chapters);
    const created = await actions.create({
      title: `Chapter ${number}`,
      kind: 'story',
      parentId: storyId,
      meta: { story: { chapterNumber: number } },
    });
    navigate({ name: 'note', noteId: created as string });
  }

  if (children.loading && chapters.length === 0) {
    return null;
  }

  return (
    <section className="sec">
      {chapters.length > 0 && (
        <>
          <div className="sec-head">
            <h2 className="sec-title">Chapters</h2>
            <span className="sec-note num">{plural(chapters.length, 'chapter')}</span>
          </div>
          {skippableCount > 0 && (
            <div className="setrow">
              <span className="setrow-main">
                <span className="setrow-label">Hide the optional ones</span>
                <span className="setrow-help">
                  {plural(skippableCount, 'chapter')} marked skippable
                </span>
              </span>
              <Switch
                checked={hideSkippable}
                label="Hide the optional chapters"
                onChange={setHideSkippable}
              />
            </div>
          )}
          <List label="Chapters">
            {visible.map((chapter) => (
              <ChapterRow chapter={chapter} key={chapter.id} onOpen={navigate} />
            ))}
          </List>
        </>
      )}
      <AddRow label="Add a chapter" onClick={() => void addChapter()} />
    </section>
  );
}

function ChapterRow({
  chapter,
  onOpen,
}: {
  readonly chapter: Note;
  readonly onOpen: (route: { name: 'note'; noteId: string }) => void;
}): React.JSX.Element {
  const number = chapterNumberOf(chapter);
  const skippable = isSkippable(chapter);
  const title = chapter.title === '' ? 'Untitled' : chapter.title;
  const meta =
    number === null && !skippable ? undefined : (
      <>
        {number !== null && <span>Chapter {number}</span>}
        {number !== null && skippable && <Sep />}
        {skippable && <span>Skippable</span>}
      </>
    );
  return (
    <Row
      kind="note"
      label={title}
      mark="none"
      meta={meta}
      onOpen={() => onOpen({ name: 'note', noteId: chapter.id as string })}
      title={title}
    />
  );
}
