import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from 'react';

/**
 * Undo and redo, for the things that are not text.
 *
 * Rose: *"can you add the ability of like ctrl+z and the reverse of that for like group moves,
 * renames, ect? so a user can quickly revert a mistaken cahnge?"*
 *
 * ## Closures, not a diff engine
 *
 * Each action registers **how to reverse itself, at the moment it happens** — when it still knows
 * the value it replaced. Nothing here inspects the tree or computes a delta afterwards, which is
 * what makes it correct: a rename knows the old name because it just read it, and no amount of
 * cleverness later recovers a name nobody kept.
 *
 * ## What it deliberately does not cover
 *
 * **Text inside a note.** ProseMirror has its own undo, and it is better than anything this could
 * do — it works per keystroke and understands the document. Ctrl+Z while the caret is in the
 * editor must reach the editor, so the shortcut ignores itself whenever focus is in a text
 * surface. Two undo stacks fighting over one keystroke is worse than one.
 *
 * ## Why the stack is per session
 *
 * It lives in memory and dies with the tab, and that is honest rather than lazy: an undo whose
 * reverse depends on rows that another device has since changed is not an undo, it is a second
 * mistake. Nothing here promises to reach back past the session it was made in.
 */

export interface HistoryEntry {
  /** What was done, in the words the toast will use: "Renamed Dreams to Journal". */
  readonly label: string;
  /** Put it back. Throwing marks the entry spent rather than leaving a broken stack. */
  undo(): Promise<void>;
  /** Do it again. */
  redo(): Promise<void>;
}

export interface History {
  /** Record something reversible that has **already happened**. */
  push(entry: HistoryEntry): void;
  undo(): Promise<HistoryEntry | null>;
  redo(): Promise<HistoryEntry | null>;
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** What Ctrl+Z would reverse, for a menu label. */
  readonly nextUndo: string | null;
  readonly nextRedo: string | null;
  clear(): void;
}

/** Deep enough for a session's mistakes, shallow enough that stale closures cannot pile up. */
const LIMIT = 50;

const HistoryContext = createContext<History | null>(null);

export function useHistory(): History {
  const value = useContext(HistoryContext);
  if (value === null) {
    throw new Error('useHistory must be used inside <HistoryProvider>');
  }
  return value;
}

/** The stack if there is one. For components that also render outside the shell. */
export function useHistoryOptional(): History | null {
  return useContext(HistoryContext);
}

export function HistoryProvider({ children }: { readonly children: ReactNode }): React.JSX.Element {
  // The stacks are refs, and the counts are state. Only the counts drive rendering — a menu
  // greying out its Undo item — and keeping the entries out of state stops every push
  // re-rendering the screen the action just changed.
  const undoStack = useRef<HistoryEntry[]>([]);
  const redoStack = useRef<HistoryEntry[]>([]);
  /*
   * `version` is in the dependency list on purpose, and getting that wrong was a real bug.
   *
   * With the memo keyed only on `refresh`, the context value kept the same identity forever — so
   * bumping the counter re-rendered the provider and React **bailed out of re-rendering every
   * consumer**, because the context value it would hand them was `Object.is`-equal to the last
   * one. The stack worked perfectly and nothing on screen ever noticed: Undo stayed greyed out
   * after an action, which is precisely the symptom a test caught here.
   */
  const [version, bump] = useState(0);
  const refresh = useCallback(() => bump((value) => value + 1), []);

  const value = useMemo<History>(
    () => ({
      push(entry) {
        undoStack.current.push(entry);
        if (undoStack.current.length > LIMIT) undoStack.current.shift();
        // A new action after an undo abandons the redo branch, which is what every editor does
        // and what people expect: the future you did not take stops existing.
        redoStack.current = [];
        refresh();
      },
      async undo() {
        const entry = undoStack.current.pop();
        if (entry === undefined) return null;
        refresh();
        try {
          await entry.undo();
          redoStack.current.push(entry);
        } catch {
          // The world moved on — the group is gone, the server refused. The entry is dropped
          // rather than put back, because retrying a reverse that has already failed once is how
          // an undo stack starts lying about what it can do.
          redoStack.current = [];
        }
        refresh();
        return entry;
      },
      async redo() {
        const entry = redoStack.current.pop();
        if (entry === undefined) return null;
        refresh();
        try {
          await entry.redo();
          undoStack.current.push(entry);
        } catch {
          undoStack.current = [];
        }
        refresh();
        return entry;
      },
      get canUndo() {
        return undoStack.current.length > 0;
      },
      get canRedo() {
        return redoStack.current.length > 0;
      },
      get nextUndo() {
        return undoStack.current.at(-1)?.label ?? null;
      },
      get nextRedo() {
        return redoStack.current.at(-1)?.label ?? null;
      },
      clear() {
        undoStack.current = [];
        redoStack.current = [];
        refresh();
      },
    }),
    // biome-ignore lint/correctness/useExhaustiveDependencies: `version` is the identity trigger
    [refresh, version],
  );

  return <HistoryContext.Provider value={value}>{children}</HistoryContext.Provider>;
}

/**
 * True when the keystroke belongs to whatever is being typed into.
 *
 * The editor, an input and a textarea all have their own undo, and theirs is better than this one
 * inside their own content. `use-shortcuts.ts` makes the same judgement for unmodified keys; this
 * is the same rule applied to a modified one, which that hook lets through on purpose.
 */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof globalThis.HTMLElement)) return false;
  const tag = target.tagName;
  return (
    tag === 'INPUT' ||
    tag === 'TEXTAREA' ||
    tag === 'SELECT' ||
    target.isContentEditable ||
    // The editor is an iframe-free mount, but its writing surface carries this class and is a
    // contenteditable, so the check above catches it. This is the belt to that braces.
    target.closest('.rn-prose') !== null
  );
}
