import type {
  GroupTemplate,
  GroupTemplateCreateRequestInput,
  GroupTemplateDeleteResponse,
  GroupTemplateUpdateRequest,
} from '@rosie-notes/schema';
import { shippedTemplates } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * The starting points a new group can be made from.
 *
 * Six ship with the app and every one of them is editable; anything else is one somebody made.
 * The list is a picker, not a collection — six to a dozen rows — so it is fetched whole and never
 * paged.
 *
 * ## Why there is a fallback at all
 *
 * `shippedTemplates()` is the same data the server would have overlaid the user's edits onto, so
 * a picker with no network still offers the six in the right order instead of nothing. It is
 * marked `local` rather than passed off as the server's answer: somebody who has edited Dreams
 * would otherwise be shown the shipped Dreams with no way to tell.
 */

export interface TemplateList {
  readonly items: readonly GroupTemplate[];
  readonly loading: boolean;
  /** True when these are the shipped values rather than the server's answer. */
  readonly local: boolean;
  reload(): Promise<void>;
  create(input: GroupTemplateCreateRequestInput): Promise<GroupTemplate>;
  update(id: string, patch: GroupTemplateUpdateRequest): Promise<GroupTemplate>;
  remove(id: string): Promise<GroupTemplateDeleteResponse>;
}

const CACHE_KEY = 'rosie-notes:templates';

function readCache(): GroupTemplate[] | null {
  try {
    const raw = globalThis.localStorage?.getItem(CACHE_KEY);
    if (raw === null || raw === undefined) return null;
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as GroupTemplate[]) : null;
  } catch {
    return null;
  }
}

function writeCache(items: readonly GroupTemplate[]): void {
  try {
    globalThis.localStorage?.setItem(CACHE_KEY, JSON.stringify(items));
  } catch {
    // Over quota, or storage disabled. The next cold start falls back to the shipped six.
  }
}

export function useTemplates(): TemplateList {
  const workspace = useWorkspace();
  const [items, setItems] = useState<readonly GroupTemplate[]>(
    () => readCache() ?? shippedTemplates(),
  );
  const [loading, setLoading] = useState(true);
  const [local, setLocal] = useState(true);

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const response = await workspace.client.groupTemplates.list();
      setItems(response.items);
      writeCache(response.items);
      setLocal(false);
    } catch {
      // Offline. Whatever was cached is a better answer than an empty picker, and the shipped
      // six are a better answer than the cache being empty too.
      setItems(readCache() ?? shippedTemplates());
      setLocal(true);
    } finally {
      setLoading(false);
    }
  }, [workspace]);

  useEffect(() => {
    void reload();
  }, [reload]);

  return useMemo<TemplateList>(
    () => ({
      items,
      loading,
      local,
      reload,
      async create(input) {
        const created = await workspace.client.groupTemplates.create(input);
        await reload();
        return created;
      },
      async update(id, patch) {
        const updated = await workspace.client.groupTemplates.update(id, patch);
        setItems((current) => {
          const next = current.map((template) => (template.id === id ? updated : template));
          writeCache(next);
          return next;
        });
        return updated;
      },
      async remove(id) {
        const outcome = await workspace.client.groupTemplates.remove(id);
        // Deleting one made here removes it; reverting a shipped one *replaces* it with the
        // shipped values. Only the server knows which row is left, so the list is refetched.
        await reload();
        return outcome;
      },
    }),
    [items, loading, local, reload, workspace],
  );
}
