import type {
  CollectionId,
  GroupSettings,
  GroupSettingsOverrides,
  GroupStructure,
} from '@rosie-notes/schema';
import {
  DEFAULT_GROUP_SETTINGS,
  EMPTY_GROUP_STRUCTURE,
  resolveGroupSettings,
  structureTally,
} from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useCreateStructure } from '../hooks/use-structure';
import { useTemplates } from '../hooks/use-templates';
import { useNavigate } from '../routing/use-route';
import { Breadcrumb, PageHeader } from './chrome';
import { GroupSettingsForm } from './group-settings-form';
import { Icon } from './icons';
import { settingsSentence } from './labels';
import { Btn, Callout, Glyph } from './primitives';
import type { OriginProps } from './settings-rows';
import { useToast } from './toasts';

/**
 * Adding a group: starting points, then a name, then **all** the settings underneath.
 *
 * The order matters and it is the whole argument of `GROUP-MODEL.md` §1 made visible. A starting
 * point is exactly that, **not a type** — picking one copies values in and is then forgotten,
 * which is why the settings are on the same screen underneath rather than behind a "customise"
 * button. If they were hidden, a preset would feel like a type you had committed to.
 *
 * The picker reads the **server's** starting points rather than the shipped constants, so a preset
 * the person has edited is the one they are offered — `NEXT-ROUND.md` §0a, and the whole reason
 * editing one is worth anything.
 *
 * **A subgroup does not ask.** It inherits its parent's settings and the picker never appears —
 * asking "what kind of group is this?" every time you add a folder inside a project is exactly
 * the friction the app is trying to remove.
 */

export interface NewGroupViewProps {
  readonly parentId: string | null;
}

export function NewGroupView({ parentId }: NewGroupViewProps): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const toast = useToast();
  const createStructure = useCreateStructure();
  const templates = useTemplates();

  const [templateId, setTemplateId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [overrides, setOverrides] = useState<Partial<GroupSettings>>({});
  const [creating, setCreating] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const nameRef = useRef<HTMLInputElement | null>(null);

  const parent = parentId === null ? undefined : tree.byId.get(parentId);

  // Focus the name once it exists. This screen is opened in order to fill it in, so landing the
  // caret there saves a tap — but only when the field is actually on screen, which is why it
  // waits for the preset step rather than being an attribute on the element.
  const ready = parentId !== null || templateId !== null;
  useEffect(() => {
    if (ready) nameRef.current?.focus();
  }, [ready]);

  const chosen = templates.items.find((template) => template.id === templateId);

  // A subgroup starts from its parent's *resolved* settings; a top-level group starts from the
  // starting point that was picked, or from the defaults for a custom one.
  const base: GroupSettings = useMemo(() => {
    if (parentId !== null) return tree.settingsOf(parentId).effective;
    return chosen?.settings ?? DEFAULT_GROUP_SETTINGS;
  }, [parentId, chosen, tree]);

  const settings: GroupSettings = useMemo(() => ({ ...base, ...overrides }), [base, overrides]);

  // A subgroup never carries a structure: it is a section inside something, and creating sections
  // inside sections is exactly the runaway a starting point must not have.
  const structure: GroupStructure =
    parentId === null ? (chosen?.structure ?? EMPTY_GROUP_STRUCTURE) : EMPTY_GROUP_STRUCTURE;
  const willCreate = structureTally(structure);

  const nameOf = useCallback(
    (id: string | null) => (id === null ? null : (tree.byId.get(id)?.name ?? null)),
    [tree],
  );

  /**
   * What the draft's inheritance marks say.
   *
   * A subgroup that has not been touched is genuinely inheriting from its parent, and saying so
   * before it exists is the honest thing — it is what tells somebody that changing the parent
   * later will move this too. Anything the person has changed on this screen is "Set here",
   * because that is exactly what will be stored.
   */
  const origin: OriginProps = useMemo(() => {
    const chain = parentId === null ? [] : tree.chain(parentId);
    const resolved = resolveGroupSettings([
      ...chain.map((group) => ({ id: group.id as string, settings: group.settings })),
      { id: '@draft', settings: overrides as GroupSettingsOverrides },
    ]);
    return { origins: resolved.origins, nameOf, groupId: '@draft' };
  }, [parentId, tree, overrides, nameOf]);

  async function create(): Promise<void> {
    const trimmed = name.trim();
    if (trimmed === '') return;
    setCreating(true);
    setFailure(null);
    try {
      const created = await tree.create({
        name: trimmed,
        // Never both: a subgroup starts from its parent, so it cannot also name a starting point.
        ...(parentId === null
          ? templateId === null
            ? {}
            : { templateId }
          : { parentId: parentId as CollectionId }),
        ...(Object.keys(overrides).length === 0
          ? {}
          : { settings: overrides as GroupSettingsOverrides }),
      });
      // The group exists from here on. A section that fails to be created is reported rather
      // than rolled back — see `useCreateStructure`.
      const built = await createStructure(created.id, structure);
      toast.show(
        built.failed > 0
          ? `Group created, with ${built.failed} of its sections missing.`
          : built.groups > 0
            ? `Group created, with ${built.groups} sections.`
            : 'Group created.',
        built.failed > 0 ? { tone: 'clay', icon: 'warn' } : undefined,
      );
      navigate({ name: 'group', groupId: created.id as string }, { replace: true });
    } catch (error) {
      setFailure(
        error instanceof Error
          ? error.message
          : 'The server did not accept it. Nothing has been created.',
      );
    } finally {
      setCreating(false);
    }
  }

  const chain = parentId === null ? [] : tree.chain(parentId);

  // Step one, top level only: which starting point? Until one is picked there is nothing to name.
  const needsPreset = parentId === null && templateId === null;

  return (
    <>
      <Breadcrumb
        chain={chain}
        leaf="New group"
        onHome={() => navigate({ name: 'home' })}
        onOpen={(ancestor) => navigate({ name: 'group', groupId: ancestor.id as string })}
      />
      <PageHeader
        actions={
          <Btn
            onClick={() =>
              navigate(parentId === null ? { name: 'home' } : { name: 'group', groupId: parentId })
            }
            tone="quiet"
          >
            Cancel
          </Btn>
        }
        sub={
          <span>
            {parent === undefined
              ? 'Pick a starting point, then adjust. A preset only fills the settings in — there is nothing to manage afterwards.'
              : `Settings are inherited from ${parent.name}. Change anything you like.`}
          </span>
        }
        title={parent === undefined ? 'New group' : `New group in ${parent.name}`}
      />

      {parentId === null && (
        <>
          <div className="cards" style={{ marginBottom: 12 }}>
            {templates.items.map((template) => (
              <button
                aria-pressed={templateId === template.id}
                className="card"
                key={template.id}
                onClick={() => setTemplateId(template.id)}
                type="button"
              >
                <div className="card-title">
                  <span className="rowicon">
                    <Glyph icon={template.icon} />
                  </span>
                  <span>{template.name}</span>
                </div>
                <div className="card-sub">{template.description ?? 'No description.'}</div>
              </button>
            ))}
          </div>
          <div style={{ marginBottom: 26 }}>
            <Btn onClick={() => navigate({ name: 'templates' })} small tone="quiet">
              Edit these starting points
            </Btn>
          </div>
        </>
      )}

      {!needsPreset && (
        <>
          <div className="eyebrow">Name</div>
          <input
            aria-label="Group name"
            className="field field-lg"
            onChange={(event) => setName(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && name.trim() !== '') void create();
            }}
            placeholder={parent === undefined ? 'Name this group' : 'docs'}
            ref={nameRef}
            value={name}
          />

          <p className="setrow-help" style={{ marginTop: 10 }}>
            {settingsSentence(settings, [])}
          </p>

          {willCreate.groups > 0 && (
            <Callout className="callout-spaced" icon="box" tone="quiet">
              <b>
                Creates {willCreate.groups} sections and {willCreate.notes} notes to start them off
              </b>{' '}
              — {structure.subgroups.map((subgroup) => subgroup.name).join(' · ')}. Rename or delete
              any of them afterwards; nothing here is linked back to the preset.
            </Callout>
          )}

          <GroupSettingsForm
            draft
            groupName={name}
            onChange={(patch) => setOverrides((current) => ({ ...current, ...patch }))}
            origin={origin}
            resolved={resolveGroupSettings([
              { id: '@draft', settings: overrides as GroupSettingsOverrides },
            ])}
            settings={settings}
          />

          {failure !== null && (
            <p className="banner banner-clay" role="alert">
              <Icon name="warn" />
              <span>{failure}</span>
            </p>
          )}

          <div className="stickyfoot">
            <Btn
              onClick={() =>
                navigate(
                  parentId === null ? { name: 'home' } : { name: 'group', groupId: parentId },
                )
              }
              tone="quiet"
            >
              Cancel
            </Btn>
            <Btn
              disabled={creating || name.trim() === ''}
              onClick={() => void create()}
              tone="primary"
            >
              {creating ? 'Creating…' : 'Create group'}
            </Btn>
          </div>
        </>
      )}
    </>
  );
}
