/**
 * Selecting several things at once — the model, with no React in it.
 *
 * Rose asked for this after a config import made ninety-two groups: *"needs to be a way to like
 * ctrl click a group/notes/ect to select them to like mass delete, mass move, mass ect of groups
 * then you can like drag to move all selected or like or right click"*. The clean-up button on
 * the config screen solves that one mess; this solves the class of it (`DECISIONS.md` D-44).
 *
 * Kept separate from the provider so the range arithmetic — the part with the off-by-one in it —
 * can be tested without mounting anything.
 */

export type SelectableKind = 'note' | 'group';

export interface SelectionItem {
  readonly kind: SelectableKind;
  readonly id: string;
}

/** Stable, and safe as a `Set` member: ids are UUIDv7 and contain no colon. */
export function selectionKey(item: SelectionItem): string {
  return `${item.kind}:${item.id}`;
}

export interface SelectionSnapshot {
  readonly keys: ReadonlySet<string>;
  /** The last item touched by a plain toggle. Shift-click measures from here. */
  readonly anchor: SelectionItem | null;
}

export const EMPTY_SELECTION: SelectionSnapshot = { keys: new Set(), anchor: null };

export function isSelected(snapshot: SelectionSnapshot, item: SelectionItem): boolean {
  return snapshot.keys.has(selectionKey(item));
}

export function toggle(snapshot: SelectionSnapshot, item: SelectionItem): SelectionSnapshot {
  const keys = new Set(snapshot.keys);
  const key = selectionKey(item);
  if (keys.has(key)) {
    keys.delete(key);
    // The anchor follows the last thing touched either way. Deselecting one row and then
    // shift-clicking another should measure from the row just touched, not from wherever the
    // anchor happened to be left three clicks ago.
    return { keys, anchor: item };
  }
  keys.add(key);
  return { keys, anchor: item };
}

/**
 * Shift-click: everything between the anchor and this row, in the order the list is drawn.
 *
 * `ordered` is the list's own rendering order rather than anything derived here, because that is
 * the only order the person can see. A list sorted by "least read first" has a range that has
 * nothing to do with ids or dates, and a range that does not match what is on screen is worse
 * than no range at all.
 *
 * With no anchor, or an anchor that has scrolled out of this list, this behaves as a plain
 * toggle — the honest fallback, since there is no second endpoint to measure to.
 */
export function extendTo(
  snapshot: SelectionSnapshot,
  item: SelectionItem,
  ordered: readonly SelectionItem[],
): SelectionSnapshot {
  const anchor = snapshot.anchor;
  if (anchor === null) return toggle(snapshot, item);

  const from = ordered.findIndex((entry) => selectionKey(entry) === selectionKey(anchor));
  const to = ordered.findIndex((entry) => selectionKey(entry) === selectionKey(item));
  if (from === -1 || to === -1) return toggle(snapshot, item);

  const keys = new Set(snapshot.keys);
  const [start, end] = from <= to ? [from, to] : [to, from];
  for (let index = start; index <= end; index += 1) {
    const entry = ordered[index];
    if (entry !== undefined) keys.add(selectionKey(entry));
  }
  // The anchor deliberately stays put. Dragging a range wider by shift-clicking further down is
  // the behaviour every file manager has, and moving the anchor to each new endpoint would
  // instead leave a trail of separate ranges behind.
  return { keys, anchor };
}

export function addAll(
  snapshot: SelectionSnapshot,
  items: readonly SelectionItem[],
): SelectionSnapshot {
  const keys = new Set(snapshot.keys);
  for (const item of items) keys.add(selectionKey(item));
  return { keys, anchor: items.at(-1) ?? snapshot.anchor };
}

export function removeAll(
  snapshot: SelectionSnapshot,
  items: readonly SelectionItem[],
): SelectionSnapshot {
  const keys = new Set(snapshot.keys);
  for (const item of items) keys.delete(selectionKey(item));
  return { keys, anchor: snapshot.anchor };
}

/** Split a selection back into the two kinds, since delete and move mean different calls. */
export function partition(snapshot: SelectionSnapshot): {
  readonly notes: readonly string[];
  readonly groups: readonly string[];
} {
  const notes: string[] = [];
  const groups: string[] = [];
  for (const key of snapshot.keys) {
    const separator = key.indexOf(':');
    const kind = key.slice(0, separator);
    const id = key.slice(separator + 1);
    if (kind === 'note') notes.push(id);
    else if (kind === 'group') groups.push(id);
  }
  return { notes, groups };
}

/**
 * What a click means, given which keys were held.
 *
 * The third case is the one worth writing down. Once anything is selected, a plain click
 * **selects** rather than opens — because on a phone there is no Ctrl to hold, and because a
 * plain click that navigated away would silently throw away a selection somebody spent thirty
 * taps building. Nothing is selected? Then a plain click opens, exactly as it always did, and a
 * person who never uses this feature never meets it.
 */
export type ClickIntent = 'open' | 'toggle' | 'range';

export function clickIntent(
  event: { readonly shiftKey: boolean; readonly ctrlKey: boolean; readonly metaKey: boolean },
  anySelected: boolean,
): ClickIntent {
  if (event.shiftKey) return 'range';
  if (event.ctrlKey || event.metaKey) return 'toggle';
  return anySelected ? 'toggle' : 'open';
}
