import type { CollectionId, Note } from '@rosie-notes/schema';
import { newId } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { type GroupTree, useGroups } from '../hooks/use-groups';
import { useNoteBody } from '../hooks/use-note-body';
import { useNoteQuery } from '../hooks/use-note-query';
import { useNavigate } from '../routing/use-route';
import { useWorkspace } from '../session/session-context';
import { Breadcrumb, PageHeader } from './chrome';
import { Icon } from './icons';
import { ago, numberedTitle, plural } from './labels';
import { Btn, Callout, Sheet } from './primitives';
import { SkeletonRows } from './rail';
import { EmptyState, ErrorState, NotFoundState, OfflineBanner } from './states';
import { useToast } from './toasts';

/**
 * A code project's prompts, read back rather than dug for.
 *
 * Rose: *"Per-project prompts page: scroll back, expand, merge-newer on duplicate upload."* The
 * prompts already exist as ordinary notes — `kind: 'prompt'` inside the project's group — this
 * screen just reads them the way they are actually used: newest first, because the current version
 * of something is read far more often than an old one; collapsed by default, because a prompt worth
 * keeping is usually long; copy-first, because a prompt's whole job is to be pasted somewhere else.
 *
 * `useNoteQuery` with `kind: 'prompt'` is the list; `useNoteBody` (see its own header — the doc and
 * the projection both have to be written, in that order) is every card's text, read and written
 * outside the editor exactly the way it was built for.
 *
 * ## "Everything under it"
 *
 * A project's prompts are not always all sitting directly in the project group — Rose's own note on
 * organising code projects mentions a `prompts/` subgroup alongside `docs/` and `repos/`. So the
 * query is not `collectionId: groupId`, it is "in this group or any of its descendants", built by
 * hand from {@link subtreeIds} the same way `GroupTree.tally` walks the tree for a count rather than
 * a list of ids.
 *
 * ## Merge-newer
 *
 * "Never silently overwrite" is the one rule this file cannot get wrong: the existing note's body is
 * somebody's work. So a title match never writes on its own — it always stops at {@link ComposerSheet}'s
 * merge step and asks, showing a line diff so "what changed" is an answer, not a claim.
 */

export interface PromptsViewProps {
  readonly groupId: string;
}

/** This group and everything nested under it, at every depth — same walk as `GroupTree.tally`,
 * but the ids themselves rather than a count, which is what a filter over the whole subtree needs.
 * Takes only `children` (not the whole `GroupTree`), so a test can hand it a bare tree shape. */
export function subtreeIds(tree: Pick<GroupTree, 'children'>, groupId: string): string[] {
  const ids = [groupId];
  const stack = [...tree.children(groupId)];
  while (stack.length > 0) {
    const next = stack.pop();
    if (next === undefined) continue;
    ids.push(next.id as string);
    stack.push(...tree.children(next.id as string));
  }
  return ids;
}

/** The descendant path under this screen's group, or `null` for a prompt sitting in it directly —
 * the breadcrumb above already says where the group itself is, so this only adds what is new. */
export function pathLabelFor(
  tree: Pick<GroupTree, 'chain'>,
  groupId: string,
  note: Note,
): string | null {
  const noteGroupId = (note.collectionIds[0] as string | undefined) ?? null;
  if (noteGroupId === null || noteGroupId === groupId) return null;
  const chain = tree.chain(noteGroupId);
  const cut = chain.findIndex((entry) => (entry.id as string) === groupId);
  const rest = cut === -1 ? chain : chain.slice(cut + 1);
  const label = rest.map((entry) => entry.name).join(' / ');
  return label === '' ? null : label;
}

/** Same one-liner as the private `countWords` in `notes-store.ts` and `import-plan.ts` — small
 * enough that copying it beats exporting one for a single extra caller. */
export function countWords(text: string): number {
  const trimmed = text.trim();
  return trimmed === '' ? 0 : trimmed.split(/\s+/u).length;
}

export function PromptsView({ groupId }: PromptsViewProps): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const [composer, setComposer] = useState<ComposerMode | null>(null);

  const group = tree.byId.get(groupId);
  const chain = tree.chain(groupId);
  const ids = useMemo(() => subtreeIds(tree, groupId), [tree, groupId]);

  // `kind` is the shorthand; the subtree is a hand-built `or` of `collection` nodes because there
  // is no shorthand for "this group or any descendant". Both are ANDed by the server the same way
  // `collectionId` and `kind` already are (`buildListFilter`), and evaluated the same way offline
  // (`filters/evaluate.ts`), so this behaves identically online and from the cache.
  const query = useMemo(
    () => ({
      kind: 'prompt' as const,
      filter: {
        type: 'or' as const,
        filters: ids.map((id) => ({
          type: 'collection' as const,
          collectionId: id as CollectionId,
        })),
      },
      limit: 200,
    }),
    [ids],
  );
  const notes = useNoteQuery(query);

  if (group === undefined) {
    if (tree.loading) {
      return <SkeletonRows count={3} />;
    }
    return <NotFoundState onBack={() => navigate({ name: 'home' })} what="That group" />;
  }

  return (
    <>
      <Breadcrumb
        chain={chain}
        leaf="Prompts"
        onHome={() => navigate({ name: 'home' })}
        onOpen={(ancestor) => navigate({ name: 'group', groupId: ancestor.id as string })}
      />
      <PageHeader
        actions={
          <Btn icon="plus" onClick={() => setComposer({ kind: 'new' })} tone="primary">
            Add or update
          </Btn>
        }
        sub={
          <span>
            {plural(notes.notes.length, 'prompt')} in {group.name} and everything under it, newest
            first.
          </span>
        }
        title="Prompts"
      />

      {notes.stale && <OfflineBanner what="prompts" />}

      {notes.loading && notes.notes.length === 0 ? (
        <SkeletonRows count={3} />
      ) : notes.error !== null ? (
        <ErrorState
          body="The server did not answer and this device has nothing cached for this group."
          onRetry={notes.reload}
          title="These prompts could not be loaded"
        />
      ) : notes.notes.length === 0 ? (
        <EmptyState
          action={
            <Btn icon="plus" large onClick={() => setComposer({ kind: 'new' })} tone="primary">
              Add a prompt
            </Btn>
          }
          body="Paste or drop the first one you hand to an agent for this project."
          title="No prompts here yet"
        />
      ) : (
        <ul aria-label="Prompts" style={{ display: 'grid', gap: 12 }}>
          {notes.notes.map((note) => (
            <PromptCard
              key={note.id}
              note={note}
              onUpdate={(target) => setComposer({ kind: 'update', existing: target })}
              pathLabel={pathLabelFor(tree, groupId, note)}
            />
          ))}
        </ul>
      )}

      {notes.hasMore && (
        <div className="undertext">
          <Btn onClick={notes.loadMore} small tone="quiet">
            Show more
          </Btn>
        </div>
      )}

      {composer !== null && (
        <ComposerSheet
          groupId={groupId}
          mode={composer}
          onClose={() => setComposer(null)}
          onSaved={notes.reload}
          prompts={notes.notes}
        />
      )}
    </>
  );
}

// -------------------------------------------------------------------------------------------
// One prompt
// -------------------------------------------------------------------------------------------

/** Collapsed to a fixed number of lines regardless of how the text is paragraphed — a line clamp,
 * not a character cut, which is what keeps the collapsed height predictable for a prompt that is
 * one giant paragraph and one that is fifty short ones alike. */
function bodyStyle(expanded: boolean): React.CSSProperties {
  const base: React.CSSProperties = {
    marginTop: 10,
    fontFamily: 'var(--f-mono)',
    fontSize: 13,
    lineHeight: 1.6,
    color: 'var(--text-2)',
    whiteSpace: 'pre-wrap',
    overflowWrap: 'anywhere',
  };
  if (expanded) return base;
  return {
    ...base,
    display: '-webkit-box',
    WebkitBoxOrient: 'vertical',
    WebkitLineClamp: 5,
    overflow: 'hidden',
  };
}

function PromptCard({
  note,
  pathLabel,
  onUpdate,
}: {
  readonly note: Note;
  readonly pathLabel: string | null;
  readonly onUpdate: (note: Note) => void;
}): React.JSX.Element {
  const body = useNoteBody(note.id);
  const [expanded, setExpanded] = useState(false);
  const toast = useToast();

  async function copy(): Promise<void> {
    try {
      await globalThis.navigator.clipboard.writeText(body.text);
      toast.show('Copied.', { icon: 'doc' });
    } catch {
      // No clipboard permission, or an insecure origin — the same fallback `share-dialog.tsx`
      // leans on: the text is already on screen and selectable, which is what every browser
      // still allows.
    }
  }

  return (
    <li className="card" style={{ padding: 14 }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="card-title">
            <span className="rowicon">
              <Icon name="term" />
            </span>
            <span>{note.title === '' ? 'Untitled' : note.title}</span>
          </div>
          <p className="setrow-help" style={{ marginTop: 2 }}>
            {plural(note.wordCount, 'word')} · changed {ago(note.updatedAt)}
            {pathLabel !== null && ` · ${pathLabel}`}
          </p>
        </div>
        <div style={{ display: 'flex', flexShrink: 0, gap: 6 }}>
          {/* The most-pressed button on this screen — a prompt exists to be pasted somewhere
              else, so copying it is one tap regardless of whether the card is expanded. */}
          <Btn
            disabled={body.loading || body.text === ''}
            icon="doc"
            onClick={() => void copy()}
            small
            title="Copy the whole prompt"
            tone="ghost"
          >
            Copy
          </Btn>
          <Btn
            icon="edit"
            onClick={() => onUpdate(note)}
            small
            title="Paste a new version"
            tone="ghost"
          >
            Update
          </Btn>
        </div>
      </div>

      {body.loading ? (
        <p className="setrow-help" style={{ marginTop: 10 }}>
          Reading…
        </p>
      ) : (
        <>
          <div style={bodyStyle(expanded)}>
            {body.text === '' ? 'Nothing written in this one yet.' : body.text}
          </div>
          <button
            aria-expanded={expanded}
            className="btn btn-sm btn-quiet"
            onClick={() => setExpanded((value) => !value)}
            style={{ marginTop: 8 }}
            type="button"
          >
            <span
              style={{
                display: 'inline-flex',
                transform: expanded ? 'rotate(180deg)' : undefined,
              }}
            >
              <Icon name="chevd" />
            </span>
            {expanded ? 'Collapse' : 'Expand'}
          </button>
        </>
      )}
    </li>
  );
}

// -------------------------------------------------------------------------------------------
// Add or update
// -------------------------------------------------------------------------------------------

/** A blank prompt, or a known-in-advance target — the per-card "Update" button already knows which
 * note it means, so it skips straight past the title-matching `'new'` mode does. */
export type ComposerMode =
  | { readonly kind: 'new' }
  | { readonly kind: 'update'; readonly existing: Note };

interface ComposerSheetProps {
  readonly groupId: string;
  readonly mode: ComposerMode;
  /** Every prompt already loaded on this screen — the whole set a title is checked against, and
   * what `numberedTitle` avoids colliding with when saving alongside. */
  readonly prompts: readonly Note[];
  readonly onClose: () => void;
  readonly onSaved: () => void;
}

function ComposerSheet({
  groupId,
  mode,
  prompts,
  onClose,
  onSaved,
}: ComposerSheetProps): React.JSX.Element {
  const workspace = useWorkspace();
  const toast = useToast();

  const [title, setTitle] = useState(mode.kind === 'update' ? mode.existing.title : '');
  const [text, setText] = useState('');
  const [dragOver, setDragOver] = useState(false);
  const [mergeTarget, setMergeTarget] = useState<Note | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Minted the moment the sheet opens rather than when a create actually happens, so a `useNoteBody`
  // bound to it below is already primed with the right id by the time any button that needs it is
  // clickable — no effect has to wait for state to "catch up" with an id chosen mid-handler.
  const [freshId] = useState(() => newId<'note'>(workspace.adapter.clock()));
  const freshBody = useNoteBody(freshId);
  // Bound to whichever note this session turns out to be comparing against — `null` until a
  // duplicate title is found (or the caller already named one via `mode: 'update'`).
  const existingBody = useNoteBody(mergeTarget?.id ?? null);

  const merging = mergeTarget !== null;

  async function readFile(file: File): Promise<void> {
    const content = await file.text();
    setText(content);
    if (mode.kind === 'new' && title.trim() === '') {
      setTitle(file.name.replace(/\.(md|txt)$/iu, ''));
    }
  }

  function onDrop(event: React.DragEvent<HTMLDivElement>): void {
    event.preventDefault();
    setDragOver(false);
    const file = event.dataTransfer.files[0];
    if (file !== undefined) void readFile(file);
  }

  function onFileChosen(event: React.ChangeEvent<HTMLInputElement>): void {
    const file = event.target.files?.[0];
    if (file !== undefined) void readFile(file);
    // Otherwise choosing the same file a second time would not fire another change event.
    event.target.value = '';
  }

  async function createFresh(finalTitle: string, announce: string): Promise<void> {
    setSaving(true);
    setError(null);
    try {
      await workspace.writes.submit({
        kind: 'create',
        noteId: freshId,
        input: {
          id: freshId,
          title: finalTitle,
          kind: 'prompt',
          collectionIds: [groupId as CollectionId],
        },
      });
      await freshBody.write(text);
      toast.show(announce, { icon: 'check' });
      onSaved();
      onClose();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not save that.');
    } finally {
      setSaving(false);
    }
  }

  async function onSubmit(): Promise<void> {
    const trimmedTitle = title.trim();
    if (trimmedTitle === '' || text.trim() === '') return;

    if (mode.kind === 'update') {
      setMergeTarget(mode.existing);
      return;
    }
    const duplicate = prompts.find(
      (candidate) =>
        candidate.title.trim().toLocaleLowerCase() === trimmedTitle.toLocaleLowerCase(),
    );
    if (duplicate !== undefined) {
      setMergeTarget(duplicate);
      return;
    }
    await createFresh(trimmedTitle, `Added "${trimmedTitle}".`);
  }

  // Named `overwriteWithNew`, not `useNew` — a plain function named `use*` reads as a hook to
  // both Biome's and React's own eslint rule, which is exactly backwards for something that is
  // not one and calls none conditionally.
  async function overwriteWithNew(): Promise<void> {
    if (mergeTarget === null) return;
    setSaving(true);
    setError(null);
    try {
      await existingBody.write(text);
      toast.show(`Updated "${mergeTarget.title}".`, { icon: 'check' });
      onSaved();
      onClose();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not save that.');
    } finally {
      setSaving(false);
    }
  }

  function keepOld(): void {
    toast.show('Kept the version already here.');
    onClose();
  }

  async function saveAlongside(): Promise<void> {
    if (mergeTarget === null) return;
    const distinct = numberedTitle(
      mergeTarget.title,
      prompts.map((candidate) => candidate.title),
    );
    await createFresh(distinct, `Saved alongside as "${distinct}".`);
  }

  return (
    <Sheet
      footer={
        merging ? (
          <>
            <Btn disabled={saving} onClick={keepOld} tone="quiet">
              Keep the old one
            </Btn>
            <Btn
              disabled={saving || existingBody.loading}
              onClick={() => void saveAlongside()}
              tone="primary"
            >
              Save alongside
            </Btn>
            <Btn
              disabled={saving || existingBody.loading}
              onClick={() => void overwriteWithNew()}
              tone="danger"
            >
              Use the new one
            </Btn>
          </>
        ) : (
          <Btn
            disabled={saving || title.trim() === '' || text.trim() === ''}
            onClick={() => void onSubmit()}
            tone="primary"
          >
            {saving ? 'Saving…' : mode.kind === 'update' ? 'Compare' : 'Save'}
          </Btn>
        )
      }
      onClose={onClose}
      sub={
        merging
          ? 'Never overwritten without asking — here is what is different.'
          : mode.kind === 'update'
            ? 'Paste or drop the new version.'
            : 'Paste text, or drop a .md or .txt file.'
      }
      title={
        merging
          ? `"${mergeTarget.title}" already exists`
          : mode.kind === 'update'
            ? `Update "${mode.existing.title}"`
            : 'Add a prompt'
      }
    >
      {merging ? (
        existingBody.loading ? (
          <p className="setrow-help">Reading the version already here…</p>
        ) : (
          <div style={{ display: 'grid', gap: 12 }}>
            <Callout icon="warn" tone="quiet">
              Last changed {ago(mergeTarget.updatedAt)}, {plural(mergeTarget.wordCount, 'word')}.
              The new text has {plural(countWords(text), 'word')}.
            </Callout>
            <DiffView newText={text} oldText={existingBody.text} />
            {error !== null && (
              <Callout icon="warn" tone="clay">
                {error}
              </Callout>
            )}
          </div>
        )
      ) : (
        <div style={{ display: 'grid', gap: 12 }}>
          {mode.kind === 'new' && (
            <label className="setrow setrow-stack">
              <span className="setrow-label">Title</span>
              <input
                className="field"
                onChange={(event) => setTitle(event.target.value)}
                placeholder="e.g. Orchestrator prompt"
                value={title}
              />
            </label>
          )}
          {/* biome-ignore lint/a11y/noStaticElementInteractions: a drop target, not a control — the
              file input beside it is the keyboard- and screen-reader-reachable way in */}
          <div
            onDragLeave={() => setDragOver(false)}
            onDragOver={(event) => {
              event.preventDefault();
              setDragOver(true);
            }}
            onDrop={onDrop}
            style={{
              border: `1px dashed var(${dragOver ? '--accent-line' : '--line-soft'})`,
              borderRadius: 'var(--r2)',
              padding: 14,
              textAlign: 'center',
            }}
          >
            <p className="setrow-help">Drop a .md or .txt file here, or paste below.</p>
            <input accept=".md,.txt,text/markdown,text/plain" onChange={onFileChosen} type="file" />
          </div>
          <label className="setrow setrow-stack">
            <span className="setrow-label">Prompt text</span>
            <textarea
              className="field field-mono"
              onChange={(event) => setText(event.target.value)}
              rows={10}
              value={text}
            />
          </label>
          {error !== null && (
            <Callout icon="warn" tone="clay">
              {error}
            </Callout>
          )}
        </div>
      )}
    </Sheet>
  );
}

// -------------------------------------------------------------------------------------------
// The diff
// -------------------------------------------------------------------------------------------

export interface DiffLine {
  readonly text: string;
  readonly kind: 'same' | 'added' | 'removed';
}

/** Above this many combined lines an O(n·m) table is not worth building — the word-count callout
 * above already carries the comparison. Real prompts are pages, not codebases, so this is generous. */
const MAX_DIFF_LINES = 2000;

/**
 * A line-level diff via the textbook LCS table, read backwards.
 *
 * No dependency pulled in for this: `diff`/`jsdiff` would be the normal reach, but this screen is
 * the only caller, the input is prompt-sized text rather than a whole file, and forty lines of
 * well-understood DP is cheaper to review than a new package for one call site.
 */
export function diffLines(oldText: string, newText: string): DiffLine[] | null {
  const a = oldText.split('\n');
  const b = newText.split('\n');
  if (a.length + b.length > MAX_DIFF_LINES) return null;

  const n = a.length;
  const m = b.length;
  const lcs: number[][] = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      const row = lcs[i] as number[];
      const nextRow = lcs[i + 1] as number[];
      row[j] =
        a[i] === b[j]
          ? (nextRow[j + 1] as number) + 1
          : Math.max(nextRow[j] as number, row[j + 1] as number);
    }
  }

  const out: DiffLine[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      out.push({ text: a[i] as string, kind: 'same' });
      i += 1;
      j += 1;
    } else if (((lcs[i + 1] as number[])[j] as number) >= ((lcs[i] as number[])[j + 1] as number)) {
      out.push({ text: a[i] as string, kind: 'removed' });
      i += 1;
    } else {
      out.push({ text: b[j] as string, kind: 'added' });
      j += 1;
    }
  }
  while (i < n) {
    out.push({ text: a[i] as string, kind: 'removed' });
    i += 1;
  }
  while (j < m) {
    out.push({ text: b[j] as string, kind: 'added' });
    j += 1;
  }
  return out;
}

function DiffView({
  oldText,
  newText,
}: {
  readonly oldText: string;
  readonly newText: string;
}): React.JSX.Element {
  const diff = useMemo(() => diffLines(oldText, newText), [oldText, newText]);

  if (diff === null) {
    return (
      <p className="setrow-help">
        Too long to line up here — the word counts above are the comparison.
      </p>
    );
  }
  const changed = diff.filter((line) => line.kind !== 'same');
  if (changed.length === 0) {
    return <p className="setrow-help">Same text, word for word.</p>;
  }

  return (
    <div
      style={{
        maxHeight: '40vh',
        overflowY: 'auto',
        border: '1px solid var(--line-soft)',
        borderRadius: 'var(--r2)',
        padding: 8,
        display: 'grid',
        gap: 2,
      }}
    >
      {changed.map((line, index) => (
        <div
          // biome-ignore lint/suspicious/noArrayIndexKey: diff lines have no identity of their own
          key={index}
          style={{
            whiteSpace: 'pre-wrap',
            overflowWrap: 'anywhere',
            fontFamily: 'var(--f-mono)',
            fontSize: 12.5,
            lineHeight: 1.5,
            padding: '2px 6px',
            borderRadius: 4,
            borderLeft: `3px solid var(${line.kind === 'added' ? '--sage' : '--clay'})`,
            background: line.kind === 'added' ? 'var(--surface-2)' : 'var(--clay-soft)',
            color: line.kind === 'added' ? 'var(--sage)' : 'var(--clay)',
          }}
        >
          {line.kind === 'added' ? '+ ' : '− '}
          {line.text === '' ? ' ' : line.text}
        </div>
      ))}
    </div>
  );
}
