import type { GroupSettings, GroupStructure } from '@rosie-notes/schema';
import { resolveGroupSettings, structureTally } from '@rosie-notes/schema';
import { useState } from 'react';
import { useTemplates } from '../hooks/use-templates';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { GroupSettingsForm } from './group-settings-form';
import { settingsSentence } from './labels';
import { Btn, Callout, SetGroup, SetRow, SetTextRow, Sheet } from './primitives';
import type { OriginProps } from './settings-rows';
import { LoadingState, NotFoundState } from './states';
import { useToast } from './toasts';

/**
 * One starting point, edited.
 *
 * The same settings form as a group's own screen, on purpose: "what a new group starts as" and
 * "what this group is" have to look identical or a starting point becomes a second thing to
 * learn. What differs is the cascade — a starting point has no parent and no ancestors, so every
 * value is **set here** and the inheritance marks say so honestly rather than being hidden.
 *
 * A shipped starting point is **reverted**, never deleted: the six are always in the picker, and
 * "put it back how it came" is a thing people want after experimenting. One made here is deleted
 * outright. The screen says which of the two the button will do.
 */

export interface TemplateViewProps {
  readonly templateId: string;
}

export function TemplateView({ templateId }: TemplateViewProps): React.JSX.Element {
  const templates = useTemplates();
  const navigate = useNavigate();
  const toast = useToast();
  const [name, setName] = useState<string | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);

  const template = templates.items.find((entry) => entry.id === templateId);

  if (template === undefined) {
    if (templates.loading) return <LoadingState label="Opening the starting point…" />;
    return (
      <NotFoundState onBack={() => navigate({ name: 'templates' })} what="That starting point" />
    );
  }

  async function patch(next: Partial<GroupSettings>): Promise<void> {
    try {
      await templates.update(templateId, { settings: next });
    } catch {
      toast.show('That change did not reach the server.', { tone: 'clay', icon: 'warn' });
    }
  }

  async function setStructure(structure: GroupStructure): Promise<void> {
    try {
      await templates.update(templateId, { structure });
    } catch {
      toast.show('That change did not reach the server.', { tone: 'clay', icon: 'warn' });
    }
  }

  async function rename(): Promise<void> {
    const trimmed = (name ?? '').trim();
    if (trimmed === '' || trimmed === template?.name) {
      if (name !== null) setName(null);
      return;
    }
    try {
      await templates.update(templateId, { name: trimmed });
      setName(null);
      toast.show('Renamed.');
    } catch {
      toast.show('That rename did not reach the server.', { tone: 'clay', icon: 'warn' });
    }
  }

  // No parent and no ancestors: every value on a starting point is set on it. Passing the draft
  // through the same resolver the group screens use keeps the marks truthful rather than absent.
  const origin: OriginProps = {
    origins: resolveGroupSettings([{ id: templateId, settings: template.settings }]).origins,
    nameOf: () => null,
    groupId: templateId,
  };

  const tally = structureTally(template.structure);

  return (
    <>
      <PageHeader
        actions={
          <Btn
            onClick={() => {
              void rename().then(() => navigate({ name: 'templates' }));
            }}
            tone="ghost"
          >
            Done
          </Btn>
        }
        icon={template.icon}
        sub={<span>{settingsSentence(template.settings, [])}</span>}
        title={template.name}
      />

      <Callout className="callout-spaced" icon="eye" tone="quiet">
        Changes here apply to the <b>next</b> group you make from this. Groups you have already made
        keep exactly the settings they were created with.
      </Callout>

      <SetGroup title="Identity">
        <SetTextRow
          help="What this starting point is called in the picker."
          label="Name"
          onChange={setName}
          onCommit={() => void rename()}
          value={name ?? template.name}
        />
      </SetGroup>

      <StructureEditor
        onChange={(structure) => void setStructure(structure)}
        structure={template.structure}
      />

      <GroupSettingsForm
        onChange={(next) => void patch(next)}
        origin={origin}
        resolved={resolveGroupSettings([{ id: templateId, settings: template.settings }])}
        settings={template.settings}
      />

      <SetGroup title="This starting point">
        <SetRow
          danger
          help={
            template.preset === null
              ? 'Removes it from the picker. Groups made from it are untouched.'
              : 'Puts it back to the version the app ships with. Groups made from it are untouched.'
          }
          label={template.preset === null ? 'Delete it' : 'Revert to the shipped version'}
          onClick={() => setConfirmReset(true)}
          value={<span />}
        />
      </SetGroup>

      {confirmReset && (
        <Sheet
          onClose={() => setConfirmReset(false)}
          sub={
            template.preset === null
              ? 'The groups you made from it are not affected in any way.'
              : 'It stays in the picker — only your changes to it go. The groups you made from it are not affected.'
          }
          title={template.preset === null ? `Delete ${template.name}?` : `Revert ${template.name}?`}
        >
          <p className="setrow-help">
            {tally.groups > 0
              ? `It currently creates ${tally.groups} sections and ${tally.notes} notes.`
              : 'It currently creates no sections.'}
          </p>
          <div className="form__actions" style={{ marginTop: 16 }}>
            <Btn onClick={() => setConfirmReset(false)} tone="ghost">
              Keep it
            </Btn>
            <Btn
              onClick={() => {
                void templates.remove(templateId).then((outcome) => {
                  toast.show(outcome.reverted ? 'Back to the shipped version.' : 'Deleted.');
                  navigate({ name: 'templates' }, { replace: true });
                });
              }}
              tone="danger"
            >
              {template.preset === null ? 'Delete it' : 'Revert it'}
            </Btn>
          </div>
        </Sheet>
      )}
    </>
  );
}

/**
 * The sections and starter notes a group from this begins with.
 *
 * Deliberately plain: a list of names with a remove button and a field to add another. The thing
 * that makes it useful is the note under each section — *"a section you can open and immediately
 * write in"* is the whole shape `NEXT-ROUND.md` §1 settled on, so a section with no starter note
 * says so rather than looking finished.
 */
function StructureEditor({
  structure,
  onChange,
}: {
  readonly structure: GroupStructure;
  readonly onChange: (next: GroupStructure) => void;
}): React.JSX.Element {
  const [draft, setDraft] = useState('');
  const [open, setOpen] = useState<string | null>(null);

  function addSection(): void {
    const name = draft.trim();
    if (name === '' || structure.subgroups.some((entry) => entry.name === name)) {
      setDraft('');
      return;
    }
    onChange({ ...structure, subgroups: [...structure.subgroups, { name, notes: [] }] });
    setDraft('');
  }

  function removeSection(name: string): void {
    onChange({
      ...structure,
      subgroups: structure.subgroups.filter((entry) => entry.name !== name),
    });
  }

  function setNoteTitle(section: string, index: number, title: string): void {
    onChange({
      ...structure,
      subgroups: structure.subgroups.map((entry) =>
        entry.name === section
          ? {
              ...entry,
              notes: entry.notes.map((note, at) => (at === index ? { ...note, title } : note)),
            }
          : entry,
      ),
    });
  }

  function addNote(section: string): void {
    onChange({
      ...structure,
      subgroups: structure.subgroups.map((entry) =>
        entry.name === section
          ? { ...entry, notes: [...entry.notes, { title: 'Notes', kind: 'doc', body: '' }] }
          : entry,
      ),
    });
  }

  function removeNote(section: string, index: number): void {
    onChange({
      ...structure,
      subgroups: structure.subgroups.map((entry) =>
        entry.name === section
          ? { ...entry, notes: entry.notes.filter((_note, at) => at !== index) }
          : entry,
      ),
    });
  }

  return (
    <SetGroup note="Created once, then yours" title="What it creates">
      {structure.subgroups.length === 0 && (
        <div className="setrow">
          <span className="setrow-main">
            <span className="setrow-help">
              Nothing — a group from this starts empty. Add a section to change that.
            </span>
          </span>
        </div>
      )}

      {structure.subgroups.map((section) => (
        <div key={section.name}>
          <div className="setrow">
            <button
              aria-expanded={open === section.name}
              className="setrow-main"
              onClick={() => setOpen((current) => (current === section.name ? null : section.name))}
              style={{ textAlign: 'left', background: 'none', border: 0, padding: 0 }}
              type="button"
            >
              <span className="setrow-label">{section.name}</span>
              <span className="setrow-help">
                {section.notes.length === 0
                  ? 'No note to start it — it will be an empty section.'
                  : section.notes.map((note) => note.title).join(' · ')}
              </span>
            </button>
            <Btn onClick={() => removeSection(section.name)} small tone="quiet">
              Remove
            </Btn>
          </div>

          {open === section.name && (
            <div className="setopts stack">
              {section.notes.map((note, index) => (
                // Keyed by position rather than by title on purpose: the title is what is being
                // typed into, and a key that changed with it would remount the field on every
                // keystroke and take the caret with it.
                <div
                  // biome-ignore lint/suspicious/noArrayIndexKey: the title is the editable value
                  key={`${section.name}-${index}`}
                  style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
                >
                  <input
                    aria-label={`Starter note in ${section.name}`}
                    className="field"
                    onChange={(event) => setNoteTitle(section.name, index, event.target.value)}
                    style={{ width: 220, flex: 'none' }}
                    value={note.title}
                  />
                  <Btn onClick={() => removeNote(section.name, index)} small tone="quiet">
                    Remove note
                  </Btn>
                </div>
              ))}
              <div>
                <Btn onClick={() => addNote(section.name)} small>
                  Add a starter note
                </Btn>
              </div>
            </div>
          )}
        </div>
      ))}

      <div className="setrow setrow-stack">
        <span className="setrow-label">Add a section</span>
        <span className="setrow-help spaced">
          Each one becomes a subgroup, and a folder on disk if the group keeps files.
        </span>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <input
            aria-label="New section"
            className="field"
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                addSection();
              }
            }}
            placeholder="docs"
            style={{ width: 220, flex: 'none' }}
            value={draft}
          />
          <Btn onClick={addSection} small>
            Add section
          </Btn>
        </div>
      </div>
    </SetGroup>
  );
}
