/**
 * Turning a pile of files into a plan for notes and subgroups.
 *
 * Two of Rose's asks need the same machine:
 *
 * - **T-35** — have rosie-notes itself be the first real code project in the app, so it can be
 *   shaped by being used. Its docs, plans and prompts are already markdown files on disk.
 * - **T-39** — bring in Rose's existing writing, the ADHD notes among it. The open question there
 *   was *what format is it in*, and this answers the version of that question that can be
 *   answered without asking: **text files, in folders**.
 *
 * The plan is computed first and shown before anything is created — the same rule the config
 * import follows (`DECISIONS.md` D-33): deriving is a convenience, never an authority.
 *
 * Nothing here touches the network or the DOM, so the awkward parts — a title, a folder trail, a
 * name that collides — are tested without a browser.
 */

export interface ImportFile {
  /** Path as the browser reported it: `docs/handoff/STATE.md`, or just `STATE.md`. */
  readonly path: string;
  readonly text: string;
}

export interface PlannedNote {
  readonly title: string;
  readonly markdown: string;
  /** Subgroups to create, outermost first. Empty means straight into the target group. */
  readonly folders: readonly string[];
  readonly sourcePath: string;
  readonly words: number;
}

export interface ImportPlan {
  readonly notes: readonly PlannedNote[];
  /** Every folder that will be created, as a trail. Parents before children. */
  readonly folders: readonly (readonly string[])[];
  /** Files left out, and why — always shown, never silently dropped. */
  readonly skipped: readonly { readonly path: string; readonly why: string }[];
}

/** What is read as text. Anything else is skipped **and reported**, never quietly ignored. */
const TEXT_EXTENSIONS = new Set([
  'md',
  'markdown',
  'txt',
  'text',
  'rst',
  'org',
  'adoc',
  'log',
  'json',
  'yml',
  'yaml',
  'toml',
  'csv',
]);

/** Files that are somebody's tooling rather than their writing. */
const IGNORED_NAMES = new Set(['.ds_store', 'thumbs.db', 'desktop.ini', '.gitkeep']);
const IGNORED_FOLDERS = new Set(['node_modules', '.git', 'dist', 'build', '.next', '__pycache__']);

/** 2 MB. Past that it is a database or a log, not a note somebody wants to read on a phone. */
export const MAX_IMPORT_FILE_BYTES = 2_000_000;

function extensionOf(path: string): string {
  const name = path.split('/').at(-1) ?? '';
  const dot = name.lastIndexOf('.');
  return dot === -1 ? '' : name.slice(dot + 1).toLowerCase();
}

/**
 * A title for the note.
 *
 * The first markdown heading wins, because that is what the document calls itself; the filename is
 * the fallback, tidied. `README.md` in a folder called `handoff` becoming a note called "README"
 * is worse than useless, so a heading is always preferred where there is one.
 */
export function titleFor(path: string, text: string): string {
  // Horizontal whitespace only, deliberately. `\s` matches newlines, so a bare `#` on a line of
  // its own ran on and took the paragraph below it as the title — which is what it did, and what
  // the test above now stops.
  const heading = /^[ \t]*#[ \t]+(.+?)[ \t]*$/mu.exec(text.slice(0, 4000));
  if (heading?.[1] !== undefined && heading[1].trim() !== '') {
    return heading[1].trim().slice(0, 200);
  }
  const name = (path.split('/').at(-1) ?? path).replace(/\.[^.]+$/u, '');
  const tidied = name.replaceAll(/[_-]+/gu, ' ').trim();
  return (tidied === '' ? 'Untitled' : tidied).slice(0, 200);
}

function countWords(text: string): number {
  const trimmed = text.trim();
  return trimmed === '' ? 0 : trimmed.split(/\s+/u).length;
}

/**
 * Work out what a set of files would become.
 *
 * `flatten` collapses the folder trail so everything lands in one group — the right choice for a
 * dozen loose files, and the wrong one for a whole `docs/` tree, which is why it is a switch and
 * not a guess.
 */
export function planImport(
  files: readonly ImportFile[],
  options: { readonly flatten?: boolean } = {},
): ImportPlan {
  const flatten = options.flatten ?? false;
  const notes: PlannedNote[] = [];
  const skipped: { path: string; why: string }[] = [];
  const folderKeys = new Set<string>();
  const folders: string[][] = [];

  for (const file of files) {
    const parts = file.path.split('/').filter((part) => part !== '' && part !== '.');
    const name = (parts.at(-1) ?? '').toLowerCase();
    const trail = parts.slice(0, -1);

    if (IGNORED_NAMES.has(name) || name.startsWith('.')) {
      skipped.push({ path: file.path, why: 'a hidden or system file' });
      continue;
    }
    if (trail.some((part) => IGNORED_FOLDERS.has(part.toLowerCase()))) {
      skipped.push({ path: file.path, why: 'inside a build or dependency folder' });
      continue;
    }
    const extension = extensionOf(file.path);
    if (!TEXT_EXTENSIONS.has(extension)) {
      skipped.push({
        path: file.path,
        why: extension === '' ? 'no file extension to read it by' : `not text (.${extension})`,
      });
      continue;
    }
    if (file.text.length > MAX_IMPORT_FILE_BYTES) {
      skipped.push({ path: file.path, why: 'over 2 MB' });
      continue;
    }
    if (file.text.trim() === '') {
      skipped.push({ path: file.path, why: 'empty' });
      continue;
    }

    const noteFolders = flatten ? [] : trail;
    for (let depth = 1; depth <= noteFolders.length; depth += 1) {
      const partial = noteFolders.slice(0, depth);
      const key = partial.join('/');
      if (!folderKeys.has(key)) {
        folderKeys.add(key);
        folders.push(partial);
      }
    }

    notes.push({
      title: titleFor(file.path, file.text),
      markdown: file.text,
      folders: noteFolders,
      sourcePath: file.path,
      words: countWords(file.text),
    });
  }

  // Parents before children, so a create loop can rely on its parent existing. Sorting by depth
  // then by name also makes the preview read like the folder tree it came from.
  folders.sort(
    (left, right) => left.length - right.length || left.join('/').localeCompare(right.join('/')),
  );

  return { notes, folders, skipped };
}

/** Totals for the preview line. A count is what makes "is this the right folder?" answerable. */
export function planSummary(plan: ImportPlan): string {
  const words = plan.notes.reduce((running, note) => running + note.words, 0);
  const parts = [
    `${plan.notes.length} ${plan.notes.length === 1 ? 'note' : 'notes'}`,
    plan.folders.length === 0
      ? null
      : `${plan.folders.length} ${plan.folders.length === 1 ? 'subgroup' : 'subgroups'}`,
    `${words.toLocaleString('en-GB')} words`,
  ].filter((part): part is string => part !== null);
  return parts.join(' · ');
}
