import { useEffect, useRef, useState } from 'react';

/**
 * A heading you rename by clicking it.
 *
 * Rose: *"when in a group or notes or ect you should be able to just click the title to change the
 * title/name of it"*. A note already worked this way — its title has always been a field. A group's
 * did not: renaming one meant opening its settings, which is three taps for a typo.
 *
 * ## Why it is not simply an always-editable input
 *
 * That is what the note screen does, and it is right there because the title is the first thing
 * you type. On a **group** the heading is mostly read, and an input styled to look like a heading
 * brings a caret, a focus ring and a text cursor to something nobody is editing — so this is a
 * button that *becomes* a field, and looks like a heading until it does.
 *
 * Escape cancels and restores what was there. That matters more than it sounds: without it the
 * only way out of an accidental click is to retype the name you just cleared from memory.
 */

export interface EditableTitleProps {
  readonly value: string;
  /** Returns true when it actually changed. Falsey means "put the old one back". */
  readonly onCommit: (next: string) => Promise<boolean> | boolean;
  /** The accessible name of the control, e.g. "Group name". */
  readonly label: string;
  readonly className?: string;
  /** Rendered when the value is empty, and used as the placeholder while editing. */
  readonly placeholder?: string;
  /** Set by a parent — the right-click menu's Rename — to start editing from outside. */
  readonly editing?: boolean;
  readonly onEditingChange?: (editing: boolean) => void;
}

export function EditableTitle({
  value,
  onCommit,
  label,
  className,
  placeholder = 'Untitled',
  editing,
  onEditingChange,
}: EditableTitleProps): React.JSX.Element {
  const [own, setOwn] = useState(false);
  const [draft, setDraft] = useState(value);
  const field = useRef<HTMLInputElement>(null);
  const active = editing ?? own;

  function setActive(next: boolean): void {
    setOwn(next);
    onEditingChange?.(next);
  }

  // The draft is seeded when editing starts, not on every render — otherwise a rename arriving
  // from another device mid-type would overwrite what is being typed.
  useEffect(() => {
    if (active) {
      setDraft(value);
      // Selected, not just focused: the common rename replaces the whole name, and the rarer one
      // is a click away.
      queueMicrotask(() => {
        field.current?.focus();
        field.current?.select();
      });
    }
  }, [active, value]);

  async function commit(): Promise<void> {
    setActive(false);
    const changed = await onCommit(draft);
    if (!changed) setDraft(value);
  }

  if (!active) {
    return (
      <button
        /*
         * "Rename Dreams", not "Dreams".
         *
         * A button's accessible name comes from its content, so without this it announced as just
         * the name — indistinguishable from the row of the same name, and saying nothing about
         * what pressing it does. The visible text is still contained in the label, which is what
         * WCAG 2.5.3 asks for: somebody saying "click Dreams" to a voice control still hits it.
         */
        aria-label={value === '' ? `Rename this ${label.toLowerCase()}` : `Rename ${value}`}
        className={className === undefined ? 'title-edit' : `title-edit ${className}`}
        onClick={() => setActive(true)}
        title={`${label} — click to rename`}
        type="button"
      >
        {value === '' ? <span className="title-empty">{placeholder}</span> : value}
      </button>
    );
  }

  return (
    <input
      aria-label={label}
      className={className === undefined ? 'title-field' : `title-field ${className}`}
      onBlur={() => void commit()}
      onChange={(event) => setDraft(event.target.value)}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          void commit();
        }
        if (event.key === 'Escape') {
          event.preventDefault();
          // Put back what was there. Without this the only way out of an accidental click is to
          // retype from memory the name you have just cleared.
          setDraft(value);
          setActive(false);
        }
      }}
      placeholder={placeholder}
      ref={field}
      value={draft}
    />
  );
}
