import type {
  GroupSettings,
  LayoutMode,
  MemberSectionDisplay,
  NewNoteKind,
  PlusButtonAction,
  ProjectStatus,
  ResolvedGroupSettings,
  SharedWith,
  ShuffleMode,
} from '@rosie-notes/schema';
import { PROJECT_STATUSES, resolveProjectPath } from '@rosie-notes/schema';
import { useState } from 'react';
import { useUserConfig } from '../hooks/use-user-config';
import {
  LAYOUT_LABEL,
  MEMBER_DISPLAY_LABEL,
  NEW_NOTE_LABEL,
  PLUS_LABEL,
  PROJECT_STATUS_BLURB,
  PROJECT_STATUS_LABEL,
  SHARED_WITH_LABEL,
  SHUFFLE_LABEL,
  SORT_OPTIONS,
  sortFromValue,
} from './labels';
import { Callout, OptionStrip, SetGroup, SetRow, SetSwitchRow, SetTextRow } from './primitives';
import { ScaffoldPreviewRow } from './scaffold-preview';
import { ChoiceRow, type OriginProps, SwitchRow } from './settings-rows';

/**
 * The ~15 settings, grouped as `GROUP-MODEL.md` §2 groups them.
 *
 * Five sections, in the order a person decides things: what it is called, how it looks, what a
 * new note is, how you find things, who can see it — then the code-project block, which switches
 * off as a unit rather than leaving orphan rows greyed out.
 *
 * The same form serves an existing group's settings screen and the last step of the add-a-group
 * flow. That is not a saving of effort, it is the point: "pick a preset, then change things
 * before it exists" and "change things afterwards" have to be the same screen, or the preset
 * becomes a type you have to manage.
 */

export interface GroupSettingsFormProps {
  readonly settings: GroupSettings;
  readonly resolved: ResolvedGroupSettings;
  readonly origin: OriginProps;
  readonly onChange: (patch: Partial<GroupSettings>) => void;
  /** The draft form, before the group exists: no name row, no delete. */
  readonly draft?: boolean;
  /** The group being edited, so its subgroups can be shown as the folders they would become. */
  readonly groupId?: string | undefined;
  /** What the group is called — the project name when none is set. */
  readonly groupName?: string;
}

export function GroupSettingsForm({
  settings,
  origin,
  onChange,
  draft = false,
  groupId,
  groupName = '',
}: GroupSettingsFormProps): React.JSX.Element {
  const [open, setOpen] = useState<string | null>(null);
  const toggle = (key: string) => () => setOpen((current) => (current === key ? null : key));
  const { config } = useUserConfig();

  /**
   * Change the code-project block, pre-filling the folder from what the project now is.
   *
   * The rule, and it is the one Rose named: **the path pre-fills from the project and subgroup
   * name, and stays yours to change**. So a derived path is only ever written into an *empty*
   * field — once somebody has typed a folder, nothing here overwrites it — and the derived value
   * is on screen either way, so it is never applied unseen. Deriving a path is a convenience,
   * never an authority.
   */
  function patchCodeProject(patch: Partial<GroupSettings['codeProject']>): void {
    const next = { ...settings.codeProject, ...patch };
    if (next.linkedFolder === null && next.projectType !== null) {
      const derived = resolveProjectPath(config, next.projectType, {
        project: next.projectName ?? groupName,
      });
      if (derived !== null && derived !== '') {
        next.linkedFolder = derived;
      }
    }
    onChange({ codeProject: next });
  }

  return (
    <>
      <SetGroup title="How it looks and reads">
        <ChoiceRow<LayoutMode>
          expanded={open === 'layoutMode'}
          help="Automatic picks from the screen it is on — a wide desktop, a phone, or a narrow editor panel."
          label="Layout"
          onChange={(layoutMode) => onChange({ layoutMode })}
          onToggle={toggle('layoutMode')}
          options={(Object.keys(LAYOUT_LABEL) as LayoutMode[]).map((value) => ({
            value,
            label: LAYOUT_LABEL[value],
          }))}
          origin={origin}
          settingKey="layoutMode"
          value={settings.layoutMode}
        />
        <SwitchRow
          help="Long-form type, reading progress, and it remembers where you stopped."
          label="Reading mode"
          onChange={(readingMode) => onChange({ readingMode })}
          origin={origin}
          settingKey="readingMode"
          value={settings.readingMode}
        />
        <ChoiceRow
          expanded={open === 'sort'}
          label="Sort by"
          onChange={(value) => onChange({ sort: sortFromValue(value) })}
          onToggle={toggle('sort')}
          options={SORT_OPTIONS.map((option) => ({ value: option.value, label: option.label }))}
          origin={origin}
          settingKey="sort"
          value={`${settings.sort.field}:${settings.sort.direction}`}
        />
      </SetGroup>

      <SetGroup title="What a new note is">
        <ChoiceRow<NewNoteKind>
          expanded={open === 'newNoteKind'}
          label="New notes start as"
          onChange={(newNoteKind) => onChange({ newNoteKind })}
          onToggle={toggle('newNoteKind')}
          options={(Object.keys(NEW_NOTE_LABEL) as NewNoteKind[]).map((value) => ({
            value,
            label: NEW_NOTE_LABEL[value],
          }))}
          origin={origin}
          settingKey="newNoteKind"
          value={settings.newNoteKind}
        />
        <ChoiceRow<PlusButtonAction>
          expanded={open === 'plusButtonAction'}
          label="The + button does"
          onChange={(plusButtonAction) => onChange({ plusButtonAction })}
          onToggle={toggle('plusButtonAction')}
          options={(Object.keys(PLUS_LABEL) as PlusButtonAction[]).map((value) => ({
            value,
            label: PLUS_LABEL[value],
          }))}
          origin={origin}
          settingKey="plusButtonAction"
          value={settings.plusButtonAction}
        />
        <SwitchRow
          help="Numbered when there is more than one on the same day."
          label="Name new notes automatically"
          onChange={(enabled) => onChange({ autoTitle: { ...settings.autoTitle, enabled } })}
          origin={origin}
          settingKey="autoTitle"
          value={settings.autoTitle.enabled}
        />
        {settings.autoTitle.enabled && (
          <SetTextRow
            help="Use {group} for this group's name, {date} for today, {time} for the clock."
            label="Naming rule"
            mono
            onChange={(template) =>
              onChange({ autoTitle: { ...settings.autoTitle, template: template || '{group}' } })
            }
            placeholder="Dream — {date}"
            value={settings.autoTitle.template}
          />
        )}
        <SwitchRow
          help="Makes one note per person, and that note is their section."
          label="Give each member their own note"
          onChange={(memberOwnNote) => onChange({ memberOwnNote })}
          origin={origin}
          settingKey="memberOwnNote"
          value={settings.memberOwnNote}
        />
      </SetGroup>

      <SetGroup title="Finding things">
        <ChoiceRow<ShuffleMode>
          expanded={open === 'shuffle'}
          help="Pulls from this group and everything under it."
          label="Shuffle"
          onChange={(shuffle) => onChange({ shuffle })}
          onToggle={toggle('shuffle')}
          options={(Object.keys(SHUFFLE_LABEL) as ShuffleMode[]).map((value) => ({
            value,
            label: SHUFFLE_LABEL[value],
          }))}
          origin={origin}
          settingKey="shuffle"
          value={settings.shuffle}
        />
        <QuickTagsRow
          onChange={(quickTags) => onChange({ quickTags })}
          origin={origin}
          tags={settings.quickTags}
        />
      </SetGroup>

      <SetGroup note="Narrower wins" title="Who can see it">
        <ChoiceRow<SharedWith>
          expanded={open === 'sharedWith'}
          help={
            settings.sharedWith === 'nobody'
              ? 'Nobody else can open this group.'
              : settings.sharedWith === 'anyone_with_link'
                ? 'Anyone holding the link can read it.'
                : 'The people you add can read everything in here unless a note is locked.'
          }
          label="Shared with"
          onChange={(sharedWith) => onChange({ sharedWith })}
          onToggle={toggle('sharedWith')}
          options={(Object.keys(SHARED_WITH_LABEL) as SharedWith[]).map((value) => ({
            value,
            label: SHARED_WITH_LABEL[value],
          }))}
          origin={origin}
          settingKey="sharedWith"
          value={settings.sharedWith}
        />
        <SwitchRow
          help="Each person owns a part of this group that only they write to."
          label="Members write in their own section"
          onChange={(memberSections) => onChange({ memberSections })}
          origin={origin}
          settingKey="memberSections"
          value={settings.memberSections}
        />
        {settings.memberSections && (
          <ChoiceRow<MemberSectionDisplay>
            expanded={open === 'memberSectionDisplay'}
            label="Show member sections as"
            onChange={(memberSectionDisplay) => onChange({ memberSectionDisplay })}
            onToggle={toggle('memberSectionDisplay')}
            options={(Object.keys(MEMBER_DISPLAY_LABEL) as MemberSectionDisplay[]).map((value) => ({
              value,
              label: MEMBER_DISPLAY_LABEL[value],
            }))}
            origin={origin}
            settingKey="memberSectionDisplay"
            value={settings.memberSectionDisplay}
          />
        )}
        <SwitchRow
          help="Adds a lock to every note here. A locked note is hidden from the other members — whoever runs the server can still read it."
          label="Notes can be marked private"
          onChange={(privateNotes) => onChange({ privateNotes })}
          origin={origin}
          settingKey="privateNotes"
          value={settings.privateNotes}
        />
      </SetGroup>

      <SetGroup title="Being told about changes">
        <SetSwitchRow
          checked={settings.notifyWhen.includes('note_added')}
          help="Someone adds a note to this group."
          label="Tell me about new notes"
          onChange={(on) =>
            onChange({
              notifyWhen: on
                ? [...new Set([...settings.notifyWhen, 'note_added' as const])]
                : settings.notifyWhen.filter((event) => event !== 'note_added'),
            })
          }
        />
        <SetSwitchRow
          checked={settings.notifyWhen.includes('note_edited')}
          help="Someone changes a note that is already here."
          label="Tell me about edits"
          onChange={(on) =>
            onChange({
              notifyWhen: on
                ? [...new Set([...settings.notifyWhen, 'note_edited' as const])]
                : settings.notifyWhen.filter((event) => event !== 'note_edited'),
            })
          }
        />
      </SetGroup>

      {/* The one block allowed to be meaningful for only some groups, and the price of that is
          that it is a *block*: off means gone, not fifteen greyed-out rows. */}
      <SetGroup
        note={settings.codeProject.enabled ? 'Nothing is written until you say so' : undefined}
        title="Files on disk"
      >
        <SwitchRow
          help="Subgroups become directories and notes become files."
          label="Keep this group as a folder"
          onChange={(enabled) => onChange({ codeProject: { ...settings.codeProject, enabled } })}
          origin={origin}
          settingKey="codeProject"
          value={settings.codeProject.enabled}
        />
        {settings.codeProject.enabled && (
          <>
            {/* First, because it is the row Rose actually reads. "Not worked on in a while" is
                deliberately not one of the options: it is worked out from the dates, and asking
                somebody to hand-maintain a flag meaning "I have not touched this lately" is
                asking them to do the bookkeeping this whole feature exists to remove. */}
            <SetRow
              expanded={open === 'status'}
              help={`Where this project stands. ${PROJECT_STATUS_BLURB[settings.codeProject.status]} A WIP project nobody has touched for a month is shown as stale on its own, so there is nothing to keep up to date.`}
              label="Status"
              onClick={toggle('status')}
              value={<span>{PROJECT_STATUS_LABEL[settings.codeProject.status]}</span>}
            >
              <OptionStrip<ProjectStatus>
                label="Status"
                // Not `patchCodeProject`: that one derives the linked folder, and changing a
                // status must never quietly write a path into an empty field.
                onChange={(status) =>
                  onChange({ codeProject: { ...settings.codeProject, status } })
                }
                options={PROJECT_STATUSES.map((value) => ({
                  value,
                  label: PROJECT_STATUS_LABEL[value],
                }))}
                value={settings.codeProject.status}
              />
            </SetRow>
            {/* A picker once the person has imported a config, a free field before that. The
                types are theirs, so there is nothing built in to offer as a fallback. */}
            {config.paths.types.length > 0 ? (
              <SetRow
                expanded={open === 'projectType'}
                help="Yours, from your config. It decides which path template the folder comes from."
                label="Project type"
                onClick={toggle('projectType')}
                value={
                  <span>
                    {config.paths.types.find((type) => type.id === settings.codeProject.projectType)
                      ?.label ?? 'Not set'}
                  </span>
                }
              >
                <OptionStrip
                  label="Project type"
                  onChange={(projectType) => patchCodeProject({ projectType })}
                  options={config.paths.types.map((type) => ({
                    value: type.id,
                    label: type.label,
                  }))}
                  value={settings.codeProject.projectType ?? ''}
                />
              </SetRow>
            ) : (
              <SetTextRow
                help="Your own label — it indexes into your list of types and their path templates. Import a config in Settings to pick from a list instead."
                label="Project type"
                onChange={(projectType) =>
                  patchCodeProject({ projectType: projectType === '' ? null : projectType })
                }
                placeholder="rust"
                value={settings.codeProject.projectType ?? ''}
              />
            )}
            <SetTextRow
              help="The folder name under your projects directory. Defaults to what this group is called."
              label="Project name"
              onChange={(projectName) =>
                patchCodeProject({ projectName: projectName === '' ? null : projectName })
              }
              placeholder={groupName === '' ? 'mc-updater' : groupName}
              value={settings.codeProject.projectName ?? ''}
            />
            <SetTextRow
              help="Filled in from the type and name. Always yours to change, and always shown before anything is written."
              label="Linked folder"
              mono
              onChange={(linkedFolder) =>
                onChange({
                  codeProject: {
                    ...settings.codeProject,
                    linkedFolder: linkedFolder === '' ? null : linkedFolder,
                  },
                })
              }
              placeholder="D:/code/projects/mc-updater"
              value={settings.codeProject.linkedFolder ?? ''}
            />
            {/* The slug the `handoff` CLI pushes under, not a path and not a group name. Naming
                one is what lets the card show real progress instead of a note count — a set that
                has never been pushed simply leaves the card as it was. */}
            <SetTextRow
              help="The project a pushed handoff set is filed under, if this one keeps one. Its task list becomes the progress shown on this group's row."
              label="Handoff project"
              mono
              onChange={(handoffProject) =>
                onChange({
                  codeProject: {
                    ...settings.codeProject,
                    handoffProject: handoffProject === '' ? null : handoffProject,
                  },
                })
              }
              placeholder="notes-ect"
              value={settings.codeProject.handoffProject ?? ''}
            />
            {/* T-15's first half: a link, shown on the group screen when set. The reviewable
                half — sharing it with drawing on screenshots — is a separate, larger feature and
                is not built here. */}
            <SetTextRow
              help="Where the code actually lives. Shown as a link on the group screen; nothing here reads or writes to it."
              label="Repository"
              mono
              onChange={(repoUrl) =>
                onChange({
                  codeProject: {
                    ...settings.codeProject,
                    repoUrl: repoUrl === '' ? null : repoUrl,
                  },
                })
              }
              placeholder="https://github.com/you/notes-ect"
              value={settings.codeProject.repoUrl ?? ''}
            />
            <TagsRow
              onChange={(tags) => patchCodeProject({ tags })}
              rules={config.tagRules}
              tags={settings.codeProject.tags}
            />
            <SetSwitchRow
              checked={settings.codeProject.mainFile.enabled}
              help="A starting file written at the top of the folder."
              label="Create a main file"
              onChange={(enabled) =>
                onChange({
                  codeProject: {
                    ...settings.codeProject,
                    mainFile: { ...settings.codeProject.mainFile, enabled },
                  },
                })
              }
            />
            <SetSwitchRow
              checked={settings.codeProject.orchestratorPrompt.enabled}
              help="A reusable block, switched on per group."
              label="Include orchestrator prompt"
              onChange={(enabled) =>
                onChange({
                  codeProject: {
                    ...settings.codeProject,
                    orchestratorPrompt: { ...settings.codeProject.orchestratorPrompt, enabled },
                  },
                })
              }
            />
            <SetSwitchRow
              checked={settings.codeProject.checkDiskChanges}
              help="Only does anything inside the editor, where the files are."
              label="Check for changes on disk"
              onChange={(checkDiskChanges) =>
                onChange({ codeProject: { ...settings.codeProject, checkDiskChanges } })
              }
            />
            <ScaffoldPreviewRow groupId={groupId} groupName={groupName} settings={settings} />
          </>
        )}
      </SetGroup>

      {draft && (
        <Callout className="callout-spaced" icon="eye" tone="quiet">
          Everything here can be changed afterwards. A preset only fills these in — once the group
          exists there is no type to manage and nothing to re-apply.
        </Callout>
      )}
    </>
  );
}

/**
 * The group's quick-tag list.
 *
 * Two things live near each other here and they belong to two different owners: the **list** is
 * the group's, and the show/hide and shuffle preferences under each tag are **this person's**. So
 * this row edits only the list, and says so — the per-person half is stored through
 * `/v1/groups/:id/quick-tags` and is deliberately not dressed in the lock's language. Hiding is a
 * curtain; the lock is a door, and the distance between them is where somebody gets hurt.
 */
function QuickTagsRow({
  tags,
  onChange,
  origin,
}: {
  readonly tags: GroupSettings['quickTags'];
  readonly onChange: (next: GroupSettings['quickTags']) => void;
  readonly origin: OriginProps;
}): React.JSX.Element {
  const [draft, setDraft] = useState('');
  const [open, setOpen] = useState(false);

  function add(): void {
    const cleaned = draft.trim().toLowerCase().replace(/\s+/g, '-').slice(0, 48);
    if (cleaned === '' || tags.includes(cleaned as GroupSettings['quickTags'][number])) {
      setDraft('');
      return;
    }
    onChange([...tags, cleaned as GroupSettings['quickTags'][number]]);
    setDraft('');
  }

  return (
    <div>
      <button
        aria-expanded={open}
        className="setrow"
        onClick={() => setOpen((value) => !value)}
        type="button"
      >
        <span className="setrow-main">
          <span className="setrow-label">Quick tags</span>
          <span className="setrow-help">
            A short list this group promotes to one-click toggles on every note here. What each one
            does to your own lists is yours alone, and never changes what anyone else can see.
          </span>
        </span>
        <span className="setrow-value">
          <OriginMarkInline origin={origin} />
          <span>{tags.length === 0 ? 'None yet' : tags.slice(0, 2).join(' · ')}</span>
        </span>
      </button>
      {open && (
        <div className="setopts stack">
          <div>
            <div className="setrow-help">
              This group&rsquo;s list — everyone here sees the same tags.
            </div>
            <div className="qtset" style={{ marginTop: 8 }}>
              {tags.length === 0 ? (
                <span className="tagbar-none">No quick tags yet.</span>
              ) : (
                tags.map((tag) => (
                  <span className="qtdef" key={tag}>
                    {tag}
                    <button
                      onClick={() => onChange(tags.filter((entry) => entry !== tag))}
                      title={`Remove ${tag}`}
                      type="button"
                    >
                      <span aria-hidden="true">×</span>
                      <span className="sr">Remove {tag}</span>
                    </button>
                  </span>
                ))
              )}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <input
              aria-label="New quick tag"
              className="field"
              onChange={(event) => setDraft(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  event.preventDefault();
                  add();
                }
              }}
              placeholder="spoiler"
              style={{ width: 180, flex: 'none' }}
              value={draft}
            />
            <button className="btn" onClick={add} type="button">
              Add tag
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function OriginMarkInline({ origin }: { readonly origin: OriginProps }): React.JSX.Element {
  const entry = origin.origins['quickTags'];
  if (entry === undefined) return <span className="inh inh-from">Default</span>;
  if (entry.source === 'set') return <span className="inh inh-here">Set here</span>;
  const from = origin.nameOf(entry.setBy);
  return <span className="inh inh-from">{from === null ? 'Default' : `from ${from}`}</span>;
}

/**
 * The tags that change how this project is **set up**.
 *
 * Rose: *"allow users to have tags that change how things are auto setup"*. Deliberately kept
 * apart from quick tags, which label notes: these change what gets *created*, so a tag with no
 * rule behind it is worth saying out loud rather than leaving to look as though it did something.
 */
function TagsRow({
  tags,
  rules,
  onChange,
}: {
  readonly tags: readonly string[];
  readonly rules: readonly { readonly tag: string }[];
  readonly onChange: (next: string[]) => void;
}): React.JSX.Element {
  const [draft, setDraft] = useState('');

  function add(): void {
    const cleaned = draft.trim().toLowerCase().replace(/\s+/gu, '-').slice(0, 64);
    if (cleaned === '' || tags.includes(cleaned)) {
      setDraft('');
      return;
    }
    onChange([...tags, cleaned]);
    setDraft('');
  }

  const unmatched = tags.filter((tag) => !rules.some((rule) => rule.tag === tag));

  return (
    <div className="setrow setrow-stack">
      <span className="setrow-label">Setup tags</span>
      <span className="setrow-help spaced">
        Tags that change what gets created — an extra folder, or a different root. The rules behind
        them are in your own config.
      </span>
      <div className="qtset" style={{ marginBottom: 8 }}>
        {tags.length === 0 ? (
          <span className="tagbar-none">None.</span>
        ) : (
          tags.map((tag) => (
            <span className="qtdef" key={tag}>
              {tag}
              <button
                onClick={() => onChange(tags.filter((entry) => entry !== tag))}
                title={`Remove ${tag}`}
                type="button"
              >
                <span aria-hidden="true">&times;</span>
                <span className="sr">Remove {tag}</span>
              </button>
            </span>
          ))
        )}
      </div>
      {unmatched.length > 0 && (
        <span className="setrow-help spaced">
          Nothing in your config matches {unmatched.join(', ')}, so{' '}
          {unmatched.length === 1 ? 'it changes' : 'they change'} nothing yet.
        </span>
      )}
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        <input
          aria-label="New setup tag"
          className="field"
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') {
              event.preventDefault();
              add();
            }
          }}
          placeholder="android"
          style={{ width: 180, flex: 'none' }}
          value={draft}
        />
        <button className="btn" onClick={add} type="button">
          Add tag
        </button>
      </div>
    </div>
  );
}
