import type { Group } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useHandoffProject } from '../hooks/use-handoff';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { EditableTitle } from './editable-title';
import { Icon } from './icons';
import { ago, plural } from './labels';
import { Btn, Chip, Glyph, Sep } from './primitives';
import {
  ProjectProgress,
  ProjectStatusChip,
  projectFact,
  StaleChip,
  StatusFilterBar,
  useProjectFilter,
} from './project-status';
import { AddRow, List, Row, SkeletonRows } from './rail';
import { RowMoveSheet, type RowTarget, useRowActions } from './row-actions';
import { RowMenu, type RowMenuState } from './row-menu';
import { useSelectionDrop } from './selection-bar';
import { orderedItems, useRowSelection } from './selection-context';
import { useShell } from './shell-context';
import { ErrorState, OfflineBanner } from './states';

/**
 * Home: every top-level group, and the way in to a new one.
 *
 * This is the front door and it is the same shape as every other level — a rail with rows on it,
 * and an add row at the bottom. That is the point of "one column, any depth": home is not a
 * special screen, it is the group list with no parent.
 */

export function HomeView(): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const shell = useShell();
  // Over the tree the app already holds: no endpoint, no spinner, and it works offline for the
  // same reason the list itself does.
  const filter = useProjectFilter(tree.roots);
  // What a shift-click measures along: the filtered list as drawn, not the whole tree.
  const siblingIds = useMemo(
    () => filter.groups.map((group) => group.id as string),
    [filter.groups],
  );

  if (tree.error !== null && tree.roots.length === 0) {
    return (
      <ErrorState
        body="The server did not answer, and there is nothing cached on this device yet."
        onRetry={() => void tree.reload()}
        title="Your groups could not be loaded"
      />
    );
  }

  if (tree.loading && tree.roots.length === 0) {
    return (
      <>
        <PageHeader sub={<span>Counting things up…</span>} title="Your groups" />
        <SkeletonRows count={4} />
      </>
    );
  }

  const totals = tree.roots.reduce(
    (running, group) => {
      const counted = tree.tally(group.id as string);
      return { notes: running.notes + counted.notes, groups: running.groups + counted.groups + 1 };
    },
    { notes: 0, groups: 0 },
  );

  const lastChange = tree.roots
    .map((group) => group.updatedAt)
    .sort()
    .at(-1);

  if (tree.roots.length === 0) {
    // The empty state's single big button. A quiet text link offers the other action underneath,
    // so the primary one stays singular.
    return (
      <div className="empty">
        <div className="empty-mark" />
        {/* An `<h1>`, not the `<h2>` `EmptyState` uses: this one *replaces* the page header
            rather than sitting under it, and a screen with no `<h1>` at all is the same problem
            as a skipped level seen from the other end. */}
        <h1>Nothing here yet</h1>
        <p>
          Everything lives in a group — a project, a journal, a shelf of things to read. Make the
          first one and you can rearrange it later, or never.
        </p>
        <Btn
          icon="plus"
          large
          onClick={() => navigate({ name: 'newGroup', parentId: null })}
          tone="primary"
        >
          Add a group
        </Btn>
      </div>
    );
  }

  return (
    <>
      {tree.stale && <OfflineBanner what="groups" />}
      <PageHeader
        actions={
          <Btn className="wide-only" icon="plus" onClick={() => shell.openAdd(null)} tone="primary">
            Add
          </Btn>
        }
        sub={
          <>
            <span className="num">{plural(totals.notes, 'note')}</span>
            <Sep />
            <span className="num">
              {plural(totals.groups, 'group')}, {tree.roots.length} at the top
            </span>
            {lastChange !== undefined && (
              <>
                <Sep />
                <span>last change {ago(lastChange)}</span>
              </>
            )}
          </>
        }
        title="Your groups"
      />
      <StatusFilterBar filter={filter} label="Filter your projects by status" />
      <List label="Your groups">
        {filter.groups.map((group) => (
          <GroupRow group={group} key={group.id} siblings={siblingIds} />
        ))}
        <AddRow label="New group" onClick={() => navigate({ name: 'newGroup', parentId: null })} />
      </List>
    </>
  );
}

/**
 * One group, on the rail.
 *
 * The meta line is the group's settings read back as words — how many things are in it, whether
 * it reads, who can see it. A person should be able to tell what a group *is* without opening it.
 */
export function GroupRow({
  group,
  siblings = [],
}: {
  readonly group: Group;
  /**
   * The ids of the list this row is drawn in, in the order it is drawn.
   *
   * Only shift-click needs it, and only the list itself knows it: a range has to match what a
   * person can see, and what they can see is this list in this order — not the tree, and not
   * anything derivable from ids. Empty means the row is selectable but ranges fall back to
   * single toggles, which is the honest behaviour when there is no order to measure along.
   */
  readonly siblings?: readonly string[];
}): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const ordered = useMemo(() => orderedItems('group', siblings), [siblings]);
  const select = useRowSelection('group', group.id as string, ordered);
  const onDropSelection = useSelectionDrop(group.id as string);
  const actions = useRowActions();
  const [menu, setMenu] = useState<RowMenuState | null>(null);
  const [renaming, setRenaming] = useState(false);
  const target = { kind: 'group' as const, id: group.id as string, name: group.name };
  const counted = tree.tally(group.id as string);
  const settings = tree.settingsOf(group.id as string).effective;

  // What the project is, before what is in it: the reason this row carries a status at all is so
  // a dozen of them can be read down the left edge without opening any of them.
  const fact = projectFact(settings, group.updatedAt);

  /*
   * Real progress when the project names a handoff set, and the note count when it does not.
   *
   * A project with no set pushed is the common case and is not a failure — the row simply keeps
   * the count of what is in it, which is a true thing about the group rather than a progress
   * figure invented to fill the space. Nothing is asked of the server for a group that names no
   * project.
   */
  const handoff = useHandoffProject(
    settings.codeProject.enabled ? settings.codeProject.handoffProject : null,
  );

  const meta: React.JSX.Element[] = [];
  if (fact.status !== null) {
    meta.push(<ProjectStatusChip key="status" status={fact.status} />);
  }
  if (fact.stale) {
    meta.push(<StaleChip key="stale" />);
  }
  if (handoff.set !== null) {
    meta.push(<ProjectProgress key="progress" progress={handoff.set.progress} />);
  }
  if (counted.groups > 0) {
    meta.push(<span key="groups">{plural(counted.groups, 'subgroup')}</span>);
  }
  meta.push(<span key="notes">{plural(counted.notes, 'note')}</span>);
  if (settings.readingMode) {
    meta.push(
      <Chip icon="book" key="reading">
        Reading
      </Chip>,
    );
  }
  if (settings.sharedWith === 'specific_people') {
    meta.push(
      <Chip icon="people" key="shared" tone="accent">
        Shared
      </Chip>,
    );
  } else if (settings.sharedWith === 'anyone_with_link') {
    meta.push(
      <Chip key="link" tone="line">
        Anyone with the link
      </Chip>,
    );
  }
  if (settings.privateNotes) {
    meta.push(
      <Chip icon="lock" key="lock" tone="private">
        Locking on
      </Chip>,
    );
  }
  meta.push(<span key="ago">{ago(group.updatedAt)}</span>);

  return (
    <>
      <Row
        // A group with no colour of its own reads in its nearest coloured ancestor's, which is what
        // makes a whole project tree one colour rather than only its root row.
        accent={tree.colourOf(group.id as string)}
        icon={<Glyph icon={group.icon} />}
        kind="group"
        label={group.name}
        mark="group"
        meta={meta.flatMap((node, index) =>
          index === 0 ? [node] : [<Sep key={`sep-${node.key ?? index}`} />, node],
        )}
        onDropSelection={onDropSelection}
        onMenu={(at) =>
          setMenu({
            ...at,
            label: `Actions for ${group.name}`,
            items: actions.itemsFor(target, { onRename: () => setRenaming(true) }),
          })
        }
        onOpen={() => navigate({ name: 'group', groupId: group.id as string })}
        select={select}
        title={
          renaming ? (
            <EditableTitle
              editing
              label="Group name"
              onCommit={(next) => actions.rename(target, next)}
              onEditingChange={setRenaming}
              value={group.name}
            />
          ) : (
            group.name
          )
        }
        trailing={<Icon name="chev" />}
      />
      {menu !== null && <RowMenu {...menu} onClose={() => setMenu(null)} />}
      {actions.moving !== null && (
        <RowMoveSheet
          onClose={actions.closeMove}
          onMove={(destination) => void actions.move(actions.moving as RowTarget, destination)}
          target={actions.moving}
        />
      )}
    </>
  );
}
