import type { Group } from '@rosie-notes/schema';
import type { ReactNode } from 'react';
import { Icon } from './icons';
import { Glyph } from './primitives';

/**
 * Breadcrumb and page header — the two pieces of chrome every screen wears.
 *
 * The breadcrumb is how arbitrary depth is navigated without a tree in a sidebar. It scrolls
 * sideways *inside itself* when the descent is deep, which is the one place in the app where a
 * horizontal scroll is correct: the alternative is either truncating ancestors a person needs to
 * jump to, or letting a long chain widen the page, and the page must never widen.
 */

export interface BreadcrumbProps {
  /** Root first, current last. The last entry is rendered as text, not a link. */
  readonly chain: readonly Group[];
  readonly onHome: () => void;
  readonly onOpen: (group: Group) => void;
  /** Appended after the chain when the screen is *about* a group rather than being it. */
  readonly leaf?: string;
}

export function Breadcrumb({ chain, onHome, onOpen, leaf }: BreadcrumbProps): React.JSX.Element {
  return (
    <nav aria-label="Breadcrumb" className="crumbs">
      <button onClick={onHome} type="button">
        Home
      </button>
      {chain.map((group, index) => {
        const last = index === chain.length - 1 && leaf === undefined;
        return (
          <span key={group.id} style={{ display: 'contents' }}>
            <span aria-hidden="true" className="sep">
              /
            </span>
            {last ? (
              <span aria-current="page" className="now">
                {group.name}
              </span>
            ) : (
              <button onClick={() => onOpen(group)} type="button">
                {group.name}
              </button>
            )}
          </span>
        );
      })}
      {leaf !== undefined && (
        <>
          <span aria-hidden="true" className="sep">
            /
          </span>
          <span aria-current="page" className="now">
            {leaf}
          </span>
        </>
      )}
    </nav>
  );
}

export interface PageHeaderProps {
  /**
   * A string, or a control that renames in place.
   *
   * Rose: *"you should be able to just click the title to change the title/name of it"*. A note's
   * title has always been a field; a group's meant opening its settings, which is three taps for a
   * typo. Widened to a node rather than adding an `onRename` prop, so the header stays a header
   * and `EditableTitle` owns the whole of the click-to-edit behaviour.
   */
  readonly title: ReactNode;
  readonly sub?: ReactNode;
  readonly actions?: ReactNode;
  /** A group's or note's mark, shown in a tile to the left of the title. */
  readonly icon?: string | null;
  /** Makes the tile a button — "change this icon". */
  readonly onEditIcon?: () => void;
  readonly titleRef?: (element: HTMLHeadingElement | null) => void;
}

export function PageHeader({
  title,
  sub,
  actions,
  icon,
  onEditIcon,
  titleRef,
}: PageHeaderProps): React.JSX.Element {
  return (
    <div className="phead">
      <div className="phead-top">
        {icon !== undefined &&
          (onEditIcon === undefined ? (
            <div className="glyph">
              <Glyph icon={icon} />
            </div>
          ) : (
            <button
              className="glyph glyph-btn"
              onClick={onEditIcon}
              title="Change this icon"
              type="button"
            >
              <Glyph icon={icon} />
              <span className="gl-pen">
                <Icon name="edit" />
              </span>
              <span className="sr">Change this icon</span>
            </button>
          ))}
        <div className="phead-main">
          {/* `tabIndex={-1}` so a route change can move focus here without adding a tab stop. */}
          <h1 className="ptitle" ref={titleRef} tabIndex={-1}>
            {title}
          </h1>
          {sub !== undefined && <div className="psub">{sub}</div>}
        </div>
        {actions !== undefined && <div className="phead-actions">{actions}</div>}
      </div>
    </div>
  );
}
