import { Component, type ErrorInfo, type ReactNode } from 'react';

/**
 * The screen that shows when something throws while rendering.
 *
 * There was no boundary at all, and the cost of that turned up as a bug report that could not be
 * investigated: Rose said "settings page doesn't load anymore", and a thrown render error in React
 * unmounts the whole tree, so the page went **blank with nothing written on it**. No message, no
 * route, no stack — nothing for Rose to send and nothing for me to search for. Five clean runs
 * against fresh accounts reproduced nothing, because the fault needed state neither of us could
 * name.
 *
 * So this is not decoration. It converts a silent, unreportable blank page into a specific
 * sentence, which is the difference between a bug that gets fixed and one that gets guessed at.
 *
 * Three deliberate choices:
 *
 * - **It shows the message and the route.** Not a friendly apology. The person reading it is the
 *   one who has to report it, and "Cannot read properties of undefined (reading 'length')" on
 *   `#/settings` is the entire investigation.
 * - **It offers to clear local data**, because the most likely cause of a crash that one person
 *   sees and nobody else can reproduce is something cached on that device.
 * - **It is scoped per route, not just at the root.** A crash in one screen leaves the rest of the
 *   app usable, so somebody can get to Settings and sign out rather than being locked out entirely.
 */

interface Props {
  readonly children: ReactNode;
  /** Named in the message, so a report says which screen without anyone having to remember. */
  readonly where: string;
}

interface State {
  readonly error: Error | null;
  readonly info: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  override state: State = { error: null, info: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  override componentDidCatch(error: Error, info: ErrorInfo): void {
    // Kept out of state until here: `getDerivedStateFromError` runs during render and must stay
    // pure, and the component stack is the half that says *which* component threw.
    this.setState({ info: info.componentStack ?? null });
    console.error(`[rosie-notes] render failed in ${this.props.where}`, error, info.componentStack);
  }

  private readonly reload = (): void => {
    globalThis.location.reload();
  };

  private readonly clearAndReload = (): void => {
    // Deliberately narrow: only this app's own keys. Wiping all of localStorage would take out
    // whatever else is served from this origin, which is somebody else's data.
    try {
      for (const key of Object.keys(globalThis.localStorage)) {
        if (key.startsWith('rn.') || key.startsWith('rosie-notes')) {
          globalThis.localStorage.removeItem(key);
        }
      }
    } catch {
      // A blocked storage API must not stop the reload — that is the part that might fix it.
    }
    globalThis.location.reload();
  };

  override render(): ReactNode {
    const { error, info } = this.state;
    if (error === null) return this.props.children;

    return (
      <main className="auth" data-rn="">
        <div className="auth__card">
          <h1 className="auth__title">That screen did not load</h1>
          <p className="auth__note auth__note--lead">
            Something threw while drawing <b>{this.props.where}</b>. The rest of the app still works
            — this is one screen, not your notes.
          </p>

          <p className="auth__error" role="alert">
            {error.message || String(error)}
          </p>

          <p className="hint">
            Nothing has been lost. Your notes are on the server, and this happened while drawing
            them rather than while saving.
          </p>

          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button className="btn btn-primary" onClick={this.reload} type="button">
              Reload
            </button>
            <button className="btn" onClick={this.clearAndReload} type="button">
              Clear this device's cache and reload
            </button>
          </div>

          {info !== null && (
            <details style={{ marginTop: 12 }}>
              <summary className="hint">What to send if it keeps happening</summary>
              <pre
                style={{
                  whiteSpace: 'pre-wrap',
                  overflowX: 'auto',
                  fontSize: 12,
                  maxHeight: 220,
                }}
              >
                {error.stack ?? error.message}
                {info}
              </pre>
            </details>
          )}
        </div>
      </main>
    );
  }
}
