import type { CollectionId, Note, RandomMode, ShuffleMode } from '@rosie-notes/schema';
import { useCallback } from 'react';
import { isDeliveryFailure } from '../offline/write-queue';
import { useWorkspace } from '../session/session-context';

/**
 * "Give me one."
 *
 * For a shelf of stories this is the *primary* way the library is used — it is not a filing
 * cabinet you go looking in, it is a shelf you pull from. So the group's own shuffle setting
 * decides what "one" means, and the server holds the state that makes two of the three modes
 * honest: `least_seen` needs `lastSeenAt`, and `shuffle_bag` needs a bag that remembers what has
 * already come out. Neither can be faked client-side without lying about "no repeats".
 *
 * Offline it falls back to a plain draw over whatever this device has cached, which is the
 * honest degradation: still a random note, no longer a promise about repeats.
 */

const MODE: Record<Exclude<ShuffleMode, 'off'>, RandomMode> = {
  random: 'pure',
  least_read: 'least_seen',
  no_repeats: 'shuffle_bag',
};

export interface ShuffleResult {
  readonly note: Note | null;
  /** True when the draw came from the cache rather than the server. */
  readonly local: boolean;
  /** How many notes the group holds, when the server said. */
  readonly matchCount: number | null;
}

export function useShuffle(): (
  groupId: string | null,
  mode: ShuffleMode,
) => Promise<ShuffleResult> {
  const workspace = useWorkspace();

  return useCallback(
    async (groupId, mode) => {
      if (mode === 'off') {
        return { note: null, local: false, matchCount: null };
      }

      try {
        const response = await workspace.client.search.random({
          mode: MODE[mode],
          count: 1,
          markSeen: true,
          ...(groupId === null ? {} : { collectionId: groupId as CollectionId }),
        });
        return {
          note: response.notes[0] ?? null,
          local: false,
          matchCount: response.matchCount,
        };
      } catch (error) {
        // Only a request that never landed is worth answering from the cache. A refusal is the
        // server telling us something — "shuffle is off for that group", "nothing matches" — and
        // drawing a note anyway would be inventing an answer it just declined to give.
        if (!isDeliveryFailure(error)) {
          return { note: null, local: false, matchCount: null };
        }
        const cached = await workspace.adapter.cache.listNotes();
        const pool = cached.filter(
          (note) =>
            !note.trashed &&
            (groupId === null || note.collectionIds.includes(groupId as CollectionId)),
        );
        if (pool.length === 0) {
          return { note: null, local: true, matchCount: 0 };
        }
        const picked = pool[Math.floor(Math.random() * pool.length)] ?? null;
        return { note: picked, local: true, matchCount: pool.length };
      }
    },
    [workspace],
  );
}
