import type { ReactNode } from 'react';
import { useCallback, useEffect, useId, useRef } from 'react';
import { Icon, type IconName } from './icons';

/**
 * The recurring components, written once.
 *
 * Everything here is in `DESIGN-SYSTEM.md`'s component table. Two of them are load-bearing
 * rather than cosmetic and are worth reading closely:
 *
 * - {@link InheritanceMark} is the single most reused idea in the product. Sharing, notifications
 *   and layout are three settings families with one interaction: a solid pill saying **Set here**
 *   or a dashed one saying **from _Dreams_**. If those three ever diverge, seventeen settings go
 *   back to feeling like a control panel.
 * - {@link Sheet} is one markup for a centred dialog and a bottom sheet. `Escape` closes it, the
 *   scrim closes it, and clicking inside does not — and it takes focus and gives it back, because
 *   a dialog that strands the keyboard is worse than no dialog.
 */

// -------------------------------------------------------------------------------------------
// Text safety
// -------------------------------------------------------------------------------------------

/**
 * A person's own words, rendered as words.
 *
 * React escapes interpolated strings, so this is not a sanitiser and does not pretend to be —
 * it is a *named place* to put user-supplied text so that "is this rendered as markup?" has a
 * one-word answer at every call site. A display name containing a script tag or an emoji is
 * inert everywhere it appears because nothing in this app ever reaches for
 * `dangerouslySetInnerHTML`, and the way to keep that true is to never introduce the habit.
 */
export function Text({ value }: { readonly value: string }): React.JSX.Element {
  return <>{value}</>;
}

// -------------------------------------------------------------------------------------------
// Buttons and chips
// -------------------------------------------------------------------------------------------

export type ButtonTone = 'default' | 'primary' | 'ghost' | 'quiet' | 'danger';

export interface BtnProps {
  readonly children: ReactNode;
  readonly onClick?: () => void;
  readonly tone?: ButtonTone;
  readonly icon?: IconName;
  readonly large?: boolean;
  readonly small?: boolean;
  readonly block?: boolean;
  readonly disabled?: boolean;
  readonly className?: string;
  readonly title?: string;
  readonly type?: 'button' | 'submit';
}

const TONE_CLASS: Record<ButtonTone, string> = {
  default: '',
  primary: 'btn-primary',
  ghost: 'btn-ghost',
  quiet: 'btn-quiet',
  danger: 'btn-danger',
};

export function Btn({
  children,
  onClick,
  tone = 'default',
  icon,
  large = false,
  small = false,
  block = false,
  disabled = false,
  className,
  title,
  type = 'button',
}: BtnProps): React.JSX.Element {
  const classes = ['btn', TONE_CLASS[tone]];
  if (large) classes.push('btn-lg');
  if (small) classes.push('btn-sm');
  if (block) classes.push('btn-block');
  if (className !== undefined) classes.push(className);

  return (
    <button
      className={classes.filter((part) => part !== '').join(' ')}
      disabled={disabled}
      onClick={onClick}
      title={title}
      type={type === 'submit' ? 'submit' : 'button'}
    >
      {icon !== undefined && <Icon name={icon} />}
      {children}
    </button>
  );
}

export type ChipTone =
  | 'neutral'
  | 'accent'
  | 'private'
  | 'peri'
  | 'sage'
  | 'clay'
  | 'line'
  | 'mono';

const CHIP_CLASS: Record<ChipTone, string> = {
  neutral: '',
  accent: 'chip-accent',
  private: 'chip-private',
  peri: 'chip-peri',
  sage: 'chip-sage',
  clay: 'chip-clay',
  line: 'chip-line',
  mono: 'chip-mono',
};

export interface ChipProps {
  readonly children: ReactNode;
  readonly tone?: ChipTone;
  readonly icon?: IconName;
  readonly className?: string;
  readonly title?: string;
}

export function Chip({
  children,
  tone = 'neutral',
  icon,
  className,
  title,
}: ChipProps): React.JSX.Element {
  const classes = ['chip', CHIP_CLASS[tone]];
  if (className !== undefined) classes.push(className);
  return (
    <span className={classes.filter((part) => part !== '').join(' ')} title={title}>
      {icon !== undefined && <Icon name={icon} />}
      {children}
    </span>
  );
}

/** The interpunct between meta items. Decorative, so it is hidden from a screen reader. */
export function Sep(): React.JSX.Element {
  return (
    <span aria-hidden="true" className="dot-sep">
      ·
    </span>
  );
}

// -------------------------------------------------------------------------------------------
// The inheritance marker
// -------------------------------------------------------------------------------------------

export interface InheritanceMarkProps {
  /** Where the value came from: set on this group, inherited from an ancestor, or the default. */
  readonly source: 'set' | 'inherited' | 'default';
  /** The ancestor's name, when `inherited`. */
  readonly from?: string | null;
}

/**
 * "Set here", or "from _Dreams_".
 *
 * Whether a value is inherited or set here is what decides whether changing the parent will move
 * it, which is the one question a settings screen with a cascade has to answer without being
 * asked. A solid accent pill means *this group owns it*; a dashed outline means *this is
 * somebody else's decision, showing through*.
 */
export function InheritanceMark({ source, from }: InheritanceMarkProps): React.JSX.Element {
  if (source === 'set') {
    return <span className="inh inh-here">Set here</span>;
  }
  if (source === 'inherited' && from !== null && from !== undefined && from !== '') {
    return (
      <span className="inh inh-from">
        from <Text value={from} />
      </span>
    );
  }
  return <span className="inh inh-from">Default</span>;
}

// -------------------------------------------------------------------------------------------
// Switch, segmented, option strip
// -------------------------------------------------------------------------------------------

export interface SwitchProps {
  readonly checked: boolean;
  readonly onChange: (next: boolean) => void;
  /** The accessible name. Visually the label is the row; this is what a screen reader says. */
  readonly label: string;
  readonly disabled?: boolean;
}

export function Switch({
  checked,
  onChange,
  label,
  disabled = false,
}: SwitchProps): React.JSX.Element {
  return (
    // The accessible name is an attribute, not a visually-hidden text node. A hidden node would
    // put the row's own label into the DOM twice, which reads as a duplicate to anything walking
    // the text — including a test, which is how this was found.
    <button
      aria-checked={checked}
      aria-label={label}
      className="switch"
      disabled={disabled}
      onClick={() => onChange(!checked)}
      role="switch"
      type="button"
    />
  );
}

export interface SegmentedOption<T extends string> {
  readonly value: T;
  readonly label: string;
}

export interface SegmentedProps<T extends string> {
  readonly options: readonly SegmentedOption<T>[];
  readonly value: T;
  readonly onChange: (next: T) => void;
  readonly wide?: boolean;
  readonly label: string;
}

/** An inline pill track; the selected item gets a `--bg` chip. Theme, density, and filters. */
export function Segmented<T extends string>({
  options,
  value,
  onChange,
  wide = false,
  label,
}: SegmentedProps<T>): React.JSX.Element {
  return (
    /*
     * `<fieldset>` would bring UA chrome and a `<legend>` that has to be hidden again, for no
     * gain: `role="group"` with a label conveys exactly the same thing to a screen reader without
     * fighting the pill track's shape.
     */
    // biome-ignore lint/a11y/useSemanticElements: a fieldset cannot be a pill track
    <div aria-label={label} className={wide ? 'seg wide' : 'seg'} role="group">
      {options.map((option) => (
        <button
          aria-pressed={option.value === value}
          key={option.value}
          onClick={() => onChange(option.value)}
          type="button"
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

/**
 * The inline option strip a setting row expands into.
 *
 * Never a modal and never a native `<select>`: a `<select>` on a phone hands the whole decision
 * to an OS widget that cannot show which option is inherited, and a modal for a one-tap choice is
 * three interactions where there should be one.
 */
export function OptionStrip<T extends string>({
  options,
  value,
  onChange,
  label,
}: SegmentedProps<T>): React.JSX.Element {
  return (
    // biome-ignore lint/a11y/useSemanticElements: see Segmented — same reasoning, same shape
    <div aria-label={label} className="setopts" role="group">
      {options.map((option) => (
        <button
          aria-pressed={option.value === value}
          className="opt"
          key={option.value}
          onClick={() => onChange(option.value)}
          type="button"
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

// -------------------------------------------------------------------------------------------
// Sheet
// -------------------------------------------------------------------------------------------

export interface SheetProps {
  readonly title: string;
  readonly sub?: ReactNode;
  readonly children: ReactNode;
  readonly footer?: ReactNode;
  readonly onClose: () => void;
}

/**
 * A centred dialog at ≥901px and a bottom sheet at ≤900px, from one piece of markup.
 *
 * The focus handling is the part worth keeping: focus moves into the sheet on open and returns to
 * whatever opened it on close, so a keyboard user is never dropped at the top of the document
 * after dismissing something.
 */
/**
 * Everything inside `root` that a Tab can reach, in tab order.
 *
 * `disabled` and `[hidden]` are excluded by the selector; the zero-size check is what removes
 * controls that are in the DOM but not on screen — the move picker renders a row per group and a
 * closed section's rows would otherwise be tab stops nobody can see.
 */
function focusableWithin(root: HTMLElement): HTMLElement[] {
  const selector =
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"]),[contenteditable="true"]';
  return [...root.querySelectorAll<HTMLElement>(selector)].filter(
    (element) =>
      element.getAttribute('aria-hidden') !== 'true' &&
      (element.offsetWidth > 0 || element.offsetHeight > 0 || element.getClientRects().length > 0),
  );
}

/**
 * The last thing a pointer went down on.
 *
 * A sheet is often opened from something that is not focusable — a row, a card, a tab-bar button
 * that blurs itself — so by the time the sheet mounts, `document.activeElement` is `<body>` and
 * there is nothing to hand focus back to. This is the fallback: not where focus *was*, but where
 * the person *was*, which is the same answer for every purpose that matters here.
 */
let lastPointerTarget: HTMLElement | null = null;
if (typeof globalThis.document !== 'undefined') {
  globalThis.document.addEventListener(
    'pointerdown',
    (event) => {
      lastPointerTarget = event.target instanceof HTMLElement ? event.target : null;
    },
    { capture: true },
  );
}

export function Sheet({ title, sub, children, footer, onClose }: SheetProps): React.JSX.Element {
  const sheetRef = useRef<HTMLDivElement | null>(null);
  const returnTo = useRef<HTMLElement | null>(null);
  const titleId = useId();

  /*
   * Take focus, and give it back.
   *
   * Both halves were broken and both are the same bug in different clothes: a dialog is only a
   * dialog if the keyboard is inside it and comes back out where it went in.
   *
   * The opener is captured on the way in. `document.activeElement` is `<body>` whenever the sheet
   * was opened by clicking something that is not itself focusable — a row, a card — so the click
   * target is remembered as a fallback: `:focus-visible` will not fire on it, but Tab will carry
   * on from the right place instead of restarting at the top of the document.
   */
  useEffect(() => {
    const document_ = globalThis.document;
    const active = document_?.activeElement;
    returnTo.current =
      active instanceof HTMLElement && active !== document_.body ? active : lastPointerTarget;

    sheetRef.current?.focus();

    return () => {
      const previous = returnTo.current;
      // The opener may have been unmounted while the sheet was open — a row that was deleted, a
      // screen that navigated away underneath. Focusing a detached node silently drops focus onto
      // `<body>`, which is the failure being fixed, so it is checked first.
      if (previous !== null && document_?.contains(previous) === true) {
        previous.focus({ preventScroll: true });
        return;
      }
      // Nothing to go back to: the top of the current screen is the honest answer, and it is
      // always there because every screen's `<h1>` carries `tabIndex={-1}`.
      const heading = document_?.querySelector<HTMLElement>('[data-rn] h1.ptitle');
      heading?.focus({ preventScroll: true });
    };
  }, []);

  /*
   * Escape closes, and Tab cannot leave.
   *
   * Without the trap, tabbing past the last control walked straight into the page behind an
   * `aria-modal="true"` dialog — the content a screen reader has already been told is not there.
   * The wrap is done by hand rather than with `inert` on the rest of the page, because the sheet
   * is a sibling of the whole app subtree and marking that inert would fight React's ownership of
   * those nodes on every render.
   */
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent): void {
      if (event.key === 'Escape') {
        event.stopPropagation();
        onClose();
        return;
      }
      if (event.key !== 'Tab') return;

      const sheet = sheetRef.current;
      if (sheet === null) return;

      const stops = focusableWithin(sheet);
      if (stops.length === 0) {
        // A sheet with nothing to focus still must not leak; the sheet itself holds the keyboard.
        event.preventDefault();
        sheet.focus();
        return;
      }

      const first = stops[0] as HTMLElement;
      const last = stops[stops.length - 1] as HTMLElement;
      const active = globalThis.document?.activeElement;

      // Focus sitting on the sheet itself (where it lands on open) is treated as "before the
      // first stop", so the first Tab goes to the first control rather than out of the dialog.
      if (!sheet.contains(active instanceof Node ? active : null)) {
        event.preventDefault();
        (event.shiftKey ? last : first).focus();
        return;
      }
      if (event.shiftKey && (active === first || active === sheet)) {
        event.preventDefault();
        last.focus();
        return;
      }
      if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    }
    globalThis.addEventListener('keydown', onKeyDown);
    return () => globalThis.removeEventListener('keydown', onKeyDown);
  }, [onClose]);

  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: the scrim duplicates Escape, handled above
    // biome-ignore lint/a11y/noStaticElementInteractions: the scrim is a click target, not a control
    <div className="scrim" onClick={onClose}>
      {/* biome-ignore lint/a11y/useKeyWithClickEvents: Escape closes; this only stops the scrim */}
      <div
        aria-labelledby={titleId}
        aria-modal="true"
        className="sheet"
        onClick={(event) => event.stopPropagation()}
        ref={sheetRef}
        role="dialog"
        tabIndex={-1}
      >
        <div className="sheet-head">
          <div>
            <div className="sheet-title" id={titleId}>
              {title}
            </div>
            {sub !== undefined && <div className="sheet-sub">{sub}</div>}
          </div>
          <button className="iconbtn" onClick={onClose} title="Close" type="button">
            <Icon name="x" />
            <span className="sr">Close</span>
          </button>
        </div>
        <div className="sheet-body">{children}</div>
        {footer !== undefined && <div className="sheet-foot">{footer}</div>}
      </div>
    </div>
  );
}

// -------------------------------------------------------------------------------------------
// Callout, panel, glyph
// -------------------------------------------------------------------------------------------

export interface CalloutProps {
  readonly children: ReactNode;
  readonly icon?: IconName;
  readonly tone?: 'clay' | 'quiet' | 'brass';
  readonly className?: string;
}

export function Callout({
  children,
  icon = 'warn',
  tone = 'clay',
  className,
}: CalloutProps): React.JSX.Element {
  const classes = ['callout'];
  if (tone === 'quiet') classes.push('callout-quiet');
  if (tone === 'brass') classes.push('callout-brass');
  if (className !== undefined) classes.push(className);
  return (
    <div className={classes.join(' ')}>
      <Icon name={icon} />
      <div>{children}</div>
    </div>
  );
}

/**
 * A group's or a note's mark: an inline icon, or any character a person typed, emoji included.
 *
 * One renderer for both, and the slot is sized for one or two characters and clipped there. A
 * paste of a paragraph into the icon field is clipped rather than allowed to widen a row — which
 * is the same rule as everywhere else: **nothing a person can type may push the page sideways.**
 */
export function Glyph({ icon }: { readonly icon: string | null }): React.JSX.Element {
  if (icon === null || icon === '') {
    return (
      <span className="gl">
        <Icon name="box" />
      </span>
    );
  }
  if (icon.startsWith('i:')) {
    return (
      <span className="gl">
        <Icon name={icon.slice(2) as IconName} />
      </span>
    );
  }
  // Anything else is treated as text the person typed. Split by code point so an emoji made of
  // several units is not sliced through the middle into replacement characters.
  const characters = [...icon].slice(0, 2).join('');
  return (
    <span className="gl">
      <span className="gl-char">{characters}</span>
    </span>
  );
}

// -------------------------------------------------------------------------------------------
// Setting rows
// -------------------------------------------------------------------------------------------

export interface SetGroupProps {
  readonly title: string;
  readonly note?: ReactNode;
  readonly children: ReactNode;
}

/**
 * `<h2>`, not `<h3>`.
 *
 * The page title is the `<h1>`; a settings family is the next level down and there is nothing in
 * between. It was an `<h3>`, which made Settings, Group settings and New group all jump H1 → H3 —
 * and a heading level skipped is a level a screen-reader user reasonably assumes they have missed
 * something at. The size on screen does not change: `.setgroup-head` styles the heading by
 * position, not by tag, and small uppercase is what a section label looks like here regardless of
 * its level.
 */
export function SetGroup({ title, note, children }: SetGroupProps): React.JSX.Element {
  return (
    <section className="setgroup">
      <div className="setgroup-head">
        <h2>{title}</h2>
        {note !== undefined && <p>{note}</p>}
      </div>
      <div className="setlist">{children}</div>
    </section>
  );
}

export interface SetRowProps {
  readonly label: string;
  readonly help?: ReactNode;
  /** The current value, read back as a word. */
  readonly value?: ReactNode;
  readonly onClick?: () => void;
  readonly expanded?: boolean;
  readonly children?: ReactNode;
  readonly danger?: boolean;
}

/**
 * Label and help on the left, the current value **as a word** on the right, chevron.
 *
 * Tapping expands an inline option strip underneath. A settings screen that reads back as
 * sentences is what stops fifteen settings feeling like a control panel.
 */
export function SetRow({
  label,
  help,
  value,
  onClick,
  expanded,
  children,
  danger = false,
}: SetRowProps): React.JSX.Element {
  const body = (
    <>
      <span className="setrow-main">
        <span className={danger ? 'setrow-label danger' : 'setrow-label'}>{label}</span>
        {help !== undefined && <span className="setrow-help">{help}</span>}
      </span>
      {value !== undefined && (
        <span className="setrow-value">
          {value}
          {onClick !== undefined && <Icon className="chev" name="chev" />}
        </span>
      )}
    </>
  );

  if (onClick === undefined) {
    return <div className="setrow">{body}</div>;
  }

  return (
    <div>
      <button aria-expanded={expanded} className="setrow" onClick={onClick} type="button">
        {body}
      </button>
      {expanded === true && children}
    </div>
  );
}

/** A setting whose control is a switch: the row never expands, the switch is the whole answer. */
export function SetSwitchRow({
  label,
  help,
  checked,
  onChange,
  mark,
}: {
  readonly label: string;
  readonly help?: ReactNode;
  readonly checked: boolean;
  readonly onChange: (next: boolean) => void;
  readonly mark?: ReactNode;
}): React.JSX.Element {
  return (
    <div className="setrow">
      <span className="setrow-main">
        <span className="setrow-label">{label}</span>
        {help !== undefined && <span className="setrow-help">{help}</span>}
      </span>
      {mark !== undefined && <span className="setrow-value">{mark}</span>}
      <Switch checked={checked} label={label} onChange={onChange} />
    </div>
  );
}

/** A setting whose control is a text field. Stacked, because a path needs the width. */
export function SetTextRow({
  label,
  help,
  value,
  onChange,
  onCommit,
  placeholder,
  mono = false,
}: {
  readonly label: string;
  readonly help?: ReactNode;
  readonly value: string;
  readonly onChange: (next: string) => void;
  /**
   * Called when the person has finished with the field — on blur and on Enter.
   *
   * A settings field that only saves through a button somewhere else is a field that throws work
   * away, because leaving a field is how people say they are done with it.
   */
  readonly onCommit?: () => void;
  readonly placeholder?: string;
  readonly mono?: boolean;
}): React.JSX.Element {
  const id = useId();
  return (
    <div className="setrow setrow-stack">
      <label className="setrow-label" htmlFor={id}>
        {label}
      </label>
      {help !== undefined && <span className="setrow-help spaced">{help}</span>}
      <input
        className={mono ? 'field field-mono' : 'field'}
        id={id}
        onBlur={onCommit}
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={(event) => {
          // Blurring runs `onCommit` through the handler above, so Enter and clicking away are
          // one path rather than two that can drift apart.
          if (event.key === 'Enter') event.currentTarget.blur();
        }}
        placeholder={placeholder}
        value={value}
      />
    </div>
  );
}

// -------------------------------------------------------------------------------------------
// Focus helpers
// -------------------------------------------------------------------------------------------

/**
 * Move focus to the top of a screen when the route changes.
 *
 * Without this a keyboard user who follows a row into a group is still focused where the row
 * used to be, and their next Tab starts from a place that no longer exists.
 */
export function useFocusOnRouteChange(key: string): (element: HTMLElement | null) => void {
  const ref = useRef<HTMLElement | null>(null);
  const seen = useRef<string | null>(null);

  useEffect(() => {
    if (seen.current === key) return;
    seen.current = key;
    ref.current?.focus();
  }, [key]);

  return useCallback((element: HTMLElement | null) => {
    ref.current = element;
  }, []);
}
