import type { Group, GroupSettings, HandoffProgress, ProjectStatus } from '@rosie-notes/schema';
import { isStale, PROJECT_STATUSES } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import {
  PROJECT_STATUS_BLURB,
  PROJECT_STATUS_ICON,
  PROJECT_STATUS_LABEL,
  plural,
  STALE_BLURB,
  STALE_LABEL,
} from './labels';
import { Chip, type ChipTone, Segmented } from './primitives';

/**
 * Reading a shelf of projects at a glance.
 *
 * Rose: *"Possibly being able to replace me doing things like this where i have many project
 * files opened at once"*. A dozen editor windows exist because there is nowhere else that says
 * which project is which — so everything here is optimised for the *list*, not for the project
 * screen: one chip per row, one row of filters above them, and nothing that has to be maintained.
 *
 * Three rules this module holds to:
 *
 * 1. **Stale is derived, never stored.** `isStale` runs against the group's last change every
 *    time the row paints. Making it a sixth status would mean asking Rose to hand-maintain a flag
 *    meaning "I have not touched this lately", which is the bookkeeping the feature removes.
 * 2. **Colour reinforces, it never carries.** Every chip is a word plus a glyph. Take all the
 *    colour away and the list still reads.
 * 3. **The filter is client-side.** The tree is already loaded whole (`useGroups`), a person has
 *    tens of groups rather than thousands, and a filter that needs a round trip is a filter with
 *    a spinner in it.
 */

// -------------------------------------------------------------------------------------------
// The facts a card shows
// -------------------------------------------------------------------------------------------

/** What a group's row says about it as a project: the status it is in, and whether it has gone quiet. */
export interface ProjectFact {
  /** `null` for a group that is not a code project — most of them. */
  readonly status: ProjectStatus | null;
  readonly stale: boolean;
}

export const NOT_A_PROJECT: ProjectFact = { status: null, stale: false };

/**
 * Read a group's project state out of its resolved settings.
 *
 * `lastActivity` is the group's own `updatedAt`, which is the best signal the tree carries: notes
 * are not loaded here, so "when did anything in this project last change" is not available
 * without a request per row. An unparseable timestamp reads as *recent* rather than as stale —
 * a neglect badge shown because a date failed to parse is worse than no badge at all.
 */
export function projectFact(
  settings: GroupSettings,
  lastActivity: string,
  now?: Date,
): ProjectFact {
  if (!settings.codeProject.enabled) {
    return NOT_A_PROJECT;
  }
  const status = settings.codeProject.status;
  const at = Date.parse(lastActivity);
  return {
    status,
    stale: Number.isNaN(at) ? false : isStale(status, new Date(at), now),
  };
}

// -------------------------------------------------------------------------------------------
// Filtering
// -------------------------------------------------------------------------------------------

/** `all`, one of the five statuses, or the derived `stale`. One choice at a time. */
export type StatusFilter = 'all' | ProjectStatus | 'stale';

export function matchesStatusFilter(filter: StatusFilter, fact: ProjectFact): boolean {
  if (filter === 'all') return true;
  if (filter === 'stale') return fact.stale;
  return fact.status === filter;
}

export interface StatusFacet {
  readonly value: StatusFilter;
  readonly label: string;
  readonly count: number;
}

/**
 * The chips worth offering, given what is actually in this list.
 *
 * Only statuses that occur get one: a filter for a state nothing is in can do exactly one thing,
 * which is empty the screen. `Stale` comes last and only when something is — it is a fact derived
 * from the others rather than a sixth state sitting beside them.
 */
export function statusFacets(facts: readonly ProjectFact[]): StatusFacet[] {
  const facets: StatusFacet[] = [{ value: 'all', label: 'All', count: facts.length }];

  for (const status of PROJECT_STATUSES) {
    const count = facts.filter((fact) => fact.status === status).length;
    if (count > 0) {
      facets.push({ value: status, label: PROJECT_STATUS_LABEL[status], count });
    }
  }

  const stale = facts.filter((fact) => fact.stale).length;
  if (stale > 0) {
    facets.push({ value: 'stale', label: STALE_LABEL, count: stale });
  }

  return facets;
}

export interface ProjectFilter {
  /** The groups that survive the current choice, in the order they were given. */
  readonly groups: readonly Group[];
  readonly facets: readonly StatusFacet[];
  readonly value: StatusFilter;
  readonly choose: (next: StatusFilter) => void;
  /** How many of the given groups are code projects at all. */
  readonly projects: number;
  factOf(groupId: string): ProjectFact;
}

/**
 * Hold a status filter over a list of groups the app already has.
 *
 * Deliberately a hook over a list rather than app-wide state: home filters its top-level groups
 * and a group screen filters its subgroups, and the two are separate questions. Filtering to
 * "Active" at home should not still be in force three screens down.
 */
export function useProjectFilter(groups: readonly Group[]): ProjectFilter {
  const tree = useGroups();
  const [chosen, setChosen] = useState<StatusFilter>('all');

  const facts = useMemo(() => {
    const map = new Map<string, ProjectFact>();
    for (const group of groups) {
      const id = group.id as string;
      map.set(id, projectFact(tree.settingsOf(id).effective, group.updatedAt));
    }
    return map;
  }, [groups, tree]);

  const facets = useMemo(() => statusFacets([...facts.values()]), [facts]);

  // A choice whose chip has gone — the last WIP project was finished while the filter was on —
  // falls back to showing everything. The alternative is an empty screen with its reason no
  // longer on it.
  const value = facets.some((facet) => facet.value === chosen) ? chosen : 'all';

  const visible = useMemo(
    () =>
      groups.filter((group) =>
        matchesStatusFilter(value, facts.get(group.id as string) ?? NOT_A_PROJECT),
      ),
    [groups, facts, value],
  );

  const projects = useMemo(
    () => [...facts.values()].filter((fact) => fact.status !== null).length,
    [facts],
  );

  return {
    groups: visible,
    facets,
    value,
    choose: setChosen,
    projects,
    factOf: (groupId) => facts.get(groupId) ?? NOT_A_PROJECT,
  };
}

/**
 * The filter row, or nothing.
 *
 * It hides itself below two projects, and below two states to choose between: a control whose
 * every setting shows the same rows is not a filter, it is a label — and one more thing to read
 * on a screen whose whole purpose is being quick to read.
 */
export function StatusFilterBar({
  filter,
  label = 'Filter projects by status',
}: {
  readonly filter: ProjectFilter;
  readonly label?: string;
}): React.JSX.Element | null {
  if (filter.projects < 2 || filter.facets.length < 3) {
    return null;
  }
  return (
    <div className="statusbar">
      <Segmented
        label={label}
        onChange={filter.choose}
        options={filter.facets.map((facet) => ({
          value: facet.value,
          label: `${facet.label} ${facet.count}`,
        }))}
        value={filter.value}
      />
    </div>
  );
}

// -------------------------------------------------------------------------------------------
// The chips
// -------------------------------------------------------------------------------------------

/**
 * Which hue reinforces which state.
 *
 * `brass` is absent and always will be: it is the note lock, and a project chip that borrowed it
 * would make "locked" and "in progress" read as the same kind of thing. `clay` is absent for the
 * same reason from the other end — it means danger, and none of these are.
 */
const STATUS_TONE: Record<ProjectStatus, ChipTone> = {
  active: 'accent',
  wip: 'peri',
  tbs: 'neutral',
  done: 'sage',
  wont_do: 'line',
};

export function ProjectStatusChip({
  status,
}: {
  readonly status: ProjectStatus;
}): React.JSX.Element {
  return (
    <Chip
      icon={PROJECT_STATUS_ICON[status]}
      title={PROJECT_STATUS_BLURB[status]}
      tone={STATUS_TONE[status]}
    >
      {PROJECT_STATUS_LABEL[status]}
    </Chip>
  );
}

/**
 * "Stale" — the one badge nobody sets.
 *
 * Outlined rather than filled, and carried by the warning glyph rather than by a hue. There is no
 * colour left in the system that could shout here without stealing a meaning that is already
 * spoken for, and a triangle among words catches the eye anyway.
 */
export function StaleChip(): React.JSX.Element {
  return (
    <Chip icon="warn" title={STALE_BLURB} tone="line">
      {STALE_LABEL}
    </Chip>
  );
}

// -------------------------------------------------------------------------------------------
// Progress
// -------------------------------------------------------------------------------------------

/**
 * How far a project has got, from the handoff set it names.
 *
 * The bar is `aria-hidden` and the count beside it is the accessible content, which is the honest
 * arrangement: "9 of 14 done" is the fact, and the bar is a picture of it. A `role="progressbar"`
 * here would announce a percentage twice and say less each time.
 *
 * Returns nothing for a set with no countable tasks. A project that pushed a `STATE.md` and no
 * `TASKS.md` is a real and ordinary thing, and "0 of 0 done" is a worse answer than the note
 * count the row already carries.
 */
export function ProjectProgress({
  progress,
}: {
  readonly progress: HandoffProgress;
}): React.JSX.Element | null {
  if (progress.total === 0) {
    return null;
  }
  const finished = progress.done === progress.total;
  return (
    <span
      className={finished ? 'prog prog-done' : 'prog'}
      title={`${plural(progress.done, 'task')} done of ${progress.total}, ${progress.inProgress} being worked on, ${progress.blocked} blocked.`}
    >
      <span aria-hidden="true" className="prog-track">
        <span className="prog-fill" style={{ width: `${progress.percent}%` }} />
      </span>
      <span>
        {progress.done}/{progress.total} done
      </span>
    </span>
  );
}
