import type { HandoffTask, HandoffTaskStatus } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { useHandoffProject } from '../hooks/use-handoff';
import { Callout } from './primitives';

/**
 * A project's todo list, read from its handoff set.
 *
 * The card overview says *how far*; this says *what*. It is deliberately a **reader, not an
 * editor**: the set on disk is the source of truth, several agents edit it at once, and a second
 * writer through a web form is exactly the collision the file layout was designed to avoid. What
 * this screen is for is the thing Rose asked for — seeing where a project is without opening it —
 * so it optimises for reading a list at a glance.
 *
 * Sections keep their order from the file. That is not cosmetic: "the next thing to do" is defined
 * as the first not-started task in file order, so a set that puts its urgent section first gets the
 * right answer for free, and re-sorting here would quietly disagree with the tool.
 */

const STATUS_WORD: Readonly<Record<HandoffTaskStatus, string>> = {
  not_started: 'To do',
  assigned: 'Assigned',
  in_progress: 'In progress',
  done: 'Done',
  blocked: 'Blocked',
  dropped: 'Dropped',
};

/**
 * A glyph as well as a word, never colour alone.
 *
 * The same rule the status chips follow: someone who cannot separate two hues still gets the right
 * answer, because the meaning is carried by something that is not the hue.
 */
const STATUS_MARK: Readonly<Record<HandoffTaskStatus, string>> = {
  not_started: '○',
  assigned: '◔',
  in_progress: '◑',
  done: '●',
  blocked: '⊘',
  dropped: '—',
};

export interface ProjectProgressProps {
  /** The handoff slug the group names, or null if it names none. */
  readonly project: string | null;
}

export function ProjectProgress({ project }: ProjectProgressProps): React.JSX.Element | null {
  const state = useHandoffProject(project);
  // Finished work is the bulk of a mature set and the least useful thing on screen, so it starts
  // collapsed — but the count stays visible, because hiding it entirely reads as "not done".
  const [showDone, setShowDone] = useState(false);

  const sections = useMemo(() => {
    if (state.set === null) return [];
    const order: string[] = [];
    const bySection = new Map<string, HandoffTask[]>();
    for (const task of state.set.tasks) {
      if (!bySection.has(task.section)) {
        bySection.set(task.section, []);
        order.push(task.section);
      }
      bySection.get(task.section)?.push(task);
    }
    return order.map((name) => ({ name, tasks: bySection.get(name) ?? [] }));
  }, [state.set]);

  if (project === null) return null;

  if (state.loading) {
    return <p className="setrow-help">Reading {project}…</p>;
  }

  // Not an error. Most projects never push a set, and saying "no progress" would be a claim about
  // the project rather than about what we know.
  if (state.missing) {
    return (
      <Callout icon="eye" tone="quiet">
        <b>{project}</b> has no handoff docs pushed yet. Run <code>handoff push</code> in the
        project to see its tasks here.
      </Callout>
    );
  }

  if (state.set === null) {
    return (
      <Callout icon="warn" tone="clay">
        Could not read {project}. Its tasks are on the server; this is a connection problem, not a
        lost list.
      </Callout>
    );
  }

  const { progress, tasks, lastWorkedOn } = state.set;
  const open = tasks.filter((t) => t.status !== 'done' && t.status !== 'dropped');

  return (
    <div style={{ display: 'grid', gap: 14 }}>
      <div>
        <div
          aria-hidden="true"
          style={{
            height: 8,
            borderRadius: 999,
            background: 'var(--surface-2)',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              width: `${progress.percent}%`,
              height: '100%',
              background: 'var(--accent-solid)',
            }}
          />
        </div>
        {/* The bar is decoration; this sentence is the accessible content. */}
        <p className="setrow-help" style={{ marginTop: 6 }}>
          {progress.done} of {progress.total} done ({progress.percent}%)
          {progress.blocked > 0 && `, ${progress.blocked} blocked`}
          {progress.inProgress > 0 && `, ${progress.inProgress} underway`}
          {lastWorkedOn !== null && ` · last worked on ${lastWorkedOn}`}
        </p>
      </div>

      {open.length === 0 && (
        <Callout icon="check" tone="quiet">
          Nothing open. Every task in this project is done or dropped.
        </Callout>
      )}

      {sections.map((section) => {
        const visible = showDone
          ? section.tasks
          : section.tasks.filter((t) => t.status !== 'done' && t.status !== 'dropped');
        if (visible.length === 0) return null;
        return (
          <section key={section.name}>
            <h3 className="eyebrow">{section.name || 'Tasks'}</h3>
            <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'grid', gap: 2 }}>
              {visible.map((task) => (
                <li className="row" key={task.id} style={{ alignItems: 'baseline', gap: 8 }}>
                  <span aria-hidden="true">{STATUS_MARK[task.status]}</span>
                  <span className="eyebrow" style={{ minWidth: '5.5em' }}>
                    {STATUS_WORD[task.status]}
                  </span>
                  <span style={{ flex: 1 }}>
                    <b>{task.id}</b> {stripMarkup(task.text)}
                  </span>
                  {task.owner !== null && <span className="chip">@{task.owner}</span>}
                </li>
              ))}
            </ul>
          </section>
        );
      })}

      {progress.done > 0 && (
        <button className="btn" onClick={() => setShowDone((v) => !v)} type="button">
          {showDone ? 'Hide' : 'Show'} {progress.done} finished
        </button>
      )}
    </div>
  );
}

/**
 * Task text is markdown written for a file, not for this screen.
 *
 * Only the two markers that appear in nearly every line are removed — `**bold**` and `` `code` ``.
 * Rendering it as real markdown would be worse: a task body can contain a table or a fenced block,
 * and a list of one-liners is the point.
 */
function stripMarkup(text: string): string {
  return text.replaceAll('**', '').replaceAll('`', '');
}
