import { isClientError, type NotesClientError } from '@rosie-notes/client';
import type { IncomingShare, NoteId } from '@rosie-notes/schema';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * `GET /v1/shares/incoming`, as a screen pages through it.
 *
 * There is no local cache for this the way there is for the account's own notes: a note shared
 * with you is never written into the offline store (`NotesStore` is scoped to notes this account
 * owns), so unlike `useNoteQuery` there is nothing to fall back to when the server cannot be
 * reached. A failed request is a plain error state with a retry, the same shape `useTags` and
 * `useCollections` already use for their own un-cached listings.
 */

export interface IncomingSharesState {
  readonly shares: readonly IncomingShare[];
  readonly loading: boolean;
  readonly error: NotesClientError | null;
  readonly hasMore: boolean;
}

export interface IncomingSharesResult extends IncomingSharesState {
  reload(): void;
  loadMore(): void;
}

const EMPTY: IncomingSharesState = { shares: [], loading: true, error: null, hasMore: false };

/** One page's worth, kept intentionally small — see `MAX_PAGE_SIZE` in `@rosie-notes/schema`. */
const PAGE_SIZE = 100;

export function useIncomingShares(writableOnly = false): IncomingSharesResult {
  const workspace = useWorkspace();
  const [state, setState] = useState<IncomingSharesState>(EMPTY);
  const [nonce, setNonce] = useState(0);
  const cursorRef = useRef<string | null>(null);

  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    let cancelled = false;
    cursorRef.current = null;
    setState((previous) => ({ ...previous, loading: true, error: null }));

    void (async () => {
      try {
        const page = await workspace.client.shares.incoming({ writableOnly, limit: PAGE_SIZE });
        if (cancelled) return;
        cursorRef.current = page.nextCursor;
        setState({ shares: page.items, loading: false, error: null, hasMore: page.hasMore });
      } catch (error) {
        if (cancelled) return;
        setState({
          shares: [],
          loading: false,
          error: isClientError(error) ? error : null,
          hasMore: false,
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [workspace, writableOnly, nonce]);

  const reload = useCallback(() => setNonce((value) => value + 1), []);

  const loadMore = useCallback(() => {
    const cursor = cursorRef.current;
    if (cursor === null) {
      return;
    }
    void (async () => {
      try {
        const page = await workspace.client.shares.incoming({
          writableOnly,
          limit: PAGE_SIZE,
          cursor,
        });
        cursorRef.current = page.nextCursor;
        setState((previous) => ({
          ...previous,
          shares: [...previous.shares, ...page.items],
          hasMore: page.hasMore,
        }));
      } catch {
        // The button simply does nothing more; what is already listed stays listed.
      }
    })();
  }, [workspace, writableOnly]);

  return { ...state, reload, loadMore };
}

/**
 * Whether `noteId` is somebody else's note, reached through a share, and if so what this account
 * may do with it.
 *
 * Meant to be called only after the caller already knows the note is not its own — comparing
 * `note.ownerId` against the signed-in user is `NoteView`'s job, cheaply, before this ever fires.
 * There is nothing on `Note` itself that carries the viewer's permission (see `docs/api.md`'s
 * note on `/v1/shares/incoming`: this endpoint is the *only* place that exists), so a foreign
 * note means one extra request — never for a note the account already owns.
 *
 * `undefined` means the check is still in flight, and `null` means it came back empty (no
 * matching grant in the first page, or the request failed outright). Both read the same way to a
 * caller deciding whether an editor is safe to leave writable: **anything short of a confirmed
 * `'write'` grant is read-only.** A stale "yes you may edit" surviving past a revoked grant is a
 * far worse failure than a moment of "why can't I type yet".
 */
export function useIncomingShareFor(noteId: NoteId | null): IncomingShare | null | undefined {
  const workspace = useWorkspace();
  const [share, setShare] = useState<IncomingShare | null | undefined>(undefined);

  useEffect(() => {
    if (noteId === null) {
      setShare(null);
      return;
    }
    let cancelled = false;
    setShare(undefined);
    void workspace.client.shares
      .incoming({ limit: PAGE_SIZE })
      .then((page) => {
        if (cancelled) return;
        setShare(page.items.find((item) => item.note.id === noteId) ?? null);
      })
      .catch(() => {
        if (!cancelled) setShare(null);
      });
    return () => {
      cancelled = true;
    };
  }, [workspace, noteId]);

  return share;
}
